(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("phil-e",[{"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὅρα δή, Πρώταρχε, τίνα λόγον μέλλεις παρὰ Φιλήβου δέχεσθαι νυνὶ καὶ πρὸς τίνα τὸν παρ᾽ ἡμῖν ἀμφισβητεῖν,", "st": "11a"}, {"sp": "N", "t": "ἐὰν μή σοι κατὰ νοῦν ᾖ λεγόμενος. βούλει συγκεφαλαιωσώμεθα ἑκάτερον;", "st": "11b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν.", "st": "11b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> Φίληβος μὲν τοίνυν ἀγαθὸν εἶναί φησι τὸ χαίρειν πᾶσι ζῴοις καὶ τὴν ἡδονὴν καὶ τέρψιν, καὶ ὅσα τοῦ γένους ἐστὶ τούτου σύμφωνα: τὸ δὲ παρ᾽ ἡμῶν ἀμφισβήτημά ἐστι μὴ ταῦτα, ἀλλὰ τὸ φρονεῖν καὶ τὸ νοεῖν καὶ μεμνῆσθαι καὶ τὰ τούτων αὖ συγγενῆ, δόξαν τε ὀρθὴν καὶ ἀληθεῖς λογισμούς, τῆς γε ἡδονῆς ἀμείνω καὶ λῴω γίγνεσθαι σύμπασιν ὅσαπερ", "st": "11b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> αὐτῶν δυνατὰ μεταλαβεῖν: δυνατοῖς δὲ μετασχεῖν ὠφελιμώτατον ἁπάντων εἶναι πᾶσι τοῖς οὖσί τε καὶ ἐσομένοις. μῶν οὐχ οὕτω πως λέγομεν, ὦ Φίληβε, ἑκάτεροι;", "st": "11c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Φίληβος:<\/span> πάντων μὲν οὖν μάλιστα, ὦ Σώκρατες.", "st": "11c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> δέχῃ δὴ τοῦτον τὸν νῦν διδόμενον, ὦ Πρώταρχε, λόγον;", "st": "11c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀνάγκη δέχεσθαι: Φίληβος γὰρ ἡμῖν ὁ καλὸς ἀπείρηκεν.", "st": "11c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> δεῖ δὴ περὶ αὐτῶν τρόπῳ παντὶ τἀληθές πῃ περανθῆναι;", "st": "11c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> δεῖ γὰρ οὖν.", "st": "11d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἴθι δή, πρὸς τούτοις διομολογησώμεθα καὶ τόδε.", "st": "11d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ ποῖον;", "st": "11d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὡς νῦν ἡμῶν ἑκάτερος ἕξιν ψυχῆς καὶ διάθεσιν ἀποφαίνειν τινὰ ἐπιχειρήσει τὴν δυναμένην ἀνθρώποις πᾶσι τὸν βίον εὐδαίμονα παρέχειν. ἆρ᾽ οὐχ οὕτως;", "st": "11d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὕτω μὲν οὖν.", "st": "11d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ὑμεῖς μὲν τὴν τοῦ χαίρειν, ἡμεῖς δ᾽ αὖ τὴν τοῦ φρονεῖν;", "st": "11d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἔστι ταῦτα.", "st": "11d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί δ᾽ ἂν ἄλλη τις κρείττων τούτων φανῇ; μῶν οὐκ,", "st": "11d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἂν μὲν ἡδονῇ μᾶλλον φαίνηται συγγενής, ἡττώμεθα μὲν ἀμφότεροι τοῦ ταῦτα ἔχοντος βεβαίως βίου, κρατεῖ δὲ ὁ τῆς", "st": "11e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἡδονῆς τὸν τῆς φρονήσεως;", "st": "12a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ναί.", "st": "12a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἂν δέ γε φρονήσει, νικᾷ μὲν φρόνησις τὴν ἡδονήν, ἡ δὲ ἡττᾶται; ταῦθ᾽ οὕτως ὁμολογούμενά φατε, ἢ πῶς;", "st": "12a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἐμοὶ γοῦν δοκεῖ.", "st": "12a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί δὲ Φιλήβῳ; τί φῄς;", "st": "12a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Φίληβος:<\/span> ἐμοὶ μὲν πάντως νικᾶν ἡδονὴ δοκεῖ καὶ δόξει: σὺ δέ, Πρώταρχε, αὐτὸς γνώσῃ.", "st": "12a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> παραδούς, ὦ Φίληβε, ἡμῖν τὸν λόγον οὐκ ἂν ἔτι κύριος εἴης τῆς πρὸς Σωκράτη ὁμολογίας ἢ καὶ τοὐναντίον.", "st": "12a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Φίληβος:<\/span> ἀληθῆ λέγεις: ἀλλὰ γὰρ ἀφοσιοῦμαι καὶ μαρτύρομαι νῦν αὐτὴν τὴν θεόν.", "st": "12b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ ἡμεῖς σοι τούτων γε αὐτῶν συμμάρτυρες ἂν εἶμεν, ὡς ταῦτα ἔλεγες ἃ λέγεις. ἀλλὰ δὴ τὰ μετὰ ταῦτα ἑξῆς, ὦ Σώκρατες, ὅμως καὶ μετὰ Φιλήβου ἑκόντος ἢ ὅπως ἂν ἐθέλῃ πειρώμεθα περαίνειν.", "st": "12b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πειρατέον, ἀπ᾽ αὐτῆς δὴ τῆς θεοῦ, ἣν ὅδε Ἀφροδίτην μὲν λέγεσθαί φησι, τὸ δ᾽ ἀληθέστατον αὐτῆς ὄνομα ἡδονὴν εἶναι.", "st": "12b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθότατα.", "st": "12b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ δ᾽ ἐμὸν δέος, ὦ Πρώταρχε, ἀεὶ πρὸς τὰ τῶν θεῶν ὀνόματα οὐκ ἔστι κατ᾽ ἄνθρωπον, ἀλλὰ πέρα τοῦ μεγίστου φόβου. καὶ νῦν τὴν μὲν Ἀφροδίτην, ὅπῃ ἐκείνῃ φίλον, ταύτῃ προσαγορεύω: τὴν δὲ ἡδονὴν οἶδα ὡς ἔστι ποικίλον, καὶ ὅπερ εἶπον, ἀπ᾽ ἐκείνης ἡμᾶς ἀρχομένους ἐνθυμεῖσθαι δεῖ καὶ σκοπεῖν ἥντινα φύσιν ἔχει. ἔστι γάρ, ἀκούειν μὲν οὕτως ἁπλῶς, ἕν τι, μορφὰς δὲ δήπου παντοίας εἴληφε καί τινα τρόπον ἀνομοίους ἀλλήλαις. ἰδὲ γάρ: ἥδεσθαι μέν φαμεν", "st": "12c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὸν ἀκολασταίνοντα ἄνθρωπον, ἥδεσθαι δὲ καὶ τὸν σωφρονοῦντα αὐτῷ τῷ σωφρονεῖν: ἥδεσθαι δ᾽ αὖ καὶ τὸν ἀνοηταίνοντα καὶ ἀνοήτων δοξῶν καὶ ἐλπίδων μεστόν, ἥδεσθαι δ᾽ αὖ τὸν φρονοῦντα αὐτῷ τῷ φρονεῖν: καὶ τούτων τῶν ἡδονῶν ἑκατέρας πῶς ἄν τις ὁμοίας ἀλλήλαις εἶναι λέγων οὐκ ἀνόητος φαίνοιτο ἐνδίκως;", "st": "12d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> εἰσὶ μὲν γὰρ ἀπ᾽ ἐναντίων, ὦ Σώκρατες, αὗται πραγμάτων, οὐ μὴν αὐταί γε ἀλλήλαις ἐναντίαι. πῶς γὰρ", "st": "12d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἡδονῇ γε ἡδονὴ [μὴ] οὐχ ὁμοιότατον ἂν εἴη, τοῦτο αὐτὸ ἑαυτῷ, πάντων χρημάτων;", "st": "12e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ γὰρ χρῶμα, ὦ δαιμόνιε, χρώματι: κατά γε αὐτὸ τοῦτο οὐδὲν διοίσει τὸ χρῶμα εἶναι πᾶν, τό γε μὴν μέλαν τῷ λευκῷ πάντες γιγνώσκομεν ὡς πρὸς τῷ διάφορον εἶναι καὶ ἐναντιώτατον ὂν τυγχάνει. καὶ δὴ καὶ σχῆμα σχήματι κατὰ ταὐτόν: γένει μέν ἐστι πᾶν ἕν, τὰ δὲ μέρη τοῖς μέρεσιν", "st": "12e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> αὐτοῦ τὰ μὲν ἐναντιώτατα ἀλλήλοις, τὰ δὲ διαφορότητ᾽ ἔχοντα μυρίαν που τυγχάνει, καὶ πολλὰ ἕτερα οὕτως ἔχονθ᾽ εὑρήσομεν. ὥστε τούτῳ γε τῷ λόγῳ μὴ πίστευε, τῷ πάντα τὰ ἐναντιώτατα ἓν ποιοῦντι. φοβοῦμαι δὲ μή τινας ἡδονὰς ἡδοναῖς εὑρήσομεν ἐναντίας.", "st": "13a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἴσως: ἀλλὰ τί τοῦθ᾽ ἡμῶν βλάψει τὸν λόγον;", "st": "13a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὅτι προσαγορεύεις αὐτὰ ἀνόμοια ὄντα ἑτέρῳ, φήσομεν, ὀνόματι: λέγεις γὰρ ἀγαθὰ πάντ᾽ εἶναι τὰ ἡδέα. τὸ μὲν οὖν μὴ οὐχὶ ἡδέα εἶναι τὰ ἡδέα λόγος οὐδεὶς ἀμφισβητεῖ:", "st": "13a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> κακὰ δ᾽ ὄντα αὐτῶν τὰ πολλὰ καὶ ἀγαθὰ δέ, ὡς ἡμεῖς φαμέν, ὅμως πάντα σὺ προσαγορεύεις ἀγαθὰ αὐτά, ὁμολογῶν ἀνόμοια εἶναι, τῷ λόγῳ εἴ τίς σε προσαναγκάζοι. τί οὖν δὴ ταὐτὸν ἐν ταῖς κακαῖς ὁμοίως καὶ ἐν ἀγαθαῖς ἐνὸν πάσας ἡδονὰς ἀγαθὸν εἶναι προσαγορεύεις;", "st": "13b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς λέγεις, ὦ Σώκρατες; οἴει γάρ τινα συγχωρήσεσθαι, θέμενον ἡδονὴν εἶναι τἀγαθόν, εἶτα ἀνέξεσθαί σου", "st": "13b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγοντος τὰς μὲν εἶναί τινας ἀγαθὰς ἡδονάς, τὰς δέ τινας ἑτέρας αὐτῶν κακάς;", "st": "13c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ᾽ οὖν ἀνομοίους γε φήσεις αὐτὰς ἀλλήλαις εἶναι καί τινας ἐναντίας.", "st": "13c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὔτι καθ᾽ ὅσον γε ἡδοναί.", "st": "13c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πάλιν εἰς τὸν αὐτὸν φερόμεθα λόγον, ὦ Πρώταρχε, οὐδ᾽ ἄρα ἡδονὴν ἡδονῆς διάφορον, ἀλλὰ πάσας ὁμοίας εἶναι φήσομεν, καὶ τὰ παραδείγματα ἡμᾶς τὰ νυνδὴ λεχθέντα οὐδὲν τιτρώσκει, πεισόμεθα δὲ καὶ ἐροῦμεν ἅπερ οἱ πάντων", "st": "13c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> φαυλότατοί τε καὶ περὶ λόγους ἅμα νέοι.", "st": "13d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὰ ποῖα δὴ λέγεις;", "st": "13d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὅτι σε μιμούμενος ἐγὼ καὶ ἀμυνόμενος ἐὰν τολμῶ λέγειν ὡς τὸ ἀνομοιότατόν ἐστι τῷ ἀνομοιοτάτῳ πάντων ὁμοιότατον, ἕξω τὰ αὐτὰ σοὶ λέγειν, καὶ φανούμεθά γε νεώτεροι τοῦ δέοντος, καὶ ὁ λόγος ἡμῖν ἐκπεσὼν οἰχήσεται. πάλιν οὖν αὐτὸν ἀνακρουώμεθα, καὶ τάχ᾽ ἂν ἰόντες εἰς τὰς ὁμοίας ἴσως ἄν πως ἀλλήλοις συγχωρήσαιμεν.", "st": "13d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγε πῶς;", "st": "13e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἐμὲ θὲς ὑπὸ σοῦ πάλιν ἐρωτώμενον, ὦ Πρώταρχε.", "st": "13e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ ποῖον δή;", "st": "13e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> φρόνησίς τε καὶ ἐπιστήμη καὶ νοῦς καὶ πάνθ᾽ ὁπόσα δὴ κατ᾽ ἀρχὰς ἐγὼ θέμενος εἶπον ἀγαθά, διερωτώμενος ὅτι ποτ᾽ ἐστὶν ἀγαθόν, ἆρ᾽ οὐ ταὐτὸν πείσονται τοῦτο ὅπερ ὁ σὸς λόγος;", "st": "13e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς;", "st": "13e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πολλαί τε αἱ συνάπασαι ἐπιστῆμαι δόξουσιν εἶναι καὶ ἀνόμοιοί τινες αὐτῶν ἀλλήλαις: εἰ δὲ καὶ ἐναντίαι πῃ", "st": "13e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> γίγνονταί τινες, ἆρα ἄξιος ἂν εἴην τοῦ διαλέγεσθαι νῦν, εἰ φοβηθεὶς τοῦτο αὐτὸ μηδεμίαν ἀνόμοιον φαίην ἐπιστήμην ἐπιστήμῃ γίγνεσθαι, κἄπειθ᾽ ἡμῖν οὕτως ὁ λόγος ὥσπερ μῦθος ἀπολόμενος οἴχοιτο, αὐτοὶ δὲ σῳζοίμεθα ἐπί τινος ἀλογίας;", "st": "14a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀλλ᾽ οὐ μὴν δεῖ τοῦτο γενέσθαι, πλὴν τοῦ σωθῆναι. τό γε μήν μοι ἴσον τοῦ σοῦ τε καὶ ἐμοῦ λόγου ἀρέσκει: πολλαὶ μὲν ἡδοναὶ καὶ ἀνόμοιοι γιγνέσθων, πολλαὶ δὲ ἐπιστῆμαι καὶ διάφοροι.", "st": "14a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὴν τοίνυν διαφορότητα, ὦ Πρώταρχε, [τοῦ ἀγαθοῦ] τοῦ τ᾽ ἐμοῦ καὶ τοῦ σοῦ μὴ ἀποκρυπτόμενοι, κατατιθέντες δὲ εἰς τὸ μέσον, τολμῶμεν, ἄν πῃ ἐλεγχόμενοι μηνύσωσι πότερον ἡδονὴν τἀγαθὸν δεῖ λέγειν ἢ φρόνησιν ἤ τι τρίτον ἄλλο εἶναι. νῦν γὰρ οὐ δήπου πρός γε αὐτὸ τοῦτο φιλονικοῦμεν, ὅπως ἁγὼ τίθεμαι, ταῦτ᾽ ἔσται τὰ νικῶντα, ἢ ταῦθ᾽ ἃ σύ, τῷ δ᾽ ἀληθεστάτῳ δεῖ που συμμαχεῖν ἡμᾶς ἄμφω.", "st": "14b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> δεῖ γὰρ οὖν.", "st": "14b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τοῦτον τοίνυν τὸν λόγον ἔτι μᾶλλον δι᾽ ὁμολογίας βεβαιωσώμεθα.", "st": "14c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸν ποῖον δή;", "st": "14c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὸν πᾶσι παρέχοντα ἀνθρώποις πράγματα ἑκοῦσί τε καὶ ἄκουσιν ἐνίοις καὶ ἐνίοτε.", "st": "14c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγε σαφέστερον.", "st": "14c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὸν νυνδὴ παραπεσόντα λέγω, φύσει πως πεφυκότα θαυμαστόν. ἓν γὰρ δὴ τὰ πολλὰ εἶναι καὶ τὸ ἓν πολλὰ θαυμαστὸν λεχθέν, καὶ ῥᾴδιον ἀμφισβητῆσαι τῷ τούτων ὁποτερονοῦν τιθεμένῳ.", "st": "14c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἆρ᾽ οὖν λέγεις ὅταν τις ἐμὲ φῇ Πρώταρχον ἕνα", "st": "14c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> γεγονότα φύσει πολλοὺς εἶναι πάλιν τοὺς ἐμὲ καὶ ἐναντίους ἀλλήλοις, μέγαν καὶ σμικρὸν τιθέμενος καὶ βαρὺν καὶ κοῦφον τὸν αὐτὸν καὶ ἄλλα μυρία;", "st": "14d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> σὺ μέν, ὦ Πρώταρχε, εἴρηκας τὰ δεδημευμένα τῶν θαυμαστῶν περὶ τὸ ἓν καὶ πολλά, συγκεχωρημένα δὲ ὡς ἔπος εἰπεῖν ὑπὸ πάντων ἤδη μὴ δεῖν τῶν τοιούτων ἅπτεσθαι, παιδαριώδη καὶ ῥᾴδια καὶ σφόδρα τοῖς λόγοις ἐμπόδια ὑπολαμβανόντων γίγνεσθαι, ἐπεὶ μηδὲ τὰ τοιάδε, ὅταν τις", "st": "14d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἑκάστου τὰ μέλη τε καὶ ἅμα μέρη διελὼν τῷ λόγῳ, πάντα ταῦτα τὸ ἓν ἐκεῖνο εἶναι διομολογησάμενος, ἐλέγχῃ καταγελῶν ὅτι τέρατα διηνάγκασται φάναι, τό τε ἓν ὡς πολλά ἐστι καὶ ἄπειρα, καὶ τὰ πολλὰ ὡς ἓν μόνον.", "st": "14e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> σὺ δὲ δὴ ποῖα, ὦ Σώκρατες, ἕτερα λέγεις, ἃ μήπω συγκεχωρημένα δεδήμευται περὶ τὸν αὐτὸν τοῦτον λόγον;", "st": "14e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὁπόταν, ὦ παῖ, τὸ ἓν μὴ τῶν γιγνομένων τε καὶ ἀπολλυμένων τις τιθῆται, καθάπερ ἀρτίως ἡμεῖς εἴπομεν. ἐνταυθοῖ μὲν γὰρ καὶ τὸ τοιοῦτον ἕν, ὅπερ εἴπομεν νυνδή, συγκεχώρηται τὸ μὴ δεῖν ἐλέγχειν: ὅταν δέ τις ἕνα ἄνθρωπον ἐπιχειρῇ τίθεσθαι καὶ βοῦν ἕνα καὶ τὸ καλὸν ἓν καὶ τὸ ἀγαθὸν ἕν, περὶ τούτων τῶν ἑνάδων καὶ τῶν τοιούτων ἡ πολλὴ σπουδὴ μετὰ διαιρέσεως ἀμφισβήτησις γίγνεται.", "st": "15a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς;", "st": "15a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πρῶτον μὲν εἴ τινας δεῖ τοιαύτας εἶναι μονάδας ὑπολαμβάνειν ἀληθῶς οὔσας: εἶτα πῶς αὖ ταύτας, μίαν ἑκάστην οὖσαν ἀεὶ τὴν αὐτὴν καὶ μήτε γένεσιν μήτε ὄλεθρον προσδεχομένην, ὅμως εἶναι βεβαιότατα μίαν ταύτην; μετὰ δὲ τοῦτ᾽ ἐν τοῖς γιγνομένοις αὖ καὶ ἀπείροις εἴτε διεσπασμένην καὶ πολλὰ γεγονυῖαν θετέον, εἴθ᾽ ὅλην αὐτὴν αὑτῆς χωρίς, ὃ δὴ πάντων ἀδυνατώτατον φαίνοιτ᾽ ἄν, ταὐτὸν καὶ ἓν ἅμα ἐν ἑνί τε καὶ πολλοῖς γίγνεσθαι. ταῦτ᾽ ἔστι τὰ", "st": "15b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> περὶ τὰ τοιαῦτα ἓν καὶ πολλά, ἀλλ᾽ οὐκ ἐκεῖνα, ὦ Πρώταρχε, ἁπάσης ἀπορίας αἴτια μὴ καλῶς ὁμολογηθέντα καὶ εὐπορίας [ἂν] αὖ καλῶς.", "st": "15c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὐκοῦν χρὴ τοῦθ᾽ ἡμᾶς, ὦ Σώκρατες, ἐν τῷ νῦν πρῶτον διαπονήσασθαι;", "st": "15c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὡς γοῦν ἐγὼ φαίην ἄν.", "st": "15c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ πάντας τοίνυν ἡμᾶς ὑπόλαβε συγχωρεῖν σοι τούσδε τὰ τοιαῦτα: Φίληβον δ᾽ ἴσως κράτιστον ἐν τῷ νῦν ἐπερωτῶντα μὴ κινεῖν εὖ κείμενον.", "st": "15c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> εἶεν: πόθεν οὖν τις ταύτης ἄρξηται πολλῆς οὔσης καὶ παντοίας περὶ τὰ ἀμφισβητούμενα μάχης; ἆρ᾽ ἐνθένδε;", "st": "15d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πόθεν;", "st": "15d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> φαμέν που ταὐτὸν ἓν καὶ πολλὰ ὑπὸ λόγων γιγνόμενα περιτρέχειν πάντῃ καθ᾽ ἕκαστον τῶν λεγομένων ἀεί, καὶ πάλαι καὶ νῦν. καὶ τοῦτο οὔτε μὴ παύσηταί ποτε οὔτε ἤρξατο νῦν, ἀλλ᾽ ἔστι τὸ τοιοῦτον, ὡς ἐμοὶ φαίνεται, τῶν λόγων αὐτῶν ἀθάνατόν τι καὶ ἀγήρων πάθος ἐν ἡμῖν: ὁ δὲ πρῶτον αὐτοῦ γευσάμενος ἑκάστοτε τῶν νέων, ἡσθεὶς ὥς", "st": "15d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τινα σοφίας ηὑρηκὼς θησαυρόν, ὑφ᾽ ἡδονῆς ἐνθουσιᾷ τε καὶ πάντα κινεῖ λόγον ἅσμενος, τοτὲ μὲν ἐπὶ θάτερα κυκλῶν καὶ συμφύρων εἰς ἕν, τοτὲ δὲ πάλιν ἀνειλίττων καὶ διαμερίζων, εἰς ἀπορίαν αὑτὸν μὲν πρῶτον καὶ μάλιστα καταβάλλων, δεύτερον δ᾽ ἀεὶ τὸν ἐχόμενον, ἄντε νεώτερος ἄντε πρεσβύτερος ἄντε ἧλιξ ὢν τυγχάνῃ, φειδόμενος οὔτε πατρὸς οὔτε μητρὸς", "st": "15e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὔτε ἄλλου τῶν ἀκουόντων οὐδενός, ὀλίγου δὲ καὶ τῶν ἄλλων ζῴων, οὐ μόνον τῶν ἀνθρώπων, ἐπεὶ βαρβάρων γε οὐδενὸς ἂν φείσαιτο, εἴπερ μόνον ἑρμηνέα ποθὲν ἔχοι.", "st": "16a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἆρ᾽, ὦ Σώκρατες, οὐχ ὁρᾷς ἡμῶν τὸ πλῆθος, ὅτι νέοι πάντες ἐσμέν, καὶ οὐ φοβῇ μή σοι μετὰ Φιλήβου συνεπιθώμεθα, ἐὰν ἡμᾶς λοιδορῇς; ὅμως δὲ μανθάνομεν γὰρ ὃ λέγεις, εἴ τις τρόπος ἔστι καὶ μηχανὴ τὴν μὲν τοιαύτην ταραχὴν ἡμῖν ἔξω τοῦ λόγου εὐμενῶς πως ἀπελθεῖν, ὁδὸν δέ", "st": "16a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τινα καλλίω ταύτης ἐπὶ τὸν λόγον ἀνευρεῖν, σύ τε προθυμοῦ τοῦτο καὶ ἡμεῖς συνακολουθήσομεν εἰς δύναμιν: οὐ γὰρ σμικρὸς ὁ παρὼν λόγος, ὦ Σώκρατες.", "st": "16b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐ γὰρ οὖν, ὦ παῖδες, ὥς φησιν ὑμᾶς προσαγορεύων Φίληβος. οὐ μὴν ἔστι καλλίων ὁδὸς οὐδ᾽ ἂν γένοιτο ἧς ἐγὼ ἐραστὴς μέν εἰμι ἀεί, πολλάκις δέ με ἤδη διαφυγοῦσα ἔρημον καὶ ἄπορον κατέστησεν.", "st": "16b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τίς αὕτη; λεγέσθω μόνον.", "st": "16b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἣν δηλῶσαι μὲν οὐ πάνυ χαλεπόν, χρῆσθαι δὲ παγχάλεπον: πάντα γὰρ ὅσα τέχνης ἐχόμενα ἀνηυρέθη πώποτε διὰ ταύτης φανερὰ γέγονε. σκόπει δὲ ἣν λέγω.", "st": "16c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγε μόνον.", "st": "16c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> θεῶν μὲν εἰς ἀνθρώπους δόσις, ὥς γε καταφαίνεται ἐμοί, ποθὲν ἐκ θεῶν ἐρρίφη διά τινος Προμηθέως ἅμα φανοτάτῳ τινὶ πυρί: καὶ οἱ μὲν παλαιοί, κρείττονες ἡμῶν καὶ ἐγγυτέρω θεῶν οἰκοῦντες, ταύτην φήμην παρέδοσαν, ὡς ἐξ ἑνὸς μὲν καὶ πολλῶν ὄντων τῶν ἀεὶ λεγομένων εἶναι, πέρας δὲ καὶ ἀπειρίαν ἐν αὑτοῖς σύμφυτον ἐχόντων. δεῖν", "st": "16c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὖν ἡμᾶς τούτων οὕτω διακεκοσμημένων ἀεὶ μίαν ἰδέαν περὶ παντὸς ἑκάστοτε θεμένους ζητεῖν — εὑρήσειν γὰρ ἐνοῦσαν ἐὰν οὖν μεταλάβωμεν, μετὰ μίαν δύο, εἴ πως εἰσί, σκοπεῖν, εἰ δὲ μή, τρεῖς ἤ τινα ἄλλον ἀριθμόν, καὶ τῶν ἓν ἐκείνων ἕκαστον πάλιν ὡσαύτως, μέχριπερ ἂν τὸ κατ᾽ ἀρχὰς ἓν μὴ ὅτι ἓν καὶ πολλὰ καὶ ἄπειρά ἐστι μόνον ἴδῃ τις, ἀλλὰ καὶ ὁπόσα: τὴν δὲ τοῦ ἀπείρου ἰδέαν πρὸς τὸ πλῆθος μὴ προσφέρειν πρὶν ἄν τις τὸν ἀριθμὸν αὐτοῦ πάντα κατίδῃ τὸν", "st": "16d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μεταξὺ τοῦ ἀπείρου τε καὶ τοῦ ἑνός, τότε δ᾽ ἤδη τὸ ἓν ἕκαστον τῶν πάντων εἰς τὸ ἄπειρον μεθέντα χαίρειν ἐᾶν. οἱ μὲν οὖν θεοί, ὅπερ εἶπον, οὕτως ἡμῖν παρέδοσαν σκοπεῖν καὶ μανθάνειν καὶ διδάσκειν ἀλλήλους: οἱ δὲ νῦν τῶν ἀνθρώπων", "st": "16e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> σοφοὶ ἓν μέν, ὅπως ἂν τύχωσι, καὶ πολλὰ θᾶττον καὶ βραδύτερον ποιοῦσι τοῦ δέοντος, μετὰ δὲ τὸ ἓν ἄπειρα εὐθύς, τὰ δὲ μέσα αὐτοὺς ἐκφεύγει — οἷς διακεχώρισται τό τε διαλεκτικῶς πάλιν καὶ τὸ ἐριστικῶς ἡμᾶς ποιεῖσθαι πρὸς ἀλλήλους τοὺς λόγους.", "st": "17a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὰ μέν πως, ὦ Σώκρατες, δοκῶ σου μανθάνειν, τὰ δὲ ἔτι σαφέστερον δέομαι ἃ λέγεις ἀκοῦσαι.", "st": "17a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> σαφὲς μήν, ὦ Πρώταρχε, ἐστὶν ἐν τοῖς γράμμασιν ὃ λέγω, καὶ λάμβαν᾽ αὐτὸ ἐν τούτοις οἷσπερ καὶ", "st": "17a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πεπαίδευσαι.", "st": "17b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς;", "st": "17b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> φωνὴ μὲν ἡμῖν ἐστί που μία διὰ τοῦ στόματος ἰοῦσα, καὶ ἄπειρος αὖ πλήθει, πάντων τε καὶ ἑκάστου.", "st": "17b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν;", "st": "17b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ οὐδὲν ἑτέρῳ γε τούτων ἐσμέν πω σοφοί, οὔτε ὅτι τὸ ἄπειρον αὐτῆς ἴσμεν οὔθ᾽ ὅτι τὸ ἕν: ἀλλ᾽ ὅτι πόσα τ᾽ ἐστὶ καὶ ὁποῖα, τοῦτό ἐστι τὸ γραμματικὸν ἕκαστον ποιοῦν ἡμῶν.", "st": "17b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀληθέστατα.", "st": "17b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν καὶ τὸ μουσικὸν ὃ τυγχάνει ποιοῦν, τοῦτ᾽ ἔστι ταὐτόν.", "st": "17b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς;", "st": "17b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> φωνὴ μέν που καὶ τὸ κατ᾽ ἐκείνην τὴν τέχνην ἐστὶ μία ἐν αὐτῇ.", "st": "17c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς δ᾽ οὔ;", "st": "17c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> δύο δὲ θῶμεν βαρὺ καὶ ὀξύ, καὶ τρίτον ὁμότονον. ἢ πῶς;", "st": "17c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὕτως.", "st": "17c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ᾽ οὔπω σοφὸς ἂν εἴης τὴν μουσικὴν εἰδὼς ταῦτα μόνα, μὴ δὲ εἰδὼς ὥς γ᾽ ἔπος εἰπεῖν εἰς ταῦτα οὐδενὸς ἄξιος ἔσῃ.", "st": "17c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὐ γὰρ οὖν.", "st": "17c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ᾽, ὦ φίλε, ἐπειδὰν λάβῃς τὰ διαστήματα ὁπόσα ἐστὶ τὸν ἀριθμὸν τῆς φωνῆς ὀξύτητός τε πέρι καὶ βαρύτητος,", "st": "17c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ ὁποῖα, καὶ τοὺς ὅρους τῶν διαστημάτων, καὶ τὰ ἐκ τούτων ὅσα συστήματα γέγονεν — ἃ κατιδόντες οἱ πρόσθεν παρέδοσαν ἡμῖν τοῖς ἑπομένοις ἐκείνοις καλεῖν αὐτὰ ἁρμονίας, ἔν τε ταῖς κινήσεσιν αὖ τοῦ σώματος ἕτερα τοιαῦτα ἐνόντα πάθη γιγνόμενα, ἃ δὴ δι᾽ ἀριθμῶν μετρηθέντα δεῖν αὖ φασι ῥυθμοὺς καὶ μέτρα ἐπονομάζειν, καὶ ἅμα ἐννοεῖν ὡς οὕτω δεῖ περὶ παντὸς ἑνὸς καὶ πολλῶν σκοπεῖν — ὅταν γὰρ αὐτά", "st": "17d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τε λάβῃς οὕτω, τότε ἐγένου σοφός, ὅταν τε ἄλλο τῶν ἓν ὁτιοῦν ταύτῃ σκοπούμενος ἕλῃς, οὕτως ἔμφρων περὶ τοῦτο γέγονας: τὸ δ᾽ ἄπειρόν σε ἑκάστων καὶ ἐν ἑκάστοις πλῆθος ἄπειρον ἑκάστοτε ποιεῖ τοῦ φρονεῖν καὶ οὐκ ἐλλόγιμον οὐδ᾽ ἐνάριθμον, ἅτ᾽ οὐκ εἰς ἀριθμὸν οὐδένα ἐν οὐδενὶ πώποτε ἀπιδόντα.", "st": "17e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> κάλλιστα, ὦ Φίληβε, ἔμοιγε τὰ νῦν λεγόμενα εἰρηκέναι φαίνεται Σωκράτης.", "st": "17e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Φίληβος:<\/span> κἀμοὶ ταῦτά γε αὐτά: ἀλλὰ τί δή ποτε πρὸς ἡμᾶς ὁ λόγος οὗτος νῦν εἴρηται καὶ τί ποτε βουλόμενος;", "st": "18a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὀρθῶς μέντοι τοῦθ᾽ ἡμᾶς, ὦ Πρώταρχε, ἠρώτηκε Φίληβος.", "st": "18a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν, καὶ ἀποκρίνου γε αὐτῷ.", "st": "18a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> δράσω ταῦτα διελθὼν σμικρὸν ἔτι περὶ αὐτῶν τούτων. ὥσπερ γὰρ ἓν ὁτιοῦν εἴ τίς ποτε λάβοι, τοῦτον, ὥς φαμεν, οὐκ ἐπ᾽ ἀπείρου φύσιν δεῖ βλέπειν εὐθὺς ἀλλ᾽ ἐπί τινα ἀριθμόν, οὕτω καὶ τὸ ἐναντίον ὅταν τις τὸ ἄπειρον", "st": "18a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀναγκασθῇ πρῶτον λαμβάνειν, μὴ ἐπὶ τὸ ἓν εὐθύς, ἀλλ᾽ [ἐπ᾽] ἀριθμὸν αὖ τινα πλῆθος ἕκαστον ἔχοντά τι κατανοεῖν, τελευτᾶν τε ἐκ πάντων εἰς ἕν. πάλιν δὲ ἐν τοῖς γράμμασι τὸ νῦν λεγόμενον λάβωμεν.", "st": "18b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς;", "st": "18b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἐπειδὴ φωνὴν ἄπειρον κατενόησεν εἴτε τις θεὸς εἴτε καὶ θεῖος ἄνθρωπος — ὡς λόγος ἐν Αἰγύπτῳ Θεῦθ τινα τοῦτον γενέσθαι λέγων, ὃς πρῶτος τὰ φωνήεντα ἐν τῷ ἀπείρῳ κατενόησεν οὐχ ἓν ὄντα ἀλλὰ πλείω, καὶ πάλιν", "st": "18b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἕτερα φωνῆς μὲν οὔ, φθόγγου δὲ μετέχοντά τινος, ἀριθμὸν δέ τινα καὶ τούτων εἶναι, τρίτον δὲ εἶδος γραμμάτων διεστήσατο τὰ νῦν λεγόμενα ἄφωνα ἡμῖν: τὸ μετὰ τοῦτο διῄρει τά τε ἄφθογγα καὶ ἄφωνα μέχρι ἑνὸς ἑκάστου, καὶ τὰ φωνήεντα καὶ τὰ μέσα κατὰ τὸν αὐτὸν τρόπον, ἕως ἀριθμὸν αὐτῶν λαβὼν ἑνί τε ἑκάστῳ καὶ σύμπασι στοιχεῖον ἐπωνόμασε: καθορῶν δὲ ὡς οὐδεὶς ἡμῶν οὐδ᾽ ἂν ἓν αὐτὸ καθ᾽ αὑτὸ ἄνευ πάντων αὐτῶν μάθοι, τοῦτον τὸν δεσμὸν αὖ λογισάμενος ὡς", "st": "18c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὄντα ἕνα καὶ πάντα ταῦτα ἕν πως ποιοῦντα μίαν ἐπ᾽ αὐτοῖς ὡς οὖσαν γραμματικὴν τέχνην ἐπεφθέγξατο προσειπών.", "st": "18d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Φίληβος:<\/span> ταῦτ᾽ ἔτι σαφέστερον ἐκείνων αὐτά γε πρὸς ἄλληλα, ὦ Πρώταρχε, ἔμαθον: τὸ δ᾽ αὐτό μοι τοῦ λόγου νῦν τε καὶ σμικρὸν ἔμπροσθεν ἐλλείπεται.", "st": "18d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μῶν, ὦ Φίληβε, τὸ τί πρὸς ἔπος αὖ ταῦτ᾽ ἐστίν;", "st": "18d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Φίληβος:<\/span> ναί, τοῦτ᾽ ἔστιν ὃ πάλαι ζητοῦμεν ἐγώ τε καὶ Πρώταρχος.", "st": "18d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἦ μὴν ἐπ᾽ αὐτῷ γε ἤδη γεγονότες ζητεῖτε, ὡς φῄς,", "st": "18d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πάλαι.", "st": "18e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Φίληβος:<\/span> πῶς;", "st": "18e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ οὐ περὶ φρονήσεως ἦν καὶ ἡδονῆς ἡμῖν ἐξ ἀρχῆς ὁ λόγος, ὁπότερον αὐτοῖν αἱρετέον;", "st": "18e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Φίληβος:<\/span> πῶς γὰρ οὔ;", "st": "18e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν ἕν γε ἑκάτερον αὐτοῖν εἶναί φαμεν.", "st": "18e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Φίληβος:<\/span> πάνυ μὲν οὖν.", "st": "18e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τοῦτ᾽ αὐτὸ τοίνυν ἡμᾶς ὁ πρόσθεν λόγος ἀπαιτεῖ, πῶς ἔστιν ἓν καὶ πολλὰ αὐτῶν ἑκάτερον, καὶ πῶς μὴ ἄπειρα", "st": "18e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> εὐθύς, ἀλλά τινά ποτε ἀριθμὸν ἑκάτερον ἔμπροσθεν κέκτηται τοῦ ἄπειρα αὐτῶν ἕκαστα γεγονέναι;", "st": "19a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὐκ εἰς φαῦλόν γε ἐρώτημα, ὦ Φίληβε, οὐκ οἶδ᾽ ὅντινα τρόπον κύκλῳ πως περιαγαγὼν ἡμᾶς ἐμβέβληκε Σωκράτης. καὶ σκόπει δὴ πότερος ἡμῶν ἀποκρινεῖται τὸ νῦν ἐρωτώμενον. ἴσως δὴ γελοῖον τὸ ἐμὲ τοῦ λόγου διάδοχον παντελῶς ὑποστάντα διὰ τὸ μὴ δύνασθαι τὸ νῦν ἐρωτηθὲν ἀποκρίνασθαι σοὶ πάλιν τοῦτο προστάττειν: γελοιότερον", "st": "19a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> δ᾽ οἶμαι πολὺ τὸ μηδέτερον ἡμῶν δύνασθαι. σκόπει δὴ τί δράσομεν. εἴδη γάρ μοι δοκεῖ νῦν ἐρωτᾶν ἡδονῆς ἡμᾶς Σωκράτης εἴτε ἔστιν εἴτε μή, καὶ ὁπόσα ἐστὶ καὶ ὁποῖα: τῆς τ᾽ αὖ φρονήσεως πέρι κατὰ ταὐτὰ ὡσαύτως.", "st": "19b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀληθέστατα λέγεις, ὦ παῖ Καλλίου: μὴ γὰρ δυνάμενοι τοῦτο κατὰ παντὸς ἑνὸς καὶ ὁμοίου καὶ ταὐτοῦ δρᾶν καὶ τοῦ ἐναντίου, ὡς ὁ παρελθὼν λόγος ἐμήνυσεν, οὐδεὶς εἰς οὐδὲν οὐδενὸς ἂν ἡμῶν οὐδέποτε γένοιτο ἄξιος.", "st": "19b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> σχεδὸν ἔοικεν οὕτως, ὦ Σώκρατες, ἔχειν. ἀλλὰ καλὸν μὲν τὸ σύμπαντα γιγνώσκειν τῷ σώφρονι, δεύτερος δ᾽ εἶναι πλοῦς δοκεῖ μὴ λανθάνειν αὐτὸν αὑτόν. τί δή μοι τοῦτο εἴρηται τὰ νῦν; ἐγώ σοι φράσω. σὺ τήνδε ἡμῖν τὴν συνουσίαν, ὦ Σώκρατες, ἐπέδωκας πᾶσι καὶ σεαυτὸν πρὸς τὸ διελέσθαι τί τῶν ἀνθρωπίνων κτημάτων ἄριστον. Φιλήβου γὰρ εἰπόντος ἡδονὴν καὶ τέρψιν καὶ χαρὰν καὶ πάνθ᾽ ὁπόσα τοιαῦτ᾽ ἐστί, σὺ πρὸς αὐτὰ ἀντεῖπες ὡς οὐ ταῦτα", "st": "19c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀλλ᾽ ἐκεῖνά ἐστιν ἃ πολλάκις ἡμᾶς αὐτοὺς ἀναμιμνῄσκομεν ἑκόντες, ὀρθῶς δρῶντες, ἵν᾽ ἐν μνήμῃ παρακείμενα ἑκάτερα βασανίζηται. φῂς δ᾽, ὡς ἔοικε, σὺ τὸ προσρηθησόμενον ὀρθῶς ἄμεινον ἡδονῆς γε ἀγαθὸν εἶναι νοῦν, ἐπιστήμην, σύνεσιν, τέχνην καὶ πάντα αὖ τὰ τούτων συγγενῆ, ⟨ἃ⟩ κτᾶσθαι δεῖν ἀλλ᾽ οὐχὶ ἐκεῖνα. τούτων δὴ μετ᾽ ἀμφισβητήσεως ἑκατέρων λεχθέντων ἡμεῖς σοι μετὰ παιδιᾶς ἠπειλήσαμεν", "st": "19d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὡς οὐκ ἀφήσομεν οἴκαδέ σε πρὶν ἂν τούτων τῶν λόγων πέρας ἱκανὸν γένηταί τι διορισθέντων, σὺ δὲ συνεχώρησας καὶ ἔδωκας εἰς ταῦθ᾽ ἡμῖν σαυτόν, ἡμεῖς δὲ δὴ λέγομεν, καθάπερ οἱ παῖδες, ὅτι τῶν ὀρθῶς δοθέντων ἀφαίρεσις οὐκ ἔστι: παῦσαι δὴ τὸν τρόπον ἡμῖν ἀπαντῶν τοῦτον ἐπὶ τὰ νῦν λεγόμενα.", "st": "19e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τίνα λέγεις;", "st": "19e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> εἰς ἀπορίαν ἐμβάλλων καὶ ἀνερωτῶν ὧν μὴ δυναίμεθ᾽ ἂν ἱκανὴν ἀπόκρισιν ἐν τῷ παρόντι διδόναι σοι. μὴ γὰρ οἰώμεθα τέλος ἡμῖν εἶναι τῶν νῦν τὴν πάντων ἡμῶν ἀπορίαν, ἀλλ᾽ εἰ δρᾶν τοῦθ᾽ ἡμεῖς ἀδυνατοῦμεν, σοὶ δραστέον: ὑπέσχου γάρ. βουλεύου δὴ πρὸς ταῦτα αὐτὸς πότερον ἡδονῆς εἴδη σοι καὶ ἐπιστήμης διαιρετέον ἢ καὶ ἐατέον, εἴ πῃ καθ᾽ ἕτερόν τινα τρόπον οἷός τ᾽ εἶ καὶ βούλει δηλῶσαί πως ἄλλως τὰ νῦν ἀμφισβητούμενα παρ᾽ ἡμῖν.", "st": "20a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> δεινὸν μὲν τοίνυν ἔτι προσδοκᾶν οὐδὲν δεῖ τὸν ἐμέ, ἐπειδὴ τοῦθ᾽ οὕτως εἶπες: τὸ γὰρ εἰ βούλει ῥηθὲν λύει πάντα φόβον ἑκάστων πέρι. πρὸς δὲ αὖ τοῖς μνήμην τινὰ δοκεῖ τίς μοι δεδωκέναι θεῶν ἡμῖν.", "st": "20b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς δὴ καὶ τίνων;", "st": "20b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> λόγων ποτέ τινων πάλαι ἀκούσας ὄναρ ἢ καὶ ἐγρηγορὼς νῦν ἐννοῶ περί τε ἡδονῆς καὶ φρονήσεως, ὡς οὐδέτερον αὐτοῖν ἐστι τἀγαθόν, ἀλλὰ ἄλλο τι τρίτον, ἕτερον μὲν τούτων, ἄμεινον δὲ ἀμφοῖν. καίτοι τοῦτό γε ἂν ἐναργῶς", "st": "20b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἡμῖν φανῇ νῦν, ἀπήλλακται μὲν ἡδονὴ τοῦ νικᾶν: τὸ γὰρ ἀγαθὸν οὐκ ἂν ἔτι ταὐτὸν αὐτῇ γίγνοιτο. ἢ πῶς;", "st": "20c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὕτως.", "st": "20c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τῶν δέ γε εἰς τὴν διαίρεσιν εἰδῶν ἡδονῆς οὐδὲν ἔτι προσδεησόμεθα κατ᾽ ἐμὴν δόξαν. προϊὸν δ᾽ ἔτι σαφέστερον δείξει.", "st": "20c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> κάλλιστ᾽ εἰπὼν οὕτω καὶ διαπέραινε.", "st": "20c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μίκρ᾽ ἄττα τοίνυν ἔμπροσθεν ἔτι διομολογησώμεθα.", "st": "20c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὰ ποῖα;", "st": "20c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὴν τἀγαθοῦ μοῖραν πότερον ἀνάγκη τέλεον ἢ μὴ τέλεον εἶναι;", "st": "20d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάντων δήπου τελεώτατον, ὦ Σώκρατες.", "st": "20d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί δέ; ἱκανὸν τἀγαθόν;", "st": "20d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς γὰρ οὔ; καὶ πάντων γε εἰς τοῦτο διαφέρειν τῶν ὄντων.", "st": "20d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τόδε γε μήν, ὡς οἶμαι, περὶ αὐτοῦ ἀναγκαιότατον εἶναι λέγειν, ὡς πᾶν τὸ γιγνῶσκον αὐτὸ θηρεύει καὶ ἐφίεται βουλόμενον ἑλεῖν καὶ περὶ αὑτὸ κτήσασθαι, καὶ τῶν ἄλλων οὐδὲν φροντίζει πλὴν τῶν ἀποτελουμένων ἅμα ἀγαθοῖς.", "st": "20d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὐκ ἔστι τούτοις ἀντειπεῖν.", "st": "20d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> σκοπῶμεν δὴ καὶ κρίνωμεν τόν τε ἡδονῆς καὶ τὸν φρονήσεως βίον ἰδόντες χωρίς.", "st": "20e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς εἶπες;", "st": "20e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μήτε ἐν τῷ τῆς ἡδονῆς ἐνέστω φρόνησις μήτ᾽ ἐν τῷ τῆς φρονήσεως ἡδονή. δεῖ γάρ, εἴπερ πότερον αὐτῶν ἔστ᾽ ἀγαθόν, μηδὲν μηδενὸς ἔτι προσδεῖσθαι: δεόμενον δ᾽", "st": "20e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἂν φανῇ πότερον, οὐκ ἔστι που τοῦτ᾽ ἔτι τὸ ὄντως ἡμῖν ἀγαθόν.", "st": "21a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς γὰρ ἄν;", "st": "21a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἐν σοὶ πειρώμεθα βασανίζοντες ταῦτα;", "st": "21a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν.", "st": "21a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀποκρίνου δή.", "st": "21a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγε.", "st": "21a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> δέξαι᾽ ἄν, Πρώταρχε, σὺ ζῆν τὸν βίον ἅπαντα ἡδόμενος ἡδονὰς τὰς μεγίστας;", "st": "21a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί δ᾽ οὔ;", "st": "21a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ οὖν ἔτι τινὸς ἄν σοι προσδεῖν ἡγοῖο, εἰ τοῦτ᾽ ἔχεις παντελῶς;", "st": "21a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὐδαμῶς.", "st": "21a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὅρα δή, τοῦ φρονεῖν καὶ τοῦ νοεῖν καὶ λογίζεσθαι", "st": "21a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὰ δέοντα καὶ ὅσα τούτων ἀδελφά, μῶν μὴ δέοι᾽ ἄν τι;", "st": "21b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ τί; πάντα γὰρ ἔχοιμ᾽ ἄν που τὸ χαίρειν ἔχων.", "st": "21b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν οὕτω ζῶν ἀεὶ μὲν διὰ βίου ταῖς μεγίσταις ἡδοναῖς χαίροις ἄν;", "st": "21b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί δ᾽ οὔ;", "st": "21b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> νοῦν δέ γε καὶ μνήμην καὶ ἐπιστήμην καὶ δόξαν μὴ κεκτημένος ἀληθῆ, πρῶτον μὲν τοῦτο αὐτό, εἰ χαίρεις ἢ μὴ χαίρεις, ἀνάγκη δήπου σε ἀγνοεῖν, κενόν γε ὄντα πάσης φρονήσεως;", "st": "21b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀνάγκη.", "st": "21b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν ὡσαύτως μνήμην μὴ κεκτημένον ἀνάγκη δήπου μηδ᾽ ὅτι ποτὲ ἔχαιρες μεμνῆσθαι, τῆς τ᾽ ἐν τῷ παραχρῆμα ἡδονῆς προσπιπτούσης μηδ᾽ ἡντινοῦν μνήμην ὑπομένειν: δόξαν δ᾽ αὖ μὴ κεκτημένον ἀληθῆ μὴ δοξάζειν χαίρειν χαίροντα, λογισμοῦ δὲ στερόμενον μηδ᾽ εἰς τὸν ἔπειτα χρόνον ὡς χαιρήσεις δυνατὸν εἶναι λογίζεσθαι, ζῆν δὲ οὐκ ἀνθρώπου βίον, ἀλλά τινος πλεύμονος ἢ τῶν ὅσα θαλάττια μετ᾽ ὀστρεΐνων ἔμψυχά ἐστι σωμάτων. ἔστι ταῦτα, ἢ παρὰ", "st": "21c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ταῦτα ἔχομεν ἄλλα διανοηθῆναι;", "st": "21d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ πῶς;", "st": "21d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ οὖν αἱρετὸς ἡμῖν βίος ὁ τοιοῦτος;", "st": "21d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> εἰς ἀφασίαν παντάπασί με, ὦ Σώκρατες, οὗτος ὁ λόγος ἐμβέβληκε τὰ νῦν.", "st": "21d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μήπω τοίνυν μαλθακιζώμεθα, τὸν δὲ τοῦ νοῦ μεταλαβόντες αὖ βίον ἴδωμεν.", "st": "21d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸν ποῖον δὴ λέγεις;", "st": "21d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> εἴ τις δέξαιτ᾽ ἂν αὖ ζῆν ἡμῶν φρόνησιν μὲν καὶ νοῦν καὶ ἐπιστήμην καὶ μνήμην πᾶσαν πάντων κεκτημένος,", "st": "21d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἡδονῆς δὲ μετέχων μήτε μέγα μήτε σμικρόν, μηδ᾽ αὖ λύπης, ἀλλὰ τὸ παράπαν ἀπαθὴς πάντων τῶν τοιούτων.", "st": "21e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὐδέτερος ὁ βίος, ὦ Σώκρατες, ἔμοιγε τούτων αἱρετός, οὐδ᾽ ἄλλῳ μή ποτε, ὡς ἐγᾦμαι, φανῇ.", "st": "21e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί δ᾽ ὁ συναμφότερος, ὦ Πρώταρχε, ἐξ ἀμφοῖν συμμειχθεὶς κοινὸς γενόμενος;", "st": "22a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἡδονῆς λέγεις καὶ νοῦ καὶ φρονήσεως;", "st": "22a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὕτω καὶ τῶν τοιούτων [λέγω] ἔγωγε.", "st": "22a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πᾶς δήπου τοῦτόν γε αἱρήσεται πρότερον ἢ ‘κείνων ὁποτερονοῦν, καὶ πρὸς τούτοις [γε] οὐχ ὁ μέν, ὁ δ᾽ οὔ.", "st": "22a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μανθάνομεν οὖν ὅτι νῦν ἡμῖν ἐστι τὸ συμβαῖνον ἐν τοῖς παροῦσι λόγοις;", "st": "22a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν, ὅτι γε τρεῖς μὲν βίοι προυτέθησαν,", "st": "22a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τοῖν δυοῖν δ᾽ οὐδέτερος ἱκανὸς οὐδὲ αἱρετὸς οὔτε ἀνθρώπων οὔτε ζῴων οὐδενί.", "st": "22b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μῶν οὖν οὐκ ἤδη τούτων γε πέρι δῆλον ὡς οὐδέτερος αὐτοῖν εἶχε τἀγαθόν; ἦν γὰρ ἂν ἱκανὸς καὶ τέλεος καὶ πᾶσι φυτοῖς καὶ ζῴοις αἱρετός, οἷσπερ δυνατὸν ἦν οὕτως ἀεὶ διὰ βίου ζῆν: εἰ δέ τις ἄλλα ᾑρεῖθ᾽ ἡμῶν, παρὰ φύσιν ἂν τὴν τοῦ ἀληθῶς αἱρετοῦ ἐλάμβανεν ἄκων ἐξ ἀγνοίας ἤ τινος ἀνάγκης οὐκ εὐδαίμονος.", "st": "22b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἔοικε γοῦν ταῦθ᾽ οὕτως ἔχειν.", "st": "22b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὡς μὲν τοίνυν τήν γε Φιλήβου θεὸν οὐ δεῖ διανοεῖσθαι ταὐτὸν καὶ τἀγαθόν, ἱκανῶς εἰρῆσθαί μοι δοκεῖ.", "st": "22c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Φίληβος:<\/span> οὐδὲ γὰρ ὁ σὸς νοῦς, ὦ Σώκρατες, ἔστι τἀγαθόν, ἀλλ᾽ ἕξει που ταὐτὰ ἐγκλήματα.", "st": "22c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τάχ᾽ ἄν, ὦ Φίληβε, ὅ γ᾽ ἐμός: οὐ μέντοι τόν γε ἀληθινὸν ἅμα καὶ θεῖον οἶμαι νοῦν, ἀλλ᾽ ἄλλως πως ἔχειν. τῶν μὲν οὖν νικητηρίων πρὸς τὸν κοινὸν βίον οὐκ ἀμφισβητῶ πω ὑπὲρ νοῦ, τῶν δὲ δὴ δευτερείων ὁρᾶν καὶ σκοπεῖν χρὴ πέρι", "st": "22c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί δράσομεν: τάχα γὰρ ἂν τοῦ κοινοῦ τούτου βίου αἰτιῴμεθ᾽ ἂν ἑκάτερος ὁ μὲν τὸν νοῦν αἴτιον, ὁ δ᾽ ἡδονὴν εἶναι, καὶ οὕτω τὸ μὲν ἀγαθὸν τούτων ἀμφοτέρων οὐδέτερον ἂν εἴη, τάχα δ᾽ ἂν αἴτιόν τις ὑπολάβοι πότερον αὐτῶν εἶναι. τούτου δὴ πέρι καὶ μᾶλλον ἔτι πρὸς Φίληβον διαμαχοίμην ἂν ὡς ἐν τῷ μεικτῷ τούτῳ βίῳ, ὅτι ποτ᾽ ἔστι τοῦτο ὃ λαβὼν ὁ βίος οὗτος γέγονεν αἱρετὸς ἅμα καὶ ἀγαθός, οὐχ ἡδονὴ ἀλλὰ νοῦς τούτῳ συγγενέστερον καὶ ὁμοιότερόν ἐστι, καὶ κατὰ τοῦτον", "st": "22d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὸν λόγον οὔτ᾽ ἂν τῶν πρωτείων οὐδ᾽ αὖ τῶν δευτερείων ἡδονῇ μετὸν ἀληθῶς ἄν ποτε λέγοιτο: πορρωτέρω δ᾽ ἐστὶ τῶν τριτείων, εἴ τι τῷ ἐμῷ νῷ δεῖ πιστεύειν ἡμᾶς τὰ νῦν.", "st": "22e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀλλὰ μήν, ὦ Σώκρατες, ἔμοιγε δοκεῖ νῦν μὲν ἡδονή σοι πεπτωκέναι καθαπερεὶ πληγεῖσα ὑπὸ τῶν νυνδὴ λόγων: τῶν γὰρ νικητηρίων πέρι μαχομένη κεῖται. τὸν δὲ", "st": "22e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> νοῦν, ὡς ἔοικε, λεκτέον ὡς ἐμφρόνως οὐκ ἀντεποιεῖτο τῶν νικητηρίων: τὰ γὰρ αὔτ᾽ ἔπαθεν ἄν. τῶν δὲ δὴ δευτερείων στερηθεῖσα ἡδονὴ παντάπασιν ἄν τινα καὶ ἀτιμίαν σχοίη πρὸς τῶν αὑτῆς ἐραστῶν: οὐδὲ γὰρ ἐκείνοις ἔτ᾽ ἂν ὁμοίως φαίνοιτο καλή.", "st": "23a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί οὖν; οὐκ ἄμεινον αὐτὴν ἐᾶν ἤδη καὶ μὴ τὴν ἀκριβεστάτην αὐτῇ προσφέροντα βάσανον καὶ ἐξελέγχοντα λυπεῖν;", "st": "23a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὐδὲν λέγεις, ὦ Σώκρατες.", "st": "23a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ ὅτι τὸ ἀδύνατον εἶπον, λυπεῖν ἡδονήν;", "st": "23b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὐ μόνον γε ἀλλ᾽ ὅτι καὶ ἀγνοεῖς ὡς οὐδείς πώ σε ἡμῶν μεθήσει πρὶν ἂν εἰς τέλος ἐπεξέλθῃς τούτων τῷ λόγῳ.", "st": "23b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> βαβαῖ ἄρα, ὦ Πρώταρχε, συχνοῦ μὲν λόγου τοῦ λοιποῦ, σχεδὸν δὲ οὐδὲ ῥᾳδίου πάνυ τι νῦν. καὶ γὰρ δὴ φαίνεται δεῖν ἄλλης μηχανῆς, ἐπὶ τὰ δευτερεῖα ὑπὲρ νοῦ πορευόμενον οἷον βέλη ἔχειν ἕτερα τῶν ἔμπροσθεν λόγων: ἔστι δὲ ἴσως ἔνια καὶ ταὐτά. οὐκοῦν χρή;", "st": "23b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς γὰρ οὔ;", "st": "23b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὴν δέ γε ἀρχὴν αὐτοῦ διευλαβεῖσθαι πειρώμεθα τιθέμενοι.", "st": "23c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ποίαν δὴ λέγεις;", "st": "23c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πάντα τὰ νῦν ὄντα ἐν τῷ παντὶ διχῇ διαλάβωμεν, μᾶλλον δ᾽, εἰ βούλει, τριχῇ.", "st": "23c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καθ᾽ ὅτι, φράζοις ἄν;", "st": "23c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> λάβωμεν ἄττα τῶν νυνδὴ λόγων.", "st": "23c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ποῖα;", "st": "23c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὸν θεὸν ἐλέγομέν που τὸ μὲν ἄπειρον δεῖξαι τῶν ὄντων, τὸ δὲ πέρας;", "st": "23c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν.", "st": "23c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τούτω δὴ τῶν εἰδῶν τὰ δύο τιθώμεθα, τὸ δὲ τρίτον", "st": "23c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἐξ ἀμφοῖν τούτοιν ἕν τι συμμισγόμενον. εἰμὶ δ᾽, ὡς ἔοικεν, ἐγὼ γελοῖός τις ἄνθρωπος κατ᾽ εἴδη διιστὰς καὶ συναριθμούμενος.", "st": "23d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί φῄς, ὠγαθέ;", "st": "23d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τετάρτου μοι γένους αὖ προσδεῖν φαίνεται.", "st": "23d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγε τίνος.", "st": "23d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τῆς συμμείξεως τούτων πρὸς ἄλληλα τὴν αἰτίαν ὅρα, καὶ τίθει μοι πρὸς τρισὶν ἐκείνοις τέταρτον τοῦτο.", "st": "23d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> μῶν οὖν σοι καὶ πέμπτου προσδεήσει διάκρισίν τινος δυναμένου;", "st": "23d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τάχ᾽ ἄν: οὐ μὴν οἶμαί γε ἐν τῷ νῦν: ἂν δέ τι δέῃ,", "st": "23d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> συγγνώσῃ πού μοι σὺ μεταδιώκοντι πέμπτον [βίον].", "st": "23e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν;", "st": "23e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πρῶτον μὲν δὴ τῶν τεττάρων τὰ τρία διελόμενοι, τὰ δύο τούτων πειρώμεθα, πολλὰ ἑκάτερον ἐσχισμένον καὶ διεσπασμένον ἰδόντες, εἰς ἓν πάλιν ἑκάτερον συναγαγόντες, νοῆσαι πῇ ποτε ἦν αὐτῶν ἓν καὶ πολλὰ ἑκάτερον.", "st": "23e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> εἴ μοι σαφέστερον ἔτι περὶ αὐτῶν εἴποις, τάχ᾽ ἂν ἑποίμην.", "st": "23e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> λέγω τοίνυν τὰ δύο ἃ προτίθεμαι ταὔτ᾽ εἶναι ἅπερ νυνδή, τὸ μὲν ἄπειρον, τὸ δὲ πέρας ἔχον: ὅτι δὲ τρόπον τινὰ τὸ ἄπειρον πόλλ᾽ ἐστί, πειράσομαι φράζειν. τὸ δὲ πέρας ἔχον ἡμᾶς περιμενέτω.", "st": "24a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> μένει.", "st": "24a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> σκέψαι δή. χαλεπὸν μὲν γὰρ καὶ ἀμφισβητήσιμον ὃ κελεύω σε σκοπεῖν, ὅμως δὲ σκόπει. θερμοτέρου καὶ ψυχροτέρου πέρι πρῶτον ὅρα πέρας εἴ ποτέ τι νοήσαις ἄν, ἢ τὸ μᾶλλόν τε καὶ ἧττον ἐν αὐτοῖς οἰκοῦν⟨τε⟩ τοῖς γένεσιν,", "st": "24a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἕωσπερ ἂν ἐνοικῆτον, τέλος οὐκ ἂν ἐπιτρεψαίτην γίγνεσθαι: γενομένης γὰρ τελευτῆς καὶ αὐτὼ τετελευτήκατον.", "st": "24b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀληθέστατα λέγεις.", "st": "24b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀεὶ δέ γε, φαμέν, ἔν τε τῷ θερμοτέρῳ καὶ ψυχροτέρῳ τὸ μᾶλλόν τε καὶ ἧττον ἔνι.", "st": "24b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ μάλα.", "st": "24b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀεὶ τοίνυν ὁ λόγος ἡμῖν σημαίνει τούτω μὴ τέλος ἔχειν: ἀτελῆ δ᾽ ὄντε δήπου παντάπασιν ἀπείρω γίγνεσθον.", "st": "24b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ σφόδρα γε, ὦ Σώκρατες.", "st": "24b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ᾽ εὖ γε, ὦ φίλε Πρώταρχε, ὑπέλαβες καὶ", "st": "24b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀνέμνησας ὅτι καὶ τὸ σφόδρα τοῦτο, ὃ σὺ νῦν ἐφθέγξω, καὶ τό γε ἠρέμα τὴν αὐτὴν δύναμιν ἔχετον τῷ μᾶλλόν τε καὶ ἧττον: ὅπου γὰρ ἂν ἐνῆτον, οὐκ ἐᾶτον εἶναι ποσὸν ἕκαστον, ἀλλ᾽ ἀεὶ σφοδρότερον ἡσυχαιτέρου καὶ τοὐναντίον ἑκάσταις πράξεσιν ἐμποιοῦντε τὸ πλέον καὶ τὸ ἔλαττον ἀπεργάζεσθον, τὸ δὲ ποσὸν ἀφανίζετον. ὃ γὰρ ἐλέχθη νυνδή, μὴ ἀφανίσαντε τὸ ποσόν, ἀλλ᾽ ἐάσαντε αὐτό τε καὶ τὸ μέτριον ἐν τῇ", "st": "24c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τοῦ μᾶλλον καὶ ἧττον καὶ σφόδρα καὶ ἠρέμα ἕδρᾳ ἐγγενέσθαι, αὐτὰ ἔρρει ταῦτα ἐκ τῆς αὑτῶν χώρας ἐν ᾗ ἐνῆν. οὐ γὰρ ἔτι θερμότερον οὐδὲ ψυχρότερον εἴτην ἂν λαβόντε τὸ ποσόν: προχωρεῖ γὰρ καὶ οὐ μένει τό τε θερμότερον ἀεὶ καὶ τὸ ψυχρότερον ὡσαύτως, τὸ δὲ ποσὸν ἔστη καὶ προϊὸν ἐπαύσατο. κατὰ δὴ τοῦτον τὸν λόγον ἄπειρον γίγνοιτ᾽ ἂν τὸ θερμότερον καὶ τοὐναντίον ἅμα.", "st": "24d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> φαίνεται γοῦν, ὦ Σώκρατες: ἔστι δ᾽, ὅπερ εἶπες, οὐ ῥᾴδια ταῦτα συνέπεσθαι. τὸ δὲ εἰς αὖθίς τε καὶ αὖθις", "st": "24d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἴσως λεχθέντα τόν τε ἐρωτῶντα καὶ τὸν ἐρωτώμενον ἱκανῶς ἂν συμφωνοῦντας ἀποφήναιεν.", "st": "24e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ᾽ εὖ μὲν λέγεις καὶ πειρατέον οὕτω ποιεῖν. νῦν μέντοι ἄθρει τῆς τοῦ ἀπείρου φύσεως εἰ τοῦτο δεξόμεθα σημεῖον, ἵνα μὴ πάντ᾽ ἐπεξιόντες μηκύνωμεν.", "st": "24e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ ποῖον δὴ λέγεις;", "st": "24e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὁπόσ᾽ ἂν ἡμῖν φαίνηται μᾶλλόν τε καὶ ἧττον γιγνόμενα καὶ τὸ σφόδρα καὶ ἠρέμα δεχόμενα καὶ τὸ λίαν καὶ ὅσα", "st": "24e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τοιαῦτα πάντα, εἰς τὸ τοῦ ἀπείρου γένος ὡς εἰς ἓν δεῖ πάντα ταῦτα τιθέναι, κατὰ τὸν ἔμπροσθεν λόγον ὃν ἔφαμεν ὅσα διέσπασται καὶ διέσχισται συναγαγόντας χρῆναι κατὰ δύναμιν μίαν ἐπισημαίνεσθαί τινα φύσιν, εἰ μέμνησαι.", "st": "25a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> μέμνημαι.", "st": "25a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τὰ μὴ δεχόμενα ταῦτα, τούτων δὲ τὰ ἐναντία πάντα δεχόμενα, πρῶτον μὲν τὸ ἴσον καὶ ἰσότητα, μετὰ δὲ τὸ ἴσον τὸ διπλάσιον καὶ πᾶν ὅτιπερ ἂν πρὸς ἀριθμὸν ἀριθμὸς", "st": "25a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἢ μέτρον ᾖ πρὸς μέτρον, ταῦτα σύμπαντα εἰς τὸ πέρας ἀπολογιζόμενοι καλῶς ἂν δοκοῖμεν δρᾶν τοῦτο. ἢ πῶς σὺ φῄς;", "st": "25b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> κάλλιστά γε, ὦ Σώκρατες.", "st": "25b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> εἶεν: τὸ δὲ τρίτον τὸ μεικτὸν ἐκ τούτοιν ἀμφοῖν τίνα ἰδέαν φήσομεν ἔχειν;", "st": "25b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> σὺ καὶ ἐμοὶ φράσεις, ὡς οἶμαι.", "st": "25b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> θεὸς μὲν οὖν, ἄνπερ γε ἐμαῖς εὐχαῖς ἐπήκοος γίγνηταί τις θεῶν.", "st": "25b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> εὔχου δὴ καὶ σκόπει.", "st": "25b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> σκοπῶ: καί μοι δοκεῖ τις, ὦ Πρώταρχε, αὐτῶν φίλος ἡμῖν νυνδὴ γεγονέναι.", "st": "25b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς λέγεις τοῦτο καὶ τίνι τεκμηρίῳ χρῇ;", "st": "25c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> φράσω δῆλον ὅτι: σὺ δέ μοι συνακολούθησον τῷ λόγῳ.", "st": "25c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγε μόνον.", "st": "25c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> θερμότερον ἐφθεγγόμεθα νυνδή πού τι καὶ ψυχρότερον. ἦ γάρ;", "st": "25c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ναί.", "st": "25c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πρόσθες δὴ ξηρότερον καὶ ὑγρότερον αὐτοῖς καὶ πλέον καὶ ἔλαττον καὶ θᾶττον καὶ βραδύτερον καὶ μεῖζον καὶ σμικρότερον καὶ ὁπόσα ἐν τῷ πρόσθεν τῆς τὸ μᾶλλόν τε καὶ ἧττον δεχομένης ἐτίθεμεν εἰς ἓν φύσεως.", "st": "25c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τῆς τοῦ ἀπείρου λέγεις;", "st": "25d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ναί. συμμείγνυ δέ γε εἰς αὐτὴν τὸ μετὰ ταῦτα τὴν αὖ τοῦ πέρατος γένναν.", "st": "25d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ποίαν;", "st": "25d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἣν καὶ νυνδή, δέον ἡμᾶς καθάπερ τὴν τοῦ ἀπείρου συνηγάγομεν εἰς ἕν, οὕτω καὶ τὴν τοῦ περατοειδοῦς συναγαγεῖν, οὐ συνηγάγομεν. ἀλλ᾽ ἴσως καὶ νῦν ταὐτὸν δράσει, ⟨εἰ⟩ τούτων ἀμφοτέρων συναγομένων καταφανὴς κἀκείνη γενήσεται.", "st": "25d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ποίαν καὶ πῶς λέγεις;", "st": "25d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὴν τοῦ ἴσου καὶ διπλασίου, καὶ ὁπόση παύει πρὸς", "st": "25d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἄλληλα τἀναντία διαφόρως ἔχοντα, σύμμετρα δὲ καὶ σύμφωνα ἐνθεῖσα ἀριθμὸν ἀπεργάζεται.", "st": "25e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> μανθάνω: φαίνῃ γάρ μοι λέγειν μειγνὺς ταῦτα γενέσεις τινὰς ἐφ᾽ ἑκάστων αὐτῶν συμβαίνειν.", "st": "25e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὀρθῶς γὰρ φαίνομαι.", "st": "25e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγε τοίνυν.", "st": "25e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρα οὐκ ἐν μὲν νόσοις ἡ τούτων ὀρθὴ κοινωνία τὴν ὑγιείας φύσιν ἐγέννησεν;", "st": "25e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> παντάπασι μὲν οὖν.", "st": "26a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἐν δὲ ὀξεῖ καὶ βαρεῖ καὶ ταχεῖ καὶ βραδεῖ, ἀπείροις οὖσιν, ἆρ᾽ οὐ ταὐτὰ [ἐγγιγνόμενα] ταῦτα: ἅμα πέρας τε ἀπηργάσατο καὶ μουσικὴν σύμπασαν τελεώτατα συνεστήσατο;", "st": "26a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> κάλλιστά γε.", "st": "26a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν ἔν γε χειμῶσιν καὶ πνίγεσιν ἐγγενομένη τὸ μὲν πολὺ λίαν καὶ ἄπειρον ἀφείλετο, τὸ δὲ ἔμμετρον καὶ ἅμα σύμμετρον ἀπηργάσατο.", "st": "26a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν;", "st": "26a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἐκ τούτων ὧραί τε καὶ ὅσα καλὰ πάντα ἡμῖν γέγονε, τῶν τε ἀπείρων καὶ τῶν πέρας ἐχόντων συμμειχθέντων;", "st": "26b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς δ᾽ οὔ;", "st": "26b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ ἄλλα γε δὴ μυρία ἐπιλείπω λέγων, οἷον μεθ᾽ ὑγιείας κάλλος καὶ ἰσχύν, καὶ ἐν ψυχαῖς αὖ πάμπολλα ἕτερα καὶ πάγκαλα. ὕβριν γάρ που καὶ σύμπασαν πάντων πονηρίαν αὕτη κατιδοῦσα ἡ θεός, ὦ καλὲ Φίληβε, πέρας οὔτε ἡδονῶν οὐδὲν οὔτε πλησμονῶν ἐνὸν ἐν αὐτοῖς, νόμον καὶ τάξιν πέρας ἔχοντ᾽ ἔθετο: καὶ σὺ μὲν ἀποκναῖσαι φῂς", "st": "26b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> αὐτήν, ἐγὼ δὲ τοὐναντίον ἀποσῶσαι λέγω. σοὶ δέ, ὦ Πρώταρχε, πῶς φαίνεται;", "st": "26c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ μάλα, ὦ Σώκρατες, ἔμοιγε κατὰ νοῦν.", "st": "26c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τὰ μὲν δὴ τρία ταῦτα εἴρηκα, εἰ συννοεῖς.", "st": "26c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀλλ᾽ οἶμαι κατανοεῖν: ἓν μὲν γάρ μοι δοκεῖς τὸ ἄπειρον λέγειν, ἓν δὲ καὶ δεύτερον τὸ πέρας ἐν τοῖς οὖσι: τρίτον δὲ οὐ σφόδρα κατέχω τί βούλει φράζειν.", "st": "26c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ γὰρ πλῆθός σε, ὦ θαυμάσιε, ἐξέπληξε τῆς τοῦ τρίτου γενέσεως: καίτοι πολλά γε καὶ τὸ ἄπειρον παρέσχετο", "st": "26c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> γένη, ὅμως δ᾽ ἐπισφραγισθέντα τῷ τοῦ μᾶλλον καὶ ἐναντίου γένει ἓν ἐφάνη.", "st": "26d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀληθῆ.", "st": "26d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν τό γε πέρας οὔτε πολλὰ εἶχεν, οὔτ᾽ ἐδυσκολαίνομεν ὡς οὐκ ἦν ἓν φύσει.", "st": "26d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς γὰρ ἄν;", "st": "26d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδαμῶς. ἀλλὰ τρίτον φάθι με λέγειν, ἓν τοῦτο τιθέντα τὸ τούτων ἔκγονον ἅπαν, γένεσιν εἰς οὐσίαν ἐκ τῶν μετὰ τοῦ πέρατος ἀπειργασμένων μέτρων.", "st": "26d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἔμαθον.", "st": "26d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ δὴ πρὸς τρισὶ τέταρτόν τι τότε ἔφαμεν εἶναι γένος σκεπτέον: κοινὴ δ᾽ ἡ σκέψις. ὅρα γὰρ εἴ σοι δοκεῖ ἀναγκαῖον εἶναι πάντα τὰ γιγνόμενα διά τινα αἰτίαν γίγνεσθαι.", "st": "26e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἔμοιγε: πῶς γὰρ ἂν χωρὶς τούτου γίγνοιτο;", "st": "26e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἡ τοῦ ποιοῦντος φύσις οὐδὲν πλὴν ὀνόματι τῆς αἰτίας διαφέρει, τὸ δὲ ποιοῦν καὶ τὸ αἴτιον ὀρθῶς ἂν εἴη λεγόμενον ἕν;", "st": "26e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθῶς.", "st": "26e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν τό γε ποιούμενον αὖ καὶ τὸ γιγνόμενον οὐδὲν πλὴν ὀνόματι, καθάπερ τὸ νυνδή, διαφέρον εὑρήσομεν. ἢ πῶς;", "st": "27a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὕτως.", "st": "27a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ οὖν ἡγεῖται μὲν τὸ ποιοῦν ἀεὶ κατὰ φύσιν, τὸ δὲ ποιούμενον ἐπακολουθεῖ γιγνόμενον ἐκείνῳ;", "st": "27a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ γε.", "st": "27a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἄλλο ἄρα καὶ οὐ ταὐτὸν αἰτία τ᾽ ἐστὶ καὶ τὸ δουλεῦον εἰς γένεσιν αἰτίᾳ.", "st": "27a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν;", "st": "27a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τὰ μὲν γιγνόμενα καὶ ἐξ ὧν γίγνεται πάντα τὰ τρία παρέσχετο ἡμῖν γένη;", "st": "27a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ μάλα.", "st": "27a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ δὲ δὴ πάντα ταῦτα δημιουργοῦν λέγομεν τέταρτον, τὴν αἰτίαν, ὡς ἱκανῶς ἕτερον ἐκείνων δεδηλωμένον;", "st": "27b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἕτερον γὰρ οὖν.", "st": "27b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὀρθῶς μὴν ἔχει, διωρισμένων τῶν τεττάρων, ἑνὸς ἑκάστου μνήμης ἕνεκα ἐφεξῆς αὐτὰ καταριθμήσασθαι.", "st": "27b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν;", "st": "27b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πρῶτον μὲν τοίνυν ἄπειρον λέγω, δεύτερον δὲ πέρας, ἔπειτ᾽ ἐκ τούτων τρίτον μεικτὴν καὶ γεγενημένην οὐσίαν: τὴν δὲ τῆς μείξεως αἰτίαν καὶ γενέσεως τετάρτην", "st": "27b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> λέγων ἆρα μὴ πλημμελοίην ἄν τι;", "st": "27c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ πῶς;", "st": "27c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> φέρε δή, τὸ μετὰ τοῦθ᾽ ἡμῖν τίς ὁ λόγος, καὶ τί ποτε βουληθέντες εἰς ταῦτα ἀφικόμεθα; ἆρ᾽ οὐ τόδε ἦν; δευτερεῖα ἐζητοῦμεν πότερον ἡδονῆς γίγνοιτ᾽ ἂν ἢ φρονήσεως. οὐχ οὕτως ἦν;", "st": "27c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὕτω μὲν οὖν.", "st": "27c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ οὖν ἴσως νῦν, ἐπειδὴ ταῦτα οὕτω διειλόμεθα, κάλλιον ἂν καὶ τὴν κρίσιν ἐπιτελεσαίμεθα πρώτου πέρι καὶ δευτέρου, περὶ ὧν δὴ τὸ πρῶτον ἠμφεσβητήσαμεν;", "st": "27c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἴσως.", "st": "27c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἴθι δή: νικῶντα μὲν ἔθεμέν που τὸν μεικτὸν βίον ἡδονῆς τε καὶ φρονήσεως. ἦν οὕτως;", "st": "27d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἦν.", "st": "27d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τοῦτον μὲν τὸν βίον ὁρῶμέν που τίς τέ ἐστι καὶ ὁποίου γένους;", "st": "27d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς γὰρ οὔ;", "st": "27d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μέρος γ᾽ αὐτὸν φήσομεν εἶναι τοῦ τρίτου οἶμαι γένους: οὐ γὰρ [ὁ] δυοῖν τινοῖν ἐστι [μικτὸς ἐκεῖνος] ἀλλὰ συμπάντων τῶν ἀπείρων ὑπὸ τοῦ πέρατος δεδεμένων, ὥστε ὀρθῶς ὁ νικηφόρος οὗτος βίος μέρος ἐκείνου γίγνοιτ᾽ ἄν.", "st": "27d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθότατα μὲν οὖν.", "st": "27d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> εἶεν: τί δὲ ὁ σός, ὦ Φίληβε, ἡδὺς καὶ ἄμεικτος ὤν; ἐν τίνι γένει τῶν εἰρημένων λεγόμενος ὀρθῶς ἄν ποτε λέγοιτο; ὧδε δ᾽ ἀπόκριναί μοι πρὶν ἀποφήνασθαι.", "st": "27e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Φίληβος:<\/span> λέγε μόνον.", "st": "27e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἡδονὴ καὶ λύπη πέρας ἔχετον, ἢ τῶν τὸ μᾶλλόν τε καὶ ἧττον δεχομένων ἐστόν;", "st": "27e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Φίληβος:<\/span> ναί, τῶν τὸ μᾶλλον, ὦ Σώκρατες: οὐ γὰρ ἂν ἡδονὴ πᾶν ἀγαθὸν ἦν, εἰ μὴ ἄπειρον ἐτύγχανε πεφυκὸς καὶ πλήθει καὶ τῷ μᾶλλον.", "st": "27e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδέ γ᾽ ἄν, ὦ Φίληβε, λύπη πᾶν κακόν: ὥστ᾽ ἄλλο τι νῷν σκεπτέον ἢ τὴν τοῦ ἀπείρου φύσιν ὡς παρέχεταί τι μέρος ταῖς ἡδοναῖς ἀγαθοῦ. τούτω δή σοι τῶν ἀπεράντων γε γένους ἔστων: φρόνησιν δὲ καὶ ἐπιστήμην καὶ νοῦν εἰς τί ποτε τῶν προειρημένων, ὦ Πρώταρχέ τε καὶ Φίληβε, νῦν θέντες οὐκ ἂν ἀσεβοῖμεν; οὐ γάρ μοι δοκεῖ σμικρὸς ἡμῖν εἶναι ὁ κίνδυνος κατορθώσασι καὶ μὴ περὶ τὸ νῦν ἐρωτώμενον.", "st": "28a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Φίληβος:<\/span> σεμνύνεις γάρ, ὦ Σώκρατες, τὸν σεαυτοῦ θεόν.", "st": "28b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ γὰρ σύ, ὦ ἑταῖρε, τὴν σαυτοῦ: τὸ δ᾽ ἐρωτώμενον ὅμως ἡμῖν λεκτέον.", "st": "28b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθῶς τοι λέγει Σωκράτης, ὦ Φίληβε, καὶ αὐτῷ πειστέον.", "st": "28b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Φίληβος:<\/span> οὐκοῦν ὑπὲρ ἐμοῦ σύ, Πρώταρχε, προῄρησαι λέγειν;", "st": "28b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ γε: νῦν μέντοι σχεδὸν ἀπορῶ, καὶ δέομαί γε, ὦ Σώκρατες, αὐτόν σε ἡμῖν γενέσθαι προφήτην, ἵνα μηδὲν ἡμεῖς σοι περὶ τὸν ἀγωνιστὴν ἐξαμαρτάνοντες παρὰ μέλος φθεγξώμεθά τι.", "st": "28b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πειστέον, ὦ Πρώταρχε: οὐδὲ γὰρ χαλεπὸν οὐδὲν ἐπιτάττεις. ἀλλ᾽ ὄντως σε ἐγώ, καθάπερ εἶπε Φίληβος, σεμνύνων ἐν τῷ παίζειν ἐθορύβησα, νοῦν καὶ ἐπιστήμην ἐρόμενος ὁποίου γένους εἶεν;", "st": "28c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> παντάπασί γε, ὦ Σώκρατες.", "st": "28c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ μὴν ῥᾴδιον: πάντες γὰρ συμφωνοῦσιν οἱ σοφοί, ἑαυτοὺς ὄντως σεμνύνοντες, ὡς νοῦς ἐστι βασιλεὺς ἡμῖν οὐρανοῦ τε καὶ γῆς. καὶ ἴσως εὖ λέγουσι. διὰ μακροτέρων δ᾽, εἰ βούλει, τὴν σκέψιν αὐτοῦ τοῦ γένους ποιησώμεθα.", "st": "28c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγ᾽ ὅπως βούλει, μηδὲν μῆκος ἡμῖν ὑπολογιζόμενος, ὦ Σώκρατες, ὡς οὐκ ἀπεχθησόμενος.", "st": "28d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καλῶς εἶπες. ἀρξώμεθα δέ πως ὧδε ἐπανερωτῶντες.", "st": "28d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς;", "st": "28d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πότερον, ὦ Πρώταρχε, τὰ σύμπαντα καὶ τόδε τὸ καλούμενον ὅλον ἐπιτροπεύειν φῶμεν τὴν τοῦ ἀλόγου καὶ εἰκῇ δύναμιν καὶ τὸ ὅπῃ ἔτυχεν, ἢ τἀναντία, καθάπερ οἱ πρόσθεν ἡμῶν ἔλεγον, νοῦν καὶ φρόνησίν τινα θαυμαστὴν συντάττουσαν διακυβερνᾶν;", "st": "28d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὐδὲν τῶν αὐτῶν, ὦ θαυμάσιε Σώκρατες: ὃ μὲν γὰρ σὺ νῦν λέγεις, οὐδὲ ὅσιον εἶναί μοι φαίνεται. τὸ δὲ νοῦν πάντα διακοσμεῖν αὐτὰ φάναι καὶ τῆς ὄψεως τοῦ κόσμου καὶ ἡλίου καὶ σελήνης καὶ ἀστέρων καὶ πάσης τῆς περιφορᾶς ἄξιον, καὶ οὐκ ἄλλως ἔγωγ᾽ ἄν ποτε περὶ αὐτῶν εἴποιμι οὐδ᾽ ἂν δοξάσαιμι.", "st": "28e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> βούλει δῆτά τι καὶ ἡμεῖς τοῖς ἔμπροσθεν ὁμολογούμενον", "st": "28e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> συμφήσωμεν ὡς ταῦθ᾽ οὕτως ἔχει, καὶ μὴ μόνον οἰώμεθα δεῖν τἀλλότρια ἄνευ κινδύνου λέγειν, ἀλλὰ καὶ συγκινδυνεύωμεν καὶ μετέχωμεν τοῦ ψόγου, ὅταν ἀνὴρ δεινὸς φῇ ταῦτα μὴ οὕτως ἀλλ᾽ ἀτάκτως ἔχειν;", "st": "29a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς γὰρ οὐκ ἂν βουλοίμην;", "st": "29a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἴθι δή, τὸν ἐπιόντα περὶ τούτων νῦν ἡμῖν λόγον ἄθρει.", "st": "29a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγε μόνον.", "st": "29a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὰ περὶ τὴν τῶν σωμάτων φύσιν ἁπάντων τῶν ζῴων, πῦρ καὶ ὕδωρ καὶ πνεῦμα καθορῶμέν που καὶ γῆν καθάπερ οἱ χειμαζόμενοι, φασίν, ἐνόντα ἐν τῇ συστάσει.", "st": "29a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ μάλα: χειμαζόμεθα γὰρ ὄντως ὑπ᾽ ἀπορίας ἐν τοῖς νῦν λόγοις.", "st": "29b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> φέρε δή, περὶ ἑκάστου τῶν παρ᾽ ἡμῖν λαβὲ τὸ τοιόνδε.", "st": "29b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ποῖον;", "st": "29b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὅτι μικρόν τε τούτων ἕκαστον παρ᾽ ἡμῖν ἔνεστι καὶ φαῦλον καὶ οὐδαμῇ οὐδαμῶς εἰλικρινὲς ὂν καὶ τὴν δύναμιν οὐκ ἀξίαν τῆς φύσεως ἔχον. ἐν ἑνὶ δὲ λαβὼν περὶ πάντων νόει ταὐτόν. οἷον πῦρ ἔστι μέν που παρ᾽ ἡμῖν, ἔστι δ᾽ ἐν τῷ παντί.", "st": "29b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν;", "st": "29b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν σμικρὸν μέν τι τὸ παρ᾽ ἡμῖν καὶ ἀσθενὲς καὶ φαῦλον, τὸ δ᾽ ἐν τῷ παντὶ πλήθει τε θαυμαστὸν καὶ κάλλει καὶ πάσῃ δυνάμει τῇ περὶ τὸ πῦρ οὔσῃ.", "st": "29c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ μάλ᾽ ἀληθὲς ὃ λέγεις.", "st": "29c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί δέ; τρέφεται καὶ γίγνεται ἐκ τούτου καὶ αὔξεται τὸ τοῦ παντὸς πῦρ ὑπὸ τοῦ παρ᾽ ἡμῖν πυρός, ἢ τοὐναντίον ὑπ᾽ ἐκείνου τό τ᾽ ἐμὸν καὶ τὸ σὸν καὶ τὸ τῶν ἄλλων ζῴων ἅπαντ᾽ ἴσχει ταῦτα;", "st": "29c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τοῦτο μὲν οὐδ᾽ ἀποκρίσεως ἄξιον ἐρωτᾷς.", "st": "29c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὀρθῶς: ταὐτὰ γὰρ ἐρεῖς οἶμαι περί τε τῆς ἐν τοῖς ζῴοις γῆς τῆς ἐνθάδε καὶ τῆς ἐν τῷ παντί, καὶ τῶν ἄλλων δὴ πάντων ὅσων ἠρώτησα ὀλίγον ἔμπροσθεν. οὕτως ἀποκρινῇ;", "st": "29d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τίς γὰρ ἀποκρινόμενος ἄλλως ὑγιαίνων ἄν ποτε φανείη;", "st": "29d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> σχεδὸν οὐδ᾽ ὁστισοῦν: ἀλλὰ τὸ μετὰ τοῦτο ἑξῆς ἕπου. πάντα γὰρ ἡμεῖς ταῦτα τὰ νυνδὴ λεχθέντα ἆρ᾽ οὐκ εἰς ἓν συγκείμενα ἰδόντες ἐπωνομάσαμεν σῶμα;", "st": "29d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν;", "st": "29d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ταὐτὸν δὴ λαβὲ καὶ περὶ τοῦδε ὃν κόσμον λέγομεν: [διὰ] τὸν αὐτὸν γὰρ τρόπον ἂν εἴη που σῶμα, σύνθετον ὂν ἐκ τῶν αὐτῶν.", "st": "29e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθότατα λέγεις.", "st": "29e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πότερον οὖν ἐκ τούτου τοῦ σώματος ὅλως τὸ παρ᾽ ἡμῖν σῶμα ἢ ἐκ τοῦ παρ᾽ ἡμῖν τοῦτο τρέφεταί τε καὶ ὅσα νυνδὴ περὶ αὐτῶν εἴπομεν εἴληφέν τε καὶ ἔχει;", "st": "29e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ τοῦθ᾽ ἕτερον, ὦ Σώκρατες, οὐκ ἄξιον ἐρωτήσεως.", "st": "29e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί δέ; τόδε ἆρα ἄξιον; ἢ πῶς ἐρεῖς;", "st": "30a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγε τὸ ποῖον.", "st": "30a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ παρ᾽ ἡμῖν σῶμα ἆρ᾽ οὐ ψυχὴν φήσομεν ἔχειν;", "st": "30a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> δῆλον ὅτι φήσομεν.", "st": "30a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πόθεν, ὦ φίλε Πρώταρχε, λαβόν, εἴπερ μὴ τό γε τοῦ παντὸς σῶμα ἔμψυχον ὂν ἐτύγχανε, ταὐτά γε ἔχον τούτῳ καὶ ἔτι πάντῃ καλλίονα;", "st": "30a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> δῆλον ὡς οὐδαμόθεν ἄλλοθεν, ὦ Σώκρατες.", "st": "30a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐ γάρ που δοκοῦμέν γε, ὦ Πρώταρχε, τὰ τέτταρα ἐκεῖνα, πέρας καὶ ἄπειρον καὶ κοινὸν καὶ τὸ τῆς αἰτίας γένος", "st": "30a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἐν ἅπασι τέταρτον ἐνόν, τοῦτο ἐν μὲν τοῖς παρ᾽ ἡμῖν ψυχήν τε παρέχον καὶ σωμασκίαν ἐμποιοῦν καὶ πταίσαντος σώματος ἰατρικὴν καὶ ἐν ἄλλοις ἄλλα συντιθὲν καὶ ἀκούμενον πᾶσαν καὶ παντοίαν σοφίαν ἐπικαλεῖσθαι, τῶν δ᾽ αὐτῶν τούτων ὄντων ἐν ὅλῳ τε οὐρανῷ καὶ κατὰ μεγάλα μέρη, καὶ προσέτι καλῶν καὶ εἰλικρινῶν, ἐν τούτοις δ᾽ οὐκ ἄρα μεμηχανῆσθαι τὴν τῶν καλλίστων καὶ τιμιωτάτων φύσιν.", "st": "30b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀλλ᾽ οὐδαμῶς τοῦτό γ᾽ ἂν λόγον ἔχοι.", "st": "30c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν εἰ μὴ τοῦτο, μετ᾽ ἐκείνου τοῦ λόγου ἂν ἑπόμενοι βέλτιον λέγοιμεν ὡς ἔστιν, ἃ πολλάκις εἰρήκαμεν, ἄπειρόν τε ἐν τῷ παντὶ πολύ, καὶ πέρας ἱκανόν, καί τις ἐπ᾽ αὐτοῖς αἰτία οὐ φαύλη, κοσμοῦσά τε καὶ συντάττουσα ἐνιαυτούς τε καὶ ὥρας καὶ μῆνας, σοφία καὶ νοῦς λεγομένη δικαιότατ᾽ ἄν.", "st": "30c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> δικαιότατα δῆτα.", "st": "30c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> σοφία μὴν καὶ νοῦς ἄνευ ψυχῆς οὐκ ἄν ποτε γενοίσθην.", "st": "30c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὐ γὰρ οὖν.", "st": "30c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἐν μὲν τῇ τοῦ Διὸς ἐρεῖς φύσει βασιλικὴν μὲν ψυχήν, βασιλικὸν δὲ νοῦν ἐγγίγνεσθαι διὰ τὴν τῆς αἰτίας δύναμιν, ἐν δ᾽ ἄλλοις ἄλλα καλά, καθ᾽ ὅτι φίλον ἑκάστοις λέγεσθαι.", "st": "30d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> μάλα γε.", "st": "30d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τοῦτον δὴ τὸν λόγον ἡμᾶς μή τι μάτην δόξῃς, ὦ Πρώταρχε, εἰρηκέναι, ἀλλ᾽ ἔστι τοῖς μὲν πάλαι ἀποφηναμένοις ὡς ἀεὶ τοῦ παντὸς νοῦς ἄρχει σύμμαχος ἐκείνοις.", "st": "30d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἔστι γὰρ οὖν.", "st": "30d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τῇ δέ γε ἐμῇ ζητήσει πεπορικὼς ἀπόκρισιν, ὅτι νοῦς", "st": "30d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἐστὶ γένους τῆς τοῦ πάντων αἰτίου λεχθέντος [τῶν τεττάρων, [ὧν] ἦν ἡμῖν ἓν τοῦτο]. ἔχεις γὰρ δήπου νῦν ἡμῶν ἤδη τὴν ἀπόκρισιν.", "st": "30e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἔχω καὶ μάλα ἱκανῶς: καίτοι με ἀποκρινάμενος ἔλαθες.", "st": "30e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀνάπαυλα γάρ, ὦ Πρώταρχε, τῆς σπουδῆς γίγνεται ἐνίοτε ἡ παιδιά.", "st": "30e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καλῶς εἶπες.", "st": "30e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> νῦν δήπου, ὦ ἑταῖρε, οὗ μὲν γένους ἐστὶ καὶ τίνα ποτὲ δύναμιν κέκτηται, σχεδὸν ἐπιεικῶς ἡμῖν τὰ νῦν δεδήλωται.", "st": "31a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν.", "st": "31a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν ἡδονῆς γε ὡσαύτως πάλαι τὸ γένος ἐφάνη.", "st": "31a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ μάλα.", "st": "31a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μεμνώμεθα δὴ καὶ ταῦτα περὶ ἀμφοῖν, ὅτι νοῦς μὲν αἰτίας ἦν συγγενὴς καὶ τούτου σχεδὸν τοῦ γένους, ἡδονὴ δὲ ἄπειρός τε αὐτὴ καὶ τοῦ μήτε ἀρχὴν μήτε μέσα μήτε τέλος ἐν αὑτῷ ἀφ᾽ ἑαυτοῦ ἔχοντος μηδὲ ἕξοντός ποτε γένους.", "st": "31a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> μεμνησόμεθα: πῶς γὰρ οὔ;", "st": "31b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> δεῖ δὴ τὸ μετὰ τοῦτο, ἐν ᾧ τέ ἐστιν ἑκάτερον αὐτοῖν καὶ διὰ τί πάθος γίγνεσθον ὁπόταν γίγνησθον ἰδεῖν ἡμᾶς. πρῶτον τὴν ἡδονήν: ὥσπερ τὸ γένος αὐτῆς πρότερον ἐβασανίσαμεν, οὕτω καὶ ταῦτα πρότερα. λύπης δὲ αὖ χωρὶς τὴν ἡδονὴν οὐκ ἄν ποτε δυναίμεθα ἱκανῶς βασανίσαι.", "st": "31b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀλλ᾽ εἰ ταύτῃ χρὴ πορεύεσθαι, ταύτῃ πορευώμεθα.", "st": "31b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ οὖν σοὶ καθάπερ ἐμοὶ φαίνεται τῆς γενέσεως αὐτῶν πέρι;", "st": "31b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ ποῖον;", "st": "31c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἐν τῷ κοινῷ μοι γένει ἅμα φαίνεσθον λύπη τε καὶ ἡδονὴ γίγνεσθαι κατὰ φύσιν.", "st": "31c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> κοινὸν δέ γε, ὦ φίλε Σώκρατες, ὑπομίμνῃσκε ἡμᾶς τί ποτε τῶν προειρημένων βούλει δηλοῦν.", "st": "31c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἔσται ταῦτ᾽ εἰς δύναμιν, ὦ θαυμάσιε.", "st": "31c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καλῶς εἶπες.", "st": "31c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> κοινὸν τοίνυν ὑπακούωμεν ὃ δὴ τῶν τεττάρων τρίτον ἐλέγομεν.", "st": "31c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὃ μετὰ τὸ ἄπειρον καὶ πέρας ἔλεγες, ἐν ᾧ καὶ ὑγίειαν, οἶμαι δὲ καὶ ἁρμονίαν, ἐτίθεσο;", "st": "31c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> κάλλιστ᾽ εἶπες. τὸν νοῦν δὲ ὅτι μάλιστ᾽ ἤδη πρόσεχε.", "st": "31d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγε μόνον.", "st": "31d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> λέγω τοίνυν τῆς ἁρμονίας μὲν λυομένης ἡμῖν ἐν τοῖς ζῴοις ἅμα λύσιν τῆς φύσεως καὶ γένεσιν ἀλγηδόνων ἐν τῷ τότε γίγνεσθαι χρόνῳ.", "st": "31d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ λέγεις εἰκός.", "st": "31d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πάλιν δὲ ἁρμοττομένης τε καὶ εἰς τὴν αὑτῆς φύσιν ἀπιούσης ἡδονὴν γίγνεσθαι λεκτέον, εἰ δεῖ δι᾽ ὀλίγων περὶ μεγίστων ὅτι τάχιστα ῥηθῆναι.", "st": "31d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οἶμαι μέν σε ὀρθῶς λέγειν, ὦ Σώκρατες, ἐμφανέστερον δὲ ἔτι ταὐτὰ ταῦτα πειρώμεθα λέγειν.", "st": "31e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τὰ δημόσιά που καὶ περιφανῆ ῥᾷστον συννοεῖν;", "st": "31e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ποῖα;", "st": "31e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πείνη μέν που λύσις καὶ λύπη;", "st": "31e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ναί.", "st": "31e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἐδωδὴ δέ, πλήρωσις γιγνομένη πάλιν, ἡδονή;", "st": "31e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ναί.", "st": "31e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> δίψος δ᾽ αὖ φθορὰ καὶ λύπη [καὶ λύσις], ἡ δὲ τοῦ", "st": "31e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὑγροῦ πάλιν τὸ ξηρανθὲν πληροῦσα δύναμις ἡδονή: διάκρισις δέ γ᾽ αὖ καὶ διάλυσις ἡ παρὰ φύσιν, τοῦ πνίγους πάθη, λύπη, κατὰ φύσιν δὲ πάλιν ἀπόδοσίς τε καὶ ψῦξις ἡδονή.", "st": "32a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν.", "st": "32a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ ῥίγους ἡ μὲν παρὰ φύσιν τοῦ ζῴου τῆς ὑγρότητος πῆξις λύπη: πάλιν δ᾽ εἰς ταὐτὸν ἀπιόντων καὶ διακρινομένων ἡ κατὰ φύσιν ὁδὸς ἡδονή. καὶ ἑνὶ λόγῳ σκόπει εἴ σοι μέτριος ὁ λόγος ὃς ἂν φῇ τὸ ἐκ τῆς ἀπείρου καὶ", "st": "32a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πέρατος κατὰ φύσιν ἔμψυχον γεγονὸς εἶδος, ὅπερ ἔλεγον ἐν τῷ πρόσθεν, ὅταν μὲν τοῦτο φθείρηται, τὴν μὲν φθορὰν λύπην εἶναι, τὴν δ᾽ εἰς τὴν αὑτῶν οὐσίαν ὁδόν, ταύτην δὲ αὖ πάλιν τὴν ἀναχώρησιν πάντων ἡδονήν.", "st": "32b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἔστω: δοκεῖ γάρ μοι τύπον γέ τινα ἔχειν.", "st": "32b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τοῦτο μὲν τοίνυν ἓν εἶδος τιθώμεθα λύπης τε καὶ ἡδονῆς ἐν τούτοις τοῖς πάθεσιν ἑκατέροις;", "st": "32b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> κείσθω.", "st": "32b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τίθει τοίνυν αὐτῆς τῆς ψυχῆς κατὰ τὸ τούτων τῶν", "st": "32b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> παθημάτων προσδόκημα τὸ μὲν πρὸ τῶν ἡδέων ἐλπιζόμενον ἡδὺ καὶ θαρραλέον, τὸ δὲ πρὸ τῶν λυπηρῶν φοβερὸν καὶ ἀλγεινόν.", "st": "32c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἔστι γὰρ οὖν τοῦθ᾽ ἡδονῆς καὶ λύπης ἕτερον εἶδος, τὸ χωρὶς τοῦ σώματος αὐτῆς τῆς ψυχῆς διὰ προσδοκίας γιγνόμενον.", "st": "32c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὀρθῶς ὑπέλαβες. ἐν γὰρ τούτοις οἶμαι, κατά γε τὴν ἐμὴν δόξαν, εἰλικρινέσιν τε ἑκατέροις γιγνομένοις, ὡς δοκεῖ, καὶ ἀμείκτοις λύπης τε καὶ ἡδονῆς, ἐμφανὲς ἔσεσθαι", "st": "32c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ περὶ τὴν ἡδονήν, πότερον ὅλον ἐστὶ τὸ γένος ἀσπαστόν, ἢ τοῦτο μὲν ἑτέρῳ τινὶ τῶν προειρημένων δοτέον ἡμῖν γενῶν, ἡδονῇ δὲ καὶ λύπῃ, καθάπερ θερμῷ καὶ ψυχρῷ καὶ πᾶσι τοῖς τοιούτοις, τοτὲ μὲν ἀσπαστέον αὐτά, τοτὲ δὲ οὐκ ἀσπαστέον, ὡς ἀγαθὰ μὲν οὐκ ὄντα, ἐνίοτε δὲ καὶ ἔνια δεχόμενα τὴν τῶν ἀγαθῶν ἔστιν ὅτε φύσιν.", "st": "32d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθότατα λέγεις, ὅτι ταύτῃ πῃ δεῖ διαπορηθῆναι τὸ νῦν μεταδιωκόμενον.", "st": "32d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πρῶτον μὲν τοίνυν τόδε συνίδωμεν: [ὡς] εἴπερ", "st": "32d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὄντως ἔστι τὸ λεγόμενον, διαφθειρομένων μὲν αὐτῶν ἀλγηδών, ἀνασῳζομένων δὲ ἡδονή, τῶν μήτε διαφθειρομένων μήτε ἀνασῳζομένων ἐννοήσωμεν πέρι, τίνα ποτὲ ἕξιν δεῖ τότε ἐν ἑκάστοις εἶναι τοῖς ζῴοις, ὅταν οὕτως ἴσχῃ. σφόδρα δὲ προσέχων τὸν νοῦν εἰπέ: ἆρα οὐ πᾶσα ἀνάγκη πᾶν ἐν τῷ τότε χρόνῳ ζῷον μήτε τι λυπεῖσθαι μήτε ἥδεσθαι μήτε μέγα μήτε σμικρόν;", "st": "32e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀνάγκη μὲν οὖν.", "st": "32e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἔστι τις τρίτη ἡμῶν ἡ τοιαύτη διάθεσις", "st": "32e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> παρά τε τὴν τοῦ χαίροντος καὶ παρὰ τὴν τοῦ λυπουμένου;", "st": "33a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν;", "st": "33a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἄγε δὴ τοίνυν, ταύτης προθυμοῦ μεμνῆσθαι. πρὸς γὰρ τὴν τῆς ἡδονῆς κρίσιν οὐ σμικρὸν μεμνῆσθαι ταύτην ἔσθ᾽ ἡμῖν ἢ μή. βραχὺ δέ τι περὶ αὐτῆς, εἰ βούλει, διαπεράνωμεν.", "st": "33a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγε ποῖον.", "st": "33a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> [τῷ] τὸν τοῦ φρονεῖν [ἑλομένῳ] βίον οἶσθ᾽ ὡς τοῦτον τὸν τρόπον οὐδὲν ἀποκωλύει ζῆν.", "st": "33a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸν τοῦ μὴ χαίρειν μηδὲ λυπεῖσθαι λέγεις;", "st": "33b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἐρρήθη γάρ που τότε ἐν τῇ παραβολῇ τῶν βίων μηδὲν δεῖν μήτε μέγα μήτε σμικρὸν χαίρειν τῷ τὸν τοῦ νοεῖν καὶ φρονεῖν βίον ἑλομένῳ.", "st": "33b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ μάλα οὕτως ἐρρήθη.", "st": "33b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν οὕτως ἂν ἐκείνῳ γε ὑπάρχοι: καὶ ἴσως οὐδὲν ἄτοπον εἰ πάντων τῶν βίων ἐστὶ θειότατος.", "st": "33b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὔκουν εἰκός γε οὔτε χαίρειν θεοὺς οὔτε τὸ ἐναντίον.", "st": "33b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πάνυ μὲν οὖν οὐκ εἰκός: ἄσχημον γοῦν αὐτῶν ἑκάτερον γιγνόμενόν ἐστιν. ἀλλὰ δὴ τοῦτο μὲν ἔτι καὶ εἰς", "st": "33b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> αὖθις ἐπισκεψόμεθα, ἐὰν πρὸς λόγον τι ᾖ, καὶ τῷ νῷ πρὸς τὰ δευτερεῖα, ἐὰν μὴ πρὸς τὰ πρωτεῖα δυνώμεθα προσθεῖναι, προσθήσομεν.", "st": "33c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθότατα λέγεις.", "st": "33c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν τό γε ἕτερον εἶδος τῶν ἡδονῶν, ὃ τῆς ψυχῆς αὐτῆς ἔφαμεν εἶναι, διὰ μνήμης πᾶν ἐστι γεγονός.", "st": "33c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς;", "st": "33c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μνήμην, ὡς ἔοικεν, ὅτι ποτ᾽ ἔστιν πρότερον ἀναληπτέον, καὶ κινδυνεύει πάλιν ἔτι πρότερον αἴσθησιν μνήμης, εἰ μέλλει τὰ περὶ ταῦθ᾽ ἡμῖν κατὰ τρόπον φανερά πῃ γενήσεσθαι.", "st": "33c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς φῄς;", "st": "33d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> θὲς τῶν περὶ τὸ σῶμα ἡμῶν ἑκάστοτε παθημάτων τὰ μὲν ἐν τῷ σώματι κατασβεννύμενα πρὶν ἐπὶ τὴν ψυχὴν διεξελθεῖν ἀπαθῆ ἐκείνην ἐάσαντα, τὰ δὲ δι᾽ ἀμφοῖν ἰόντα καί τινα ὥσπερ σεισμὸν ἐντιθέντα ἴδιόν τε καὶ κοινὸν ἑκατέρῳ.", "st": "33d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> κείσθω.", "st": "33d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὰ μὲν δὴ μὴ δι᾽ ἀμφοῖν ἰόντα ἐὰν τὴν ψυχὴν ἡμῶν φῶμεν λανθάνειν, τὰ δὲ δι᾽ ἀμφοῖν μὴ λανθάνειν, ἆρ᾽ ὀρθότατα ἐροῦμεν;", "st": "33d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς γὰρ οὔ;", "st": "33e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ τοίνυν λεληθέναι μηδαμῶς ὑπολάβῃς ὡς λέγω λήθης ἐνταῦθά που γένεσιν: ἔστι γὰρ λήθη μνήμης ἔξοδος, ἡ δ᾽ ἐν τῷ λεγομένῳ νῦν οὔπω γέγονε. τοῦ δὴ μήτε ὄντος μήτε γεγονότος πω γίγνεσθαι φάναι τινὰ ἀποβολὴν ἄτοπον. ἦ γάρ;", "st": "33e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν;", "st": "33e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὰ τοίνυν ὀνόματα μετάβαλε μόνον.", "st": "33e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς;", "st": "33e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀντὶ μὲν τοῦ λεληθέναι τὴν ψυχήν, ὅταν ἀπαθὴς αὕτη γίγνηται τῶν σεισμῶν τῶν τοῦ σώματος, ἣν νῦν λήθην", "st": "33e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καλεῖς ἀναισθησίαν ἐπονόμασον.", "st": "34a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἔμαθον.", "st": "34a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ δ᾽ ἐν ἑνὶ πάθει τὴν ψυχὴν καὶ τὸ σῶμα κοινῇ γιγνόμενον κοινῇ καὶ κινεῖσθαι, ταύτην δ᾽ αὖ τὴν κίνησιν ὀνομάζων αἴσθησιν οὐκ ἀπὸ τρόπου φθέγγοι᾽ ἄν.", "st": "34a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀληθέστατα λέγεις.", "st": "34a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἤδη μανθάνομεν ὃ βουλόμεθα καλεῖν τὴν αἴσθησιν;", "st": "34a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν;", "st": "34a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> σωτηρίαν τοίνυν αἰσθήσεως τὴν μνήμην λέγων ὀρθῶς ἄν τις λέγοι κατά γε τὴν ἐμὴν δόξαν.", "st": "34a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθῶς γὰρ οὖν.", "st": "34b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μνήμης δὲ ἀνάμνησιν ἆρ᾽ οὐ διαφέρουσαν λέγομεν;", "st": "34b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἴσως.", "st": "34b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ οὖν οὐ τόδε;", "st": "34b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ ποῖον;", "st": "34b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὅταν ἃ μετὰ τοῦ σώματος ἔπασχέν ποθ᾽ ἡ ψυχή, ταῦτ᾽ ἄνευ τοῦ σώματος αὐτὴ ἐν ἑαυτῇ ὅτι μάλιστα ἀναλαμβάνῃ, τότε ἀναμιμνῄσκεσθαί που λέγομεν. ἦ γάρ;", "st": "34b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν.", "st": "34b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν καὶ ὅταν ἀπολέσασα μνήμην εἴτ᾽ αἰσθήσεως εἴτ᾽ αὖ μαθήματος αὖθις ταύτην ἀναπολήσῃ πάλιν", "st": "34b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> αὐτὴ ἐν ἑαυτῇ, καὶ ταῦτα σύμπαντα ἀναμνήσεις [καὶ μνήμας] που λέγομεν.", "st": "34c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθῶς λέγεις.", "st": "34c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὗ δὴ χάριν ἅπαντ᾽ εἴρηται ταῦτ᾽, ἔστι τόδε.", "st": "34c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ ποῖον;", "st": "34c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἵνα πῃ τὴν ψυχῆς ἡδονὴν χωρὶς σώματος ὅτι μάλιστα καὶ ἐναργέστατα λάβοιμεν, καὶ ἅμα ἐπιθυμίαν: διὰ γὰρ τούτων πως ταῦτα ἀμφότερα ἔοικεν δηλοῦσθαι.", "st": "34c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγωμεν τοίνυν, ὦ Σώκρατες, ἤδη τὸ μετὰ ταῦτα.", "st": "34c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πολλά γε περὶ γένεσιν ἡδονῆς καὶ πᾶσαν [τὴν]", "st": "34c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μορφὴν αὐτῆς ἀναγκαῖον, ὡς ἔοικε, λέγοντας σκοπεῖν. καὶ γὰρ νῦν πρότερον ἔτι φαίνεται ληπτέον ἐπιθυμίαν εἶναι τί ποτ᾽ ἔστι καὶ ποῦ γίγνεται.", "st": "34d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> σκοπῶμεν τοίνυν: οὐδὲν γὰρ ἀπολοῦμεν.", "st": "34d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀπολοῦμεν μὲν οὖν καὶ] ταῦτά γε, ὦ Πρώταρχε: εὑρόντες ὃ νῦν ζητοῦμεν, ἀπολοῦμεν τὴν περὶ αὐτὰ ταῦτα ἀπορίαν.", "st": "34d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθῶς ἠμύνω: τὸ δ᾽ ἐφεξῆς τούτοις πειρώμεθα λέγειν.", "st": "34d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν νυνδὴ πείνην τε καὶ δίψος καὶ πολλὰ ἕτερα", "st": "34d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τοιαῦτα ἔφαμεν εἶναί τινας ἐπιθυμίας;", "st": "34e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> σφόδρα γε.", "st": "34e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πρὸς τί ποτε ἄρα ταὐτὸν βλέψαντες οὕτω πολὺ διαφέροντα ταῦθ᾽ ἑνὶ προσαγορεύομεν ὀνόματι;", "st": "34e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> μὰ Δί᾽ οὐ ῥᾴδιον ἴσως εἰπεῖν, ὦ Σώκρατες, ἀλλ᾽ ὅμως λεκτέον.", "st": "34e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἐκεῖθεν δὴ ἐκ τῶν αὐτῶν πάλιν ἀναλάβωμεν.", "st": "34e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πόθεν δή;", "st": "34e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> διψῇ γέ που λέγομεν ἑκάστοτέ τι;", "st": "34e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς δ᾽ οὔ;", "st": "34e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τοῦτο δέ γ᾽ ἐστὶ κενοῦται;", "st": "34e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν;", "st": "34e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ οὖν τὸ δίψος ἐστὶν ἐπιθυμία;", "st": "34e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ναί, πώματός γε.", "st": "34e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πώματος, ἢ πληρώσεως πώματος;", "st": "35a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οἶμαι μὲν πληρώσεως.", "st": "35a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὁ κενούμενος ἡμῶν ἄρα, ὡς ἔοικεν, ἐπιθυμεῖ τῶν ἐναντίων ἢ πάσχει: κενούμενος γὰρ ἐρᾷ πληροῦσθαι.", "st": "35a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> σαφέστατά γε.", "st": "35a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί οὖν; ὁ τὸ πρῶτον κενούμενος ἔστιν ὁπόθεν εἴτ᾽ αἰσθήσει πληρώσεως ἐφάπτοιτ᾽ ἂν εἴτε μνήμῃ, τούτου ὃ μήτ᾽ ἐν τῷ νῦν χρόνῳ πάσχει μήτ᾽ ἐν τῷ πρόσθεν πώποτε ἔπαθεν;", "st": "35a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ πῶς;", "st": "35a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ μὴν ὅ γε ἐπιθυμῶν τινὸς ἐπιθυμεῖ, φαμέν.", "st": "35b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς γὰρ οὔ;", "st": "35b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκ ἄρα ὅ γε πάσχει, τούτου ἐπιθυμεῖ. διψῇ γάρ, τοῦτο δὲ κένωσις: ὁ δ᾽ ἐπιθυμεῖ πληρώσεως.", "st": "35b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ναί.", "st": "35b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πληρώσεώς γ᾽ ἄρα πῄ τι τῶν τοῦ διψῶντος ἂν ἐφάπτοιτο.", "st": "35b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀναγκαῖον.", "st": "35b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ μὲν δὴ σῶμα ἀδύνατον: κενοῦται γάρ που.", "st": "35b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ναί.", "st": "35b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὴν ψυχὴν ἄρα τῆς πληρώσεως ἐφάπτεσθαι λοιπόν,", "st": "35b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τῇ μνήμῃ δῆλον ὅτι: τῷ γὰρ ἂν ἔτ᾽ ἄλλῳ ἐφάψαιτο;", "st": "35c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> σχεδὸν οὐδενί.", "st": "35c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μανθάνομεν οὖν ὃ συμβέβηχ᾽ ἡμῖν ἐκ τούτων τῶν λόγων;", "st": "35c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ ποῖον;", "st": "35c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> σώματος ἐπιθυμίαν οὔ φησιν ἡμῖν οὗτος ὁ λόγος γίγνεσθαι.", "st": "35c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς;", "st": "35c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὅτι τοῖς ἐκείνου παθήμασιν ἐναντίαν ἀεὶ παντὸς ζῴου μηνύει τὴν ἐπιχείρησιν.", "st": "35c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ μάλα.", "st": "35c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἡ δ᾽ ὁρμή γε ἐπὶ τοὐναντίον ἄγουσα ἢ τὰ παθήματα δηλοῖ που μνήμην οὖσαν τῶν τοῖς παθήμασιν ἐναντίων.", "st": "35c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ γε.", "st": "35c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὴν ἄρα ἐπάγουσαν ἐπὶ τὰ ἐπιθυμούμενα ἀποδείξας μνήμην ὁ λόγος ψυχῆς σύμπασαν τήν τε ὁρμὴν καὶ ἐπιθυμίαν καὶ τὴν ἀρχὴν τοῦ ζῴου παντὸς ἀπέφηνεν.", "st": "35d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθότατα.", "st": "35d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> διψῆν ἄρα ἡμῶν τὸ σῶμα ἢ πεινῆν ἤ τι τῶν τοιούτων πάσχειν οὐδαμῇ ὁ λόγος αἱρεῖ.", "st": "35d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀληθέστατα.", "st": "35d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἔτι δὴ καὶ τόδε περὶ ταὐτὰ ταῦτα κατανοήσωμεν. βίου γὰρ εἶδός τί μοι φαίνεται βούλεσθαι δηλοῦν ὁ λόγος ἡμῖν ἐν τούτοις αὐτοῖς.", "st": "35d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἐν τίσι καὶ ποίου πέρι βίου φράζεις;", "st": "35e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἐν τῷ πληροῦσθαι καὶ κενοῦσθαι καὶ πᾶσιν ὅσα περὶ σωτηρίαν τέ ἐστι τῶν ζῴων καὶ τὴν φθοράν, καὶ εἴ τις τούτων ἐν ἑκατέρῳ γιγνόμενος ἡμῶν ἀλγεῖ, τοτὲ δὲ χαίρει κατὰ τὰς μεταβολάς.", "st": "35e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἔστι ταῦτα.", "st": "35e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί δ᾽ ὅταν ἐν μέσῳ τούτων γίγνηται;", "st": "35e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς ἐν μέσῳ;", "st": "35e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> διὰ μὲν τὸ πάθος ἀλγῇ, μεμνῆται δὲ τῶν ἡδέων ⟨ὧν⟩ γενομένων παύοιτ᾽ ἂν τῆς ἀλγηδόνος, πληρῶται δὲ μήπω: τί", "st": "35e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τότε; φῶμεν ἢ μὴ φῶμεν αὐτὸν ἐν μέσῳ τῶν παθημάτων εἶναι;", "st": "36a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> φῶμεν μὲν οὖν.", "st": "36a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πότερον ἀλγοῦνθ᾽ ὅλως ἢ χαίροντα;", "st": "36a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> μὰ Δί᾽, ἀλλὰ διπλῇ τινὶ λύπῃ λυπούμενον, κατὰ μὲν τὸ σῶμα ἐν τῷ παθήματι, κατὰ δὲ τὴν ψυχὴν προσδοκίας τινὶ πόθῳ.", "st": "36a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πῶς, ὦ Πρώταρχε, τὸ διπλοῦν τῆς λύπης εἶπες; ἆρ᾽ οὐκ ἔστι μὲν ὅτε τις ἡμῶν κενούμενος ἐν ἐλπίδι φανερᾷ τοῦ", "st": "36a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πληρωθήσεσθαι καθέστηκε, τοτὲ δὲ τοὐναντίον ἀνελπίστως ἔχει;", "st": "36b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ μάλα γε.", "st": "36b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μῶν οὖν οὐχὶ ἐλπίζων μὲν πληρωθήσεσθαι τῷ μεμνῆσθαι δοκεῖ σοι χαίρειν, ἅμα δὲ κενούμενος ἐν τούτοις [τοῖς χρόνοις] ἀλγεῖν;", "st": "36b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀνάγκη.", "st": "36b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τότε ἄρ᾽ ἄνθρωπος καὶ τἆλλα ζῷα λυπεῖταί τε ἅμα καὶ χαίρει.", "st": "36b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> κινδυνεύει.", "st": "36b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί δ᾽ ὅταν ἀνελπίστως ἔχῃ κενούμενος τεύξεσθαι πληρώσεως; ἆρ᾽ οὐ τότε τὸ διπλοῦν γίγνοιτ᾽ ἂν περὶ τὰς λύπας πάθος, ὃ σὺ νυνδὴ κατιδὼν ᾠήθης ἁπλῶς εἶναι", "st": "36b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> διπλοῦν;", "st": "36c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀληθέστατα, ὦ Σώκρατες.", "st": "36c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ταύτῃ δὴ τῇ σκέψει τούτων τῶν παθημάτων τόδε χρησώμεθα.", "st": "36c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ ποῖον;", "st": "36c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πότερον ἀληθεῖς ταύτας τὰς λύπας τε καὶ ἡδονὰς ἢ ψευδεῖς εἶναι λέξομεν; ἢ τὰς μέν τινας ἀληθεῖς, τὰς δ᾽ οὔ;", "st": "36c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς δ᾽, ὦ Σώκρατες, ἂν εἶεν ψευδεῖς ἡδοναὶ ἢ λῦπαι;", "st": "36c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πῶς δέ, ὦ Πρώταρχε, φόβοι ἂν ἀληθεῖς ἢ ψευδεῖς, ἢ προσδοκίαι ἀληθεῖς ἢ μή, ἢ δόξαι ἀληθεῖς ἢ ψευδεῖς;", "st": "36c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> δόξας μὲν ἔγωγ᾽ ἄν που συγχωροίην, τὰ δ᾽ ἕτερα ταῦτ᾽ οὐκ ἄν.", "st": "36d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πῶς φῄς; λόγον μέντοι τινὰ κινδυνεύομεν οὐ πάνυ σμικρὸν ἐπεγείρειν.", "st": "36d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀληθῆ λέγεις.", "st": "36d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ᾽ εἰ πρὸς τὰ παρεληλυθότα, ὦ παῖ ‘κείνου τἀνδρός, προσήκοντα, τοῦτο σκεπτέον.", "st": "36d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἴσως τοῦτό γε.", "st": "36d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> χαίρειν τοίνυν δεῖ λέγειν τοῖς ἄλλοις μήκεσιν ἢ καὶ ὁτῳοῦν τῶν παρὰ τὸ προσῆκον λεγομένων.", "st": "36d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθῶς.", "st": "36d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> λέγε δή μοι: θαῦμα γάρ μέ γε ἔχει διὰ τέλους ἀεὶ περὶ τὰ αὐτὰ ἃ νυνδὴ προυθέμεθα ἀπορήματα. πῶς δὴ φῄς; ψευδεῖς, αἱ δ᾽ ἀληθεῖς οὐκ εἰσὶν ἡδοναί;", "st": "36e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς γὰρ ἄν;", "st": "36e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὔτε δὴ ὄναρ οὔθ᾽ ὕπαρ, ὡς φῄς, [ἐστιν] οὔτ᾽ ἐν μανίαις οὔτ᾽ ἐν παραφροσύναις οὐδεὶς ἔσθ᾽ ὅστις ποτὲ δοκεῖ μὲν χαίρειν, χαίρει δὲ οὐδαμῶς, οὐδ᾽ αὖ δοκεῖ μὲν λυπεῖσθαι, λυπεῖται δ᾽ οὔ.", "st": "36e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνθ᾽ οὕτω ταῦτα, ὦ Σώκρατες, ἔχειν πάντες ὑπειλήφαμεν.", "st": "36e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ οὖν ὀρθῶς; ἢ σκεπτέον εἴτ᾽ ὀρθῶς εἴτε μὴ ταῦτα λέγεται;", "st": "36e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> σκεπτέον, ὥς γ᾽ ἐγὼ φαίην ἄν.", "st": "36e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> διορισώμεθα δὴ σαφέστερον ἔτι τὸ νυνδὴ λεγόμενον ἡδονῆς τε πέρι καὶ δόξης. ἔστιν γάρ πού τι δοξάζειν ἡμῖν;", "st": "37a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ναί.", "st": "37a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ ἥδεσθαι;", "st": "37a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ναί.", "st": "37a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν καὶ τὸ δοξαζόμενόν ἐστί τι;", "st": "37a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς δ᾽ οὔ;", "st": "37a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ τό γε ᾧ τὸ ἡδόμενον ἥδεται;", "st": "37a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ πάνυ γε.", "st": "37a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τὸ δοξάζον, ἄντε ὀρθῶς ἄντε μὴ ὀρθῶς δοξάζῃ, τό γε δοξάζειν ὄντως οὐδέποτε ἀπόλλυσιν.", "st": "37a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς γὰρ ἄν;", "st": "37b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ τὸ ἡδόμενον, ἄντε ὀρθῶς ἄντε μὴ ὀρθῶς ἥδηται, τό γε ὄντως ἥδεσθαι δῆλον ὡς οὐδέποτ᾽ ἀπολεῖ.", "st": "37b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ναί, καὶ τοῦθ᾽ οὕτως ἔχει.", "st": "37b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὅτῳ ποτὲ οὖν δὴ τρόπῳ δόξα ψευδής τε καὶ ἀληθὴς ἡμῖν φιλεῖ γίγνεσθαι, τὸ δὲ τῆς ἡδονῆς μόνον ἀληθές, δοξάζειν δ᾽ ὄντως καὶ χαίρειν ἀμφότερα ὁμοίως εἴληχεν ⟨σκεπτέον⟩.", "st": "37b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> σκεπτέον.", "st": "37b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ ὅτι δόξῃ μὲν ἐπιγίγνεσθον ψεῦδός τε καὶ", "st": "37b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀληθές, καὶ ἐγένετο οὐ μόνον δόξα διὰ ταῦτα ἀλλὰ καὶ ποιά τις ἑκατέρα, σκεπτέον φῂς τοῦτ᾽ εἶναι;", "st": "37c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ναί.", "st": "37c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πρὸς δέ γε τούτοις, εἰ καὶ τὸ παράπαν ἡμῖν τὰ μέν ἐστι ποί᾽ ἄττα, ἡδονὴ δὲ καὶ λύπη μόνον ἅπερ ἐστί, ποιώ τινε δὲ οὐ γίγνεσθον, καὶ ταῦθ᾽ ἡμῖν διομολογητέον.", "st": "37c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> δῆλον.", "st": "37c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ᾽ οὐδὲν τοῦτό γε χαλεπὸν ἰδεῖν, ὅτι καὶ ποιώ τινε: πάλαι γὰρ εἴπομεν ὅτι μεγάλαι τε καὶ σμικραὶ καὶ σφόδρα ἑκάτεραι γίγνονται, λῦπαί τε καὶ ἡδοναί.", "st": "37c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> παντάπασι μὲν οὖν.", "st": "37d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἂν δέ γε πονηρία τούτων, ὦ Πρώταρχε, προσγίγνηταί τινι, πονηρὰν μὲν φήσομεν οὕτω γίγνεσθαι δόξαν, πονηρὰν δὲ καὶ ἡδονήν;", "st": "37d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀλλὰ τί μήν, ὦ Σώκρατες;", "st": "37d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί δ᾽, ἂν ὀρθότης ἢ τοὐναντίον ὀρθότητι τινὶ τούτων προσγίγνηται; μῶν οὐκ ὀρθὴν μὲν δόξαν ἐροῦμεν, ἂν ὀρθότητα ἴσχῃ, ταὐτὸν δὲ ἡδονήν;", "st": "37d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀναγκαῖον.", "st": "37d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἂν δέ γε ἁμαρτανόμενον τὸ δοξαζόμενον ᾖ, τὴν δόξαν τότε ἁμαρτάνουσάν γε οὐκ ὀρθὴν ὁμολογητέον οὐδ᾽ ὀρθῶς δοξάζουσαν;", "st": "37e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς γὰρ ἄν;", "st": "37e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί δ᾽, ἂν αὖ λύπην ἤ τινα ἡδονὴν περὶ τὸ ἐφ᾽ ᾧ λυπεῖται ἢ τοὐναντίον ἁμαρτάνουσαν ἐφορῶμεν, ὀρθὴν ἢ χρηστὴν ἤ τι τῶν καλῶν ὀνομάτων αὐτῇ προσθήσομεν;", "st": "37e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀλλ᾽ οὐχ οἷόν τε, εἴπερ ἁμαρτήσεταί γε ἡδονή.", "st": "37e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν ἔοικέν γε ἡδονὴ πολλάκις οὐ μετὰ δόξης ὀρθῆς ἀλλὰ μετὰ ψεύδους ἡμῖν γίγνεσθαι.", "st": "37e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς γὰρ οὔ; καὶ τὴν μὲν δόξαν γε, ὦ Σώκρατες,", "st": "37e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἐν τῷ τοιούτῳ καὶ τότε λέγομεν ψευδῆ, τὴν δ᾽ ἡδονὴν αὐτὴν οὐδεὶς ἄν ποτε προσείποι ψευδῆ.", "st": "38a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ προθύμως ἀμύνεις τῷ τῆς ἡδονῆς, ὦ Πρώταρχε, λόγῳ τὰ νῦν.", "st": "38a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὐδέν γε, ἀλλ᾽ ἅπερ ἀκούω λέγω.", "st": "38a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> διαφέρει δ᾽ ἡμῖν οὐδέν, ὦ ἑταῖρε, ἡ μετὰ δόξης τε ὀρθῆς καὶ μετ᾽ ἐπιστήμης ἡδονὴ τῆς μετὰ τοῦ ψεύδους καὶ ἀγνοίας πολλάκις ἑκάστοις ἡμῶν ἐγγιγνομένης;", "st": "38a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> εἰκὸς γοῦν μὴ σμικρὸν διαφέρειν.", "st": "38b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τῆς δὴ διαφορᾶς αὐτοῖν ἐπὶ θεωρίαν ἔλθωμεν.", "st": "38b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἄγ᾽ ὅπῃ σοι φαίνεται.", "st": "38b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τῇδε δὴ ἄγω.", "st": "38b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῇ;", "st": "38b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> δόξα, φαμέν, ἡμῖν ἔστι μὲν ψευδής, ἔστι δὲ καὶ ἀληθής;", "st": "38b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἔστιν.", "st": "38b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἕπεται μὴν ταύταις, ὃ νυνδὴ ἐλέγομεν, ἡδονὴ καὶ λύπη πολλάκις, ἀληθεῖ καὶ ψευδεῖ δόξῃ λέγω.", "st": "38b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ γε.", "st": "38b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἐκ μνήμης τε καὶ αἰσθήσεως δόξα ἡμῖν καὶ τὸ διαδοξάζειν ἐγχειρεῖν γίγνεθ᾽ ἑκάστοτε;", "st": "38b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ μάλα.", "st": "38c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ οὖν ἡμᾶς ὧδε περὶ ταῦτα ἀναγκαῖον ἡγούμεθ᾽ ἴσχειν;", "st": "38c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς;", "st": "38c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πολλάκις ἰδόντι τινὶ πόρρωθεν μὴ πάνυ σαφῶς τὰ καθορώμενα συμβαίνειν βούλεσθαι κρίνειν φαίης ἂν ταῦθ᾽ ἅπερ ὁρᾷ;", "st": "38c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> φαίην ἄν.", "st": "38c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τὸ μετὰ τοῦτο αὐτὸς αὑτὸν οὗτος ἀνέροιτ᾽ ἂν ὧδε;", "st": "38c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς;", "st": "38c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί ποτ᾽ ἄρ᾽ ἔστι τὸ παρὰ τὴν πέτραν τοῦθ᾽ ἑστάναι", "st": "38c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> φανταζόμενον ὑπό τινι δένδρῳ; ταῦτ᾽ εἰπεῖν ἄν τις πρὸς ἑαυτὸν δοκεῖ σοι, τοιαῦτ᾽ ἄττα κατιδὼν φαντασθέντα αὑτῷ ποτε;", "st": "38d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν;", "st": "38d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ οὖν μετὰ ταῦτα ὁ τοιοῦτος ὡς ἀποκρινόμενος ἂν πρὸς αὑτὸν εἴποι τοῦτο, ὡς ἔστιν ἄνθρωπος, ἐπιτυχῶς εἰπών;", "st": "38d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ πάνυ γε.", "st": "38d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ παρενεχθείς γ᾽ αὖ τάχ᾽ ἂν ὡς ἔστι τινῶν ποιμένων ἔργον τὸ καθορώμενον ἄγαλμα προσείποι.", "st": "38d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> μάλα γε.", "st": "38d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> κἂν μέν τίς γ᾽ αὐτῷ παρῇ, τά τε πρὸς αὑτὸν ῥηθέντα ἐντείνας εἰς φωνὴν πρὸς τὸν παρόντα αὐτὰ ταῦτ᾽ ἂν πάλιν φθέγξαιτο, καὶ λόγος δὴ γέγονεν οὕτως ὃ τότε δόξαν ἐκαλοῦμεν;", "st": "38e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν;", "st": "38e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἂν δ᾽ ἄρα μόνος ᾖ τοῦτο ταὐτὸν πρὸς αὑτὸν διανοούμενος, ἐνίοτε καὶ πλείω χρόνον ἔχων ἐν αὑτῷ πορεύεται.", "st": "38e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν.", "st": "38e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί οὖν; ἆρα σοὶ φαίνεται τὸ περὶ τούτων ὅπερ ἐμοί;", "st": "38e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ ποῖον;", "st": "38e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> δοκεῖ μοι τότε ἡμῶν ἡ ψυχὴ βιβλίῳ τινὶ προσεοικέναι.", "st": "38e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς;", "st": "38e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἡ μνήμη ταῖς αἰσθήσεσι συμπίπτουσα εἰς ταὐτὸν κἀκεῖνα ἃ περὶ ταῦτ᾽ ἐστὶ τὰ παθήματα φαίνονταί μοι σχεδὸν οἷον γράφειν ἡμῶν ἐν ταῖς ψυχαῖς τότε λόγους: καὶ ὅταν μὲν ἀληθῆ γράφῃ [τοῦτο τὸ πάθημα], δόξα τε ἀληθὴς καὶ λόγοι ἀπ᾽ αὐτοῦ συμβαίνουσιν ἀληθεῖς ἐν ἡμῖν γιγνόμενοι: ψευδῆ δ᾽ ὅταν ὁ τοιοῦτος παρ᾽ ἡμῖν γραμματεὺς γράψῃ, τἀναντία τοῖς ἀληθέσιν ἀπέβη.", "st": "39a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν δοκεῖ μοι, καὶ ἀποδέχομαι τὰ ῥηθέντα οὕτως.", "st": "39b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀποδέχου δὴ καὶ ἕτερον δημιουργὸν ἡμῶν ἐν ταῖς ψυχαῖς ἐν τῷ τότε χρόνῳ γιγνόμενον.", "st": "39b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τίνα;", "st": "39b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ζωγράφον, ὃς μετὰ τὸν γραμματιστὴν τῶν λεγομένων εἰκόνας ἐν τῇ ψυχῇ τούτων γράφει.", "st": "39b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς δὴ τοῦτον αὖ καὶ πότε λέγομεν;", "st": "39b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὅταν ἀπ᾽ ὄψεως ἤ τινος ἄλλης αἰσθήσεως τὰ τότε δοξαζόμενα καὶ λεγόμενα ἀπαγαγών τις τὰς τῶν δοξασθέντων", "st": "39b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ λεχθέντων εἰκόνας ἐν αὑτῷ ὁρᾷ πως. ἢ τοῦτο οὐκ ἔστι γιγνόμενον παρ᾽ ἡμῖν;", "st": "39c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> σφόδρα μὲν οὖν.", "st": "39c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν αἱ μὲν τῶν ἀληθῶν δοξῶν καὶ λόγων εἰκόνες ἀληθεῖς, αἱ δὲ τῶν ψευδῶν ψευδεῖς;", "st": "39c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> παντάπασιν.", "st": "39c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> εἰ δὴ ταῦτ᾽ ὀρθῶς εἰρήκαμεν, ἔτι καὶ τόδε ἐπὶ τούτοις σκεψώμεθα.", "st": "39c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ ποῖον;", "st": "39c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> εἰ περὶ μὲν τῶν ὄντων καὶ τῶν γεγονότων ταῦτα ἡμῖν οὕτω πάσχειν ἀναγκαῖον, περὶ δὲ τῶν μελλόντων οὔ;", "st": "39c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> περὶ ἁπάντων μὲν οὖν τῶν χρόνων ὡσαύτως.", "st": "39c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν αἵ γε διὰ τῆς ψυχῆς αὐτῆς ἡδοναὶ καὶ λῦπαι ἐλέχθησαν ἐν τοῖς πρόσθεν ὡς πρὸ τῶν διὰ τοῦ σώματος ἡδονῶν καὶ λυπῶν προγίγνοιντ᾽ ἄν, ὥσθ᾽ ἡμῖν συμβαίνει τὸ προχαίρειν τε καὶ προλυπεῖσθαι περὶ τὸν μέλλοντα χρόνον εἶναι γιγνόμενον;", "st": "39d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀληθέστατα.", "st": "39d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πότερον οὖν τὰ γράμματά τε καὶ ζωγραφήματα, ἃ σμικρῷ πρότερον ἐτίθεμεν ἐν ἡμῖν γίγνεσθαι, περὶ μὲν τὸν", "st": "39d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> γεγονότα καὶ τὸν παρόντα χρόνον ἐστίν, περὶ δὲ τὸν μέλλοντα οὐκ ἔστιν;", "st": "39e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> σφόδρα γε.", "st": "39e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρα σφόδρα λέγεις, ὅτι πάντ᾽ ἐστὶ ταῦτα ἐλπίδες εἰς τὸν ἔπειτα χρόνον οὖσαι, ἡμεῖς δ᾽ αὖ διὰ παντὸς τοῦ βίου ἀεὶ γέμομεν ἐλπίδων;", "st": "39e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> παντάπασι μὲν οὖν.", "st": "39e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἄγε δή, πρὸς τοῖς νῦν εἰρημένοις καὶ τόδε ἀπόκριναι.", "st": "39e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ ποῖον;", "st": "39e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> δίκαιος ἀνὴρ καὶ εὐσεβὴς καὶ ἀγαθὸς πάντως ἆρ᾽ οὐ θεοφιλής ἐστιν;", "st": "39e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν;", "st": "39e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί δέ; ἄδικός τε καὶ παντάπασι κακὸς ἆρ᾽ οὐ", "st": "39e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τοὐναντίον ἐκείνῳ;", "st": "40a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς δ᾽ οὔ;", "st": "40a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πολλῶν μὴν ἐλπίδων, ὡς ἐλέγομεν ἄρτι, πᾶς ἄνθρωπος γέμει;", "st": "40a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί δ᾽ οὔ;", "st": "40a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> λόγοι μήν εἰσιν ἐν ἑκάστοις ἡμῶν, ἃς ἐλπίδας ὀνομάζομεν;", "st": "40a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ναί.", "st": "40a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ δὴ καὶ τὰ φαντάσματα ἐζωγραφημένα: καί τις ὁρᾷ πολλάκις ἑαυτῷ χρυσὸν γιγνόμενον ἄφθονον καὶ ἐπ᾽ αὐτῷ πολλὰς ἡδονάς: καὶ δὴ καὶ ἐνεζωγραφημένον αὐτὸν ἐφ᾽ αὑτῷ χαίροντα σφόδρα καθορᾷ.", "st": "40a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί δ᾽ οὔ;", "st": "40b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τούτων οὖν πότερα φῶμεν τοῖς μὲν ἀγαθοῖς ὡς τὸ πολὺ τὰ γεγραμμένα παρατίθεσθαι ἀληθῆ διὰ τὸ θεοφιλεῖς εἶναι, τοῖς δὲ κακοῖς ὡς αὖ ⟨τὸ⟩ πολὺ τοὐναντίον, ἢ μὴ φῶμεν;", "st": "40b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ μάλα φατέον.", "st": "40b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ τοῖς κακοῖς ἡδοναί γε οὐδὲν ἧττον πάρεισιν ἐζωγραφημέναι, ψευδεῖς δὲ αὗταί που.", "st": "40b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν;", "st": "40b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ψευδέσιν ἄρα ἡδοναῖς τὰ πολλὰ οἱ πονηροὶ χαίρουσιν, οἱ δ᾽ ἀγαθοὶ τῶν ἀνθρώπων ἀληθέσιν.", "st": "40c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀναγκαιότατα λέγεις.", "st": "40c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> εἰσὶν δὴ κατὰ τοὺς νῦν λόγους ψευδεῖς ἐν ταῖς τῶν ἀνθρώπων ψυχαῖς ἡδοναί, μεμιμημέναι μέντοι τὰς ἀληθεῖς ἐπὶ τὰ γελοιότερα, καὶ λῦπαι δὲ ὡσαύτως.", "st": "40c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> εἰσίν.", "st": "40c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἦν δοξάζειν μὲν ὄντως ἀεὶ τῷ τὸ παράπαν δοξάζοντι, μὴ ἐπ᾽ οὖσι δὲ μηδ᾽ ἐπὶ γεγονόσι μηδὲ ἐπ᾽ ἐσομένοις ἐνίοτε.", "st": "40c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ γε.", "st": "40c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ ταῦτά γε ἦν οἶμαι τὰ ἀπεργαζόμενα δόξαν ψευδῆ τότε καὶ τὸ ψευδῶς δοξάζειν. ἦ γάρ;", "st": "40d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ναί.", "st": "40d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί οὖν; οὐκ ἀνταποδοτέον ταῖς λύπαις τε καὶ ἡδοναῖς τὴν τούτων ἀντίστροφον ἕξιν ἐν ἐκείνοις;", "st": "40d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς;", "st": "40d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὡς ἦν μὲν χαίρειν ὄντως ἀεὶ τῷ τὸ παράπαν ὁπωσοῦν καὶ εἰκῇ χαίροντι, μὴ μέντοι ἐπὶ τοῖς οὖσι μηδ᾽ ἐπὶ τοῖς γεγονόσιν ἐνίοτε, πολλάκις δὲ καὶ ἴσως πλειστάκις ἐπὶ τοῖς μηδὲ μέλλουσί ποτε γενήσεσθαι.", "st": "40d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ ταῦθ᾽ οὕτως ἀναγκαῖον, ὦ Σώκρατες, ἔχειν.", "st": "40e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ὁ αὐτὸς λόγος ἂν εἴη περὶ φόβων τε καὶ θυμῶν καὶ πάντων τῶν τοιούτων, ὡς ἔστι καὶ ψευδῆ πάντα τὰ τοιαῦτα ἐνίοτε;", "st": "40e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν.", "st": "40e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί δέ; πονηρὰς δόξας καὶ χρηστὰς ἄλλως ἢ ψευδεῖς γιγνομένας ἔχομεν εἰπεῖν;", "st": "40e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὐκ ἄλλως.", "st": "40e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδ᾽ ἡδονάς γ᾽ οἶμαι κατανοοῦμεν ὡς ἄλλον τινὰ τρόπον εἰσὶν πονηραὶ πλὴν τῷ ψευδεῖς εἶναι.", "st": "40e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν τοὐναντίον, ὦ Σώκρατες, εἴρηκας. σχεδὸν γὰρ τῷ ψεύδει μὲν οὐ πάνυ πονηρὰς ἄν τις λύπας τε καὶ ἡδονὰς θείη, μεγάλῃ δὲ ἄλλῃ καὶ πολλῇ συμπιπτούσας πονηρίᾳ.", "st": "41a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὰς μὲν τοίνυν πονηρὰς ἡδονὰς καὶ διὰ πονηρίαν οὔσας τοιαύτας ὀλίγον ὕστερον ἐροῦμεν, ἂν ἔτι δοκῇ νῷν: τὰς δὲ ψευδεῖς κατ᾽ ἄλλον τρόπον ἐν ἡμῖν πολλὰς καὶ πολλάκις", "st": "41a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἐνούσας τε καὶ ἐγγιγνομένας λεκτέον. τούτῳ γὰρ ἴσως χρησόμεθα πρὸς τὰς κρίσεις.", "st": "41b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς γὰρ οὔκ; εἴπερ γε εἰσίν.", "st": "41b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ᾽, ὦ Πρώταρχε, εἰσὶν κατά γε τὴν ἐμήν. τοῦτο δὲ τὸ δόγμα ἕως ἂν κέηται παρ᾽ ἡμῖν, ἀδύνατον ἀνέλεγκτον δήπου γίγνεσθαι.", "st": "41b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καλῶς.", "st": "41b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> περιιστώμεθα δὴ καθάπερ ἀθληταὶ πρὸς τοῦτον αὖ τὸν λόγον.", "st": "41b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἴωμεν.", "st": "41b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ μὴν εἴπομεν, εἴπερ μεμνήμεθα, ὀλίγον ἐν", "st": "41b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τοῖς πρόσθεν, ὡς ὅταν αἱ λεγόμεναι ἐπιθυμίαι ἐν ἡμῖν ὦσι, δίχα ἄρα τότε τὸ σῶμα καὶ χωρὶς τῆς ψυχῆς τοῖς παθήμασι διείληπται.", "st": "41c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> μεμνήμεθα καὶ προερρήθη ταῦτα.", "st": "41c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τὸ μὲν ἐπιθυμοῦν ἦν ἡ ψυχὴ τῶν τοῦ σώματος ἐναντίων ἕξεων, τὸ δὲ τὴν ἀλγηδόνα ἤ τινα διὰ πάθος ἡδονὴν τὸ σῶμα ἦν τὸ παρεχόμενον;", "st": "41c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἦν γὰρ οὖν.", "st": "41c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> συλλογίζου δὴ τὸ γιγνόμενον ἐν τούτοις.", "st": "41c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγε.", "st": "41c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> γίγνεται τοίνυν, ὁπόταν ᾖ ταῦτα, ἅμα παρακεῖσθαι λύπας τε καὶ ἡδονάς, καὶ τούτων αἰσθήσεις ἅμα παρ᾽ ἀλλήλας ἐναντίων οὐσῶν γίγνεσθαι, ὃ καὶ νυνδὴ ἐφάνη.", "st": "41d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> φαίνεται γοῦν.", "st": "41d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ τόδε εἴρηται καὶ συνωμολογημένον ἡμῖν ἔμπροσθε κεῖται;", "st": "41d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ ποῖον;", "st": "41d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὡς τὸ μᾶλλόν τε καὶ ἧττον ἄμφω τούτω δέχεσθον, λύπη τε καὶ ἡδονή, καὶ ὅτι τῶν ἀπείρων εἴτην.", "st": "41d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> εἴρηται. τί μήν;", "st": "41d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τίς οὖν μηχανὴ ταῦτ᾽ ὀρθῶς κρίνεσθαι;", "st": "41d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῇ δὴ καὶ πῶς;", "st": "41e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> εἰ τὸ βούλημα ἡμῖν τῆς κρίσεως τούτων ἐν τοιούτοις τισὶ διαγνῶναι βούλεται ἑκάστοτε τίς τούτων πρὸς ἀλλήλας μείζων καὶ τίς ἐλάττων καὶ τίς μᾶλλον καὶ τίς σφοδροτέρα, λύπη τε πρὸς ἡδονὴν καὶ λύπη πρὸς λύπην καὶ ἡδονὴ πρὸς ἡδονήν.", "st": "41e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀλλ᾽ ἔστι ταῦτά τε τοιαῦτα καὶ ἡ βούλησις τῆς κρίσεως αὕτη.", "st": "41e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί οὖν; ἐν μὲν ὄψει τὸ πόρρωθεν καὶ ἐγγύθεν ὁρᾶν", "st": "41e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὰ μεγέθη τὴν ἀλήθειαν ἀφανίζει καὶ ψευδῆ ποιεῖ δοξάζειν, ἐν λύπαις δ᾽ ἄρα καὶ ἡδοναῖς οὐκ ἔστι ταὐτὸν τοῦτο γιγνόμενον;", "st": "42a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πολὺ μὲν οὖν μᾶλλον, ὦ Σώκρατες.", "st": "42a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἐναντίον δὴ τὸ νῦν τῷ σμικρὸν ἔμπροσθε γέγονεν.", "st": "42a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ ποῖον λέγεις;", "st": "42a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τότε μὲν αἱ δόξαι ψευδεῖς τε καὶ ἀληθεῖς αὗται γιγνόμεναι τὰς λύπας τε καὶ ἡδονὰς ἅμα τοῦ παρ᾽ αὑταῖς παθήματος ἀνεπίμπλασαν.", "st": "42a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀληθέστατα.", "st": "42b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> νῦν δέ γε αὐταὶ διὰ τὸ πόρρωθέν τε καὶ ἐγγύθεν ἑκάστοτε μεταβαλλόμεναι θεωρεῖσθαι, καὶ ἅμα τιθέμεναι παρ᾽ ἀλλήλας, αἱ μὲν ἡδοναὶ παρὰ τὸ λυπηρὸν μείζους φαίνονται καὶ σφοδρότεραι, λῦπαι δ᾽ αὖ διὰ τὸ παρ᾽ ἡδονὰς τοὐναντίον ἐκείναις.", "st": "42b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀνάγκη γίγνεσθαι τὰ τοιαῦτα διὰ ταῦτα.", "st": "42b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ὅσῳ μείζους τῶν οὐσῶν ἑκάτεραι καὶ ἐλάττους φαίνονται, τοῦτο ἀποτεμόμενος ἑκατέρων τὸ φαινόμενον", "st": "42b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ᾽ οὐκ ὄν, οὔτε αὐτὸ ὀρθῶς φαινόμενον ἐρεῖς, οὐδ᾽ αὖ ποτε τὸ ἐπὶ τούτῳ μέρος τῆς ἡδονῆς καὶ λύπης γιγνόμενον ὀρθόν τε καὶ ἀληθὲς τολμήσεις λέγειν.", "st": "42c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὐ γὰρ οὖν.", "st": "42c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τούτων τοίνυν ἑξῆς ὀψόμεθα ἐὰν τῇδε ἀπαντῶμεν ἡδονὰς καὶ λύπας ψευδεῖς ἔτι μᾶλλον ἢ ταύτας φαινομένας τε καὶ οὔσας ἐν τοῖς ζῴοις.", "st": "42c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ποίας δὴ καὶ πῶς λέγεις;", "st": "42c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> εἴρηταί που πολλάκις ὅτι τῆς φύσεως ἑκάστων διαφθειρομένης μὲν συγκρίσεσι καὶ διακρίσεσι καὶ πληρώσεσι", "st": "42c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ κενώσεσι καί τισιν αὔξαις καὶ φθίσεσι λῦπαί τε καὶ ἀλγηδόνες καὶ ὀδύναι καὶ πάνθ᾽ ὁπόσα τοιαῦτ᾽ ὀνόματα ἔχει συμβαίνει γιγνόμενα.", "st": "42d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ναί, ταῦτα εἴρηται πολλάκις.", "st": "42d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> εἰς δέ γε τὴν αὑτῶν φύσιν ὅταν καθιστῆται, ταύτην αὖ τὴν κατάστασιν ἡδονὴν ἀπεδεξάμεθα παρ᾽ ἡμῶν αὐτῶν.", "st": "42d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθῶς.", "st": "42d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί δ᾽ ὅταν περὶ τὸ σῶμα μηδὲν τούτων γιγνόμενον ἡμῶν ᾖ;", "st": "42d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πότε δὲ τοῦτ᾽ ἂν γένοιτο, ὦ Σώκρατες;", "st": "42d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδὲν πρὸς λόγον ἐστίν, ὦ Πρώταρχε, ὃ σὺ νῦν ἤρου τὸ ἐρώτημα.", "st": "42e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί δή;", "st": "42e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> διότι τὴν ἐμὴν ἐρώτησιν οὐ κωλύεις με διερέσθαι σε πάλιν.", "st": "42e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ποίαν;", "st": "42e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> εἰ δ᾽ οὖν μὴ γίγνοιτο, ὦ Πρώταρχε, φήσω, τὸ τοιοῦτον, τί ποτε ἀναγκαῖον ἐξ αὐτοῦ συμβαίνειν ἡμῖν;", "st": "42e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> μὴ κινουμένου τοῦ σώματος ἐφ᾽ ἑκάτερα φῄς;", "st": "42e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὕτως.", "st": "42e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> δῆλον δὴ τοῦτό γε, ὦ Σώκρατες, ὡς οὔτε ἡδονὴ γίγνοιτ᾽ ἂν ἐν τῷ τοιούτῳ ποτὲ οὔτ᾽ ἄν τις λύπη.", "st": "42e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> κάλλιστ᾽ εἶπες. ἀλλὰ γὰρ οἶμαι τόδε λέγεις, ὡς ἀεί τι τούτων ἀναγκαῖον ἡμῖν συμβαίνειν, ὡς οἱ σοφοί φασιν: ἀεὶ γὰρ ἅπαντα ἄνω τε καὶ κάτω ῥεῖ.", "st": "43a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγουσι γὰρ οὖν, καὶ δοκοῦσί γε οὐ φαύλως λέγειν.", "st": "43a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πῶς γὰρ ἄν, μὴ φαῦλοί γε ὄντες; ἀλλὰ γὰρ ὑπεκστῆναι τὸν λόγον ἐπιφερόμενον τοῦτον βούλομαι. τῇδ᾽ οὖν διανοοῦμαι φεύγειν, καὶ σύ μοι σύμφευγε.", "st": "43a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγε ὅπῃ.", "st": "43a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ταῦτα μὲν τοίνυν οὕτως ἔστω, φῶμεν πρὸς τούτους:", "st": "43a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> σὺ δ᾽ ἀπόκριναι πότερον ἀεὶ πάντα, ὁπόσα πάσχει τι τῶν ἐμψύχων, ταῦτ᾽ αἰσθάνεται τὸ πάσχον, καὶ οὔτ᾽ αὐξανόμενοι λανθάνομεν ἡμᾶς αὐτοὺς οὔτε τι τῶν τοιούτων οὐδὲν πάσχοντες, ἢ πᾶν τοὐναντίον.", "st": "43b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἅπαν δήπου τοὐναντίον: ὀλίγου γὰρ τά γε τοιαῦτα λέληθε πάνθ᾽ ἡμᾶς.", "st": "43b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐ τοίνυν καλῶς ἡμῖν εἴρηται τὸ νυνδὴ ῥηθέν, ὡς αἱ μεταβολαὶ κάτω τε καὶ ἄνω γιγνόμεναι λύπας τε καὶ ἡδονὰς ἀπεργάζονται.", "st": "43b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν;", "st": "43b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὧδ᾽ ἔσται κάλλιον καὶ ἀνεπιληπτότερον τὸ λεγόμενον.", "st": "43c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς;", "st": "43c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὡς αἱ μὲν μεγάλαι μεταβολαὶ λύπας τε καὶ ἡδονὰς ποιοῦσιν ἡμῖν, αἱ δ᾽ αὖ μέτριαί τε καὶ σμικραὶ τὸ παράπαν οὐδέτερα τούτων.", "st": "43c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθότερον οὕτως ἢ ‘κείνως, ὦ Σώκρατες.", "st": "43c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν εἰ ταῦτα οὕτω, πάλιν ὁ νυνδὴ ῥηθεὶς βίος ἂν ἥκοι.", "st": "43c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ποῖος;", "st": "43c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὃν ἄλυπόν τε καὶ ἄνευ χαρμονῶν ἔφαμεν εἶναι.", "st": "43c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀληθέστατα λέγεις.", "st": "43c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἐκ δὴ τούτων τιθῶμεν τριττοὺς ἡμῖν βίους, ἕνα", "st": "43c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μὲν ἡδύν, τὸν δ᾽ αὖ λυπηρόν, τὸν δ᾽ ἕνα μηδέτερα. ἢ πῶς ἂν φαίης σὺ περὶ τούτων;", "st": "43d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὐκ ἄλλως ἔγωγε ἢ ταύτῃ, τρεῖς εἶναι τοὺς βίους.", "st": "43d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν οὐκ ἂν εἴη τὸ μὴ λυπεῖσθαί ποτε ταὐτὸν τῷ χαίρειν;", "st": "43d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς γὰρ ἄν;", "st": "43d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὁπόταν οὖν ἀκούσῃς ὡς ἥδιστον πάντων ἐστὶν ἀλύπως διατελεῖν τὸν βίον ἅπαντα, τί τόθ᾽ ὑπολαμβάνεις λέγειν τὸν τοιοῦτον;", "st": "43d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἡδὺ λέγειν φαίνεται ἔμοιγε οὗτος τὸ μὴ λυπεῖσθαι.", "st": "43d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τριῶν ὄντων οὖν ἡμῖν, ὧντινων βούλει, τίθει, καλλίοσιν ἵνα ὀνόμασι χρώμεθα, τὸ μὲν χρυσόν, τὸ δ᾽ ἄργυρον, τρίτον δὲ τὸ μηδέτερα τούτων.", "st": "43e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> κεῖται.", "st": "43e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ δὴ μηδέτερα τούτων ἔσθ᾽ ἡμῖν ὅπως θάτερα γένοιτο ἄν, χρυσὸς ἢ ἄργυρος;", "st": "43e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ πῶς ἄν;", "st": "43e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδ᾽ ἄρα ὁ μέσος βίος ἡδὺς ἢ λυπηρὸς λεγόμενος ὀρθῶς ἄν ποτε οὔτ᾽ εἰ δοξάζοι τις, δοξάζοιτο, οὔτ᾽ εἰ λέγοι, λεχθείη, κατά γε τὸν ὀρθὸν λόγον.", "st": "43e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς γὰρ ἄν;", "st": "43e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ μήν, ὦ ἑταῖρε, λεγόντων γε ταῦτα καὶ δοξαζόντων αἰσθανόμεθα.", "st": "44a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ μάλα.", "st": "44a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πότερον οὖν καὶ χαίρειν οἴονται τότε ὅταν μὴ λυπῶνται;", "st": "44a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> φασὶ γοῦν.", "st": "44a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν οἴονται τότε χαίρειν: οὐ γὰρ ἂν ἔλεγόν που.", "st": "44a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> κινδυνεύει.", "st": "44a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ψευδῆ γε μὴν δοξάζουσι περὶ τοῦ χαίρειν, εἴπερ χωρὶς τοῦ μὴ λυπεῖσθαι καὶ τοῦ χαίρειν ἡ φύσις ἑκατέρου.", "st": "44a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ μὴν χωρίς γε ἦν.", "st": "44a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πότερον οὖν αἱρώμεθα παρ᾽ ἡμῖν ταῦτ᾽ εἶναι, καθάπερ", "st": "44a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἄρτι, τρία, ἢ δύο μόνα, λύπην μὲν κακὸν τοῖς ἀνθρώποις, τὴν δ᾽ ἀπαλλαγὴν τῶν λυπῶν, αὐτὸ τοῦτο ἀγαθὸν ὄν, ἡδὺ προσαγορεύεσθαι;", "st": "44b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς δὴ νῦν τοῦτο, ὦ Σώκρατες, ἐρωτώμεθα ὑφ᾽ ἡμῶν αὐτῶν; οὐ γὰρ μανθάνω.", "st": "44b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὄντως γὰρ τοὺς πολεμίους Φιλήβου τοῦδε, ὦ Πρώταρχε, οὐ μανθάνεις;", "st": "44b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγεις δὲ αὐτοὺς τίνας;", "st": "44b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μάλα δεινοὺς λεγομένους τὰ περὶ φύσιν, οἳ τὸ παράπαν ἡδονὰς οὔ φασιν εἶναι.", "st": "44b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν;", "st": "44b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> λυπῶν ταύτας εἶναι πάσας ἀποφυγάς, ἃς νῦν οἱ περὶ Φίληβον ἡδονὰς ἐπονομάζουσιν.", "st": "44c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τούτοις οὖν ἡμᾶς πότερα πείθεσθαι συμβουλεύεις, ἢ πῶς, ὦ Σώκρατες;", "st": "44c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὔκ, ἀλλ᾽ ὥσπερ μάντεσι προσχρῆσθαί τισι, μαντευομένοις οὐ τέχνῃ ἀλλά τινι δυσχερείᾳ φύσεως οὐκ ἀγεννοῦς λίαν μεμισηκότων τὴν τῆς ἡδονῆς δύναμιν καὶ νενομικότων οὐδὲν ὑγιές, ὥστε καὶ αὐτὸ τοῦτο αὐτῆς τὸ ἐπαγωγὸν γοήτευμα,", "st": "44c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐχ ἡδονήν, εἶναι. τούτοις μὲν οὖν ταῦτα ἂν προσχρήσαιο, σκεψάμενος ἔτι καὶ τὰ ἄλλα αὐτῶν δυσχεράσματα: μετὰ δὲ ταῦτα αἵ γέ μοι δοκοῦσιν ἡδοναὶ ἀληθεῖς εἶναι πεύσῃ, ἵνα ἐξ ἀμφοῖν τοῖν λόγοιν σκεψάμενοι τὴν δύναμιν αὐτῆς παραθώμεθα πρὸς τὴν κρίσιν.", "st": "44d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθῶς λέγεις.", "st": "44d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μεταδιώκωμεν δὴ τούτους, ὥσπερ συμμάχους, κατὰ τὸ τῆς δυσχερείας αὐτῶν ἴχνος. οἶμαι γὰρ τοιόνδε τι λέγειν αὐτούς, ἀρχομένους ποθὲν ἄνωθεν, ὡς εἰ βουληθεῖμεν ὁτουοῦν", "st": "44d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> εἴδους τὴν φύσιν ἰδεῖν, οἷον τὴν τοῦ σκληροῦ, πότερον εἰς τὰ σκληρότατα ἀποβλέποντες οὕτως ἂν μᾶλλον συννοήσαιμεν ἢ πρὸς τὰ πολλοστὰ σκληρότητι; δεῖ δή σε, ὦ Πρώταρχε, καθάπερ ἐμοί, καὶ τούτοις τοῖς δυσχερέσιν ἀποκρίνεσθαι.", "st": "44e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν, καὶ λέγω γε αὐτοῖς ὅτι πρὸς τὰ πρῶτα μεγέθει.", "st": "44e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν εἰ καὶ τὸ τῆς ἡδονῆς γένος ἰδεῖν ἥντινά ποτ᾽ ἔχει φύσιν βουληθεῖμεν, οὐκ εἰς τὰς πολλοστὰς ἡδονὰς", "st": "44e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀποβλεπτέον, ἀλλ᾽ εἰς τὰς ἀκροτάτας καὶ σφοδροτάτας λεγομένας.", "st": "45a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πᾶς ἄν σοι ταύτῃ συγχωροίη τὰ νῦν.", "st": "45a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ οὖν, αἱ πρόχειροί γε αἵπερ καὶ μέγισται τῶν ἡδονῶν, ὃ λέγομεν πολλάκις, αἱ περὶ τὸ σῶμά εἰσιν αὗται;", "st": "45a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς γὰρ οὔ;", "st": "45a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πότερον οὖν καὶ μείζους εἰσὶ καὶ γίγνονται περὶ τοὺς κάμνοντας ἐν ταῖς νόσοις ἢ περὶ ὑγιαίνοντας; εὐλαβηθῶμεν δὲ μὴ προπετῶς ἀποκρινόμενοι πταίσωμέν πῃ. τάχα γὰρ", "st": "45a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἴσως φαῖμεν ἂν περὶ ὑγιαίνοντας.", "st": "45b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> εἰκός γε.", "st": "45b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί δ᾽; οὐχ αὗται τῶν ἡδονῶν ὑπερβάλλουσιν, ὧν ἂν καὶ ἐπιθυμίαι μέγισται προγίγνωνται;", "st": "45b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τοῦτο μὲν ἀληθές.", "st": "45b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ᾽ οὐχ οἱ πυρέττοντες καὶ ἐν τοιούτοις νοσήμασιν ἐχόμενοι μᾶλλον διψῶσι καὶ ῥιγοῦσι καὶ πάντα ὁπόσα διὰ τοῦ σώματος εἰώθασι πάσχειν, μᾶλλόν τ᾽ ἐνδείᾳ συγγίγνονται καὶ ἀποπληρουμένων μείζους ἡδονὰς ἴσχουσιν; ἢ τοῦτο οὐ φήσομεν ἀληθὲς εἶναι;", "st": "45b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν νῦν ῥηθὲν φαίνεται.", "st": "45b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί οὖν; ὀρθῶς ἂν φαινοίμεθα λέγοντες ὡς εἴ τις τὰς μεγίστας ἡδονὰς ἰδεῖν βούλοιτο, οὐκ εἰς ὑγίειαν ἀλλ᾽ εἰς νόσον ἰόντας δεῖ σκοπεῖν; ὅρα δὲ μή με ἡγῇ διανοούμενον ἐρωτᾶν σε εἰ πλείω χαίρουσιν οἱ σφόδρα νοσοῦντες τῶν ὑγιαινόντων, ἀλλ᾽ οἴου μέγεθός με ζητεῖν ἡδονῆς, καὶ τὸ σφόδρα περὶ τοῦ τοιούτου ποῦ ποτε γίγνεται ἑκάστοτε. νοῆσαι γὰρ δεῖ φαμεν ἥντινα φύσιν ἔχει καὶ τίνα λέγουσιν οἱ φάσκοντες μηδ᾽ εἶναι τὸ παράπαν αὐτήν.", "st": "45c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀλλὰ σχεδὸν ἕπομαι τῷ λόγῳ σου.", "st": "45d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τάχα, ὦ Πρώταρχε, οὐχ ἧττον δείξεις. ἀπόκριναι γάρ: ἐν ὕβρει μείζους ἡδονάς — οὐ πλείους λέγω, τῷ σφόδρα δὲ καὶ τῷ μᾶλλον ὑπερεχούσας — ὁρᾷς ἢ ἐν τῷ σώφρονι βίῳ; λέγε δὲ προσέχων τὸν νοῦν.", "st": "45d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀλλ᾽ ἔμαθον ὃ λέγεις, καὶ πολὺ τὸ διαφέρον ὁρῶ. τοὺς μὲν γὰρ σώφρονάς που καὶ ὁ παροιμιαζόμενος", "st": "45d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἐπίσχει λόγος ἑκάστοτε, ὁ τὸ μηδὲν ἄγαν παρακελευόμενος, ᾧ πείθονται: τὸ δὲ τῶν ἀφρόνων τε καὶ ὑβριστῶν μέχρι μανίας ἡ σφοδρὰ ἡδονὴ κατέχουσα περιβοήτους ἀπεργάζεται.", "st": "45e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καλῶς: καὶ εἴ γε τοῦθ᾽ οὕτως ἔχει, δῆλον ὡς ἔν τινι πονηρίᾳ ψυχῆς καὶ τοῦ σώματος, ἀλλ᾽ οὐκ ἐν ἀρετῇ μέγισται μὲν ἡδοναί, μέγισται δὲ καὶ λῦπαι γίγνονται.", "st": "45e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν.", "st": "45e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τούτων τινὰς προελόμενον δεῖ σκοπεῖσθαι τίνα ποτὲ τρόπον ἐχούσας ἐλέγομεν αὐτὰς εἶναι μεγίστας.", "st": "45e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀνάγκη.", "st": "46a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> σκόπει δὴ τὰς τῶν τοιῶνδε νοσημάτων ἡδονάς, τίνα ποτὲ ἔχουσι τρόπον.", "st": "46a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ποίων;", "st": "46a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὰς τῶν ἀσχημόνων, ἃς οὓς εἴπομεν δυσχερεῖς μισοῦσι παντελῶς.", "st": "46a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ποίας;", "st": "46a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οἷον τὰς τῆς ψώρας ἰάσεις τῷ τρίβειν καὶ ὅσα τοιαῦτα, οὐκ ἄλλης δεόμενα φαρμάξεως: τοῦτο γὰρ δὴ τὸ πάθος ἡμῖν, ὦ πρὸς θεῶν, τί ποτε φῶμεν ἐγγίγνεσθαι; πότερον ἡδονὴν ἢ λύπην;", "st": "46a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> σύμμεικτον τοῦτό γ᾽ ἄρ᾽, ὦ Σώκρατες, ἔοικε γίγνεσθαί τι κακόν.", "st": "46a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐ μὲν δὴ Φιλήβου γε ἕνεκα παρεθέμην τὸν λόγον: ἀλλ᾽ ἄνευ τούτων, ὦ Πρώταρχε, τῶν ἡδονῶν καὶ τῶν ταύταις ἑπομένων, ἂν μὴ κατοφθῶσι, σχεδὸν οὐκ ἄν ποτε δυναίμεθα διακρίνασθαι τὸ νῦν ζητούμενον.", "st": "46b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὐκοῦν ἰτέον ἐπὶ τὰς τούτων συγγενεῖς.", "st": "46b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὰς ἐν τῇ μείξει κοινωνούσας λέγεις;", "st": "46b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν.", "st": "46b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> εἰσὶ τοίνυν μείξεις αἱ μὲν κατὰ τὸ σῶμα ἐν αὐτοῖς", "st": "46b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τοῖς σώμασιν, αἱ δ᾽ αὐτῆς τῆς ψυχῆς ἐν τῇ ψυχῇ: τὰς δ᾽ αὖ τῆς ψυχῆς καὶ τοῦ σώματος ἀνευρήσομεν λύπας ἡδοναῖς μειχθείσας τοτὲ μὲν ἡδονὰς τὰ συναμφότερα, τοτὲ δὲ λύπας ἐπικαλουμένας.", "st": "46c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς;", "st": "46c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὁπόταν ἐν τῇ καταστάσει τις ἢ τῇ διαφθορᾷ τἀναντία ἅμα πάθη πάσχῃ, ποτὲ ῥιγῶν θέρηται καὶ θερμαινόμενος ἐνίοτε ψύχηται, ζητῶν οἶμαι τὸ μὲν ἔχειν, τοῦ δὲ ἀπαλλάττεσθαι, τὸ δὴ λεγόμενον πικρῷ γλυκὺ μεμειγμένον, μετὰ", "st": "46c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> δυσαπαλλακτίας παρόν, ἀγανάκτησιν καὶ ὕστερον σύντασιν ἀγρίαν ποιεῖ.", "st": "46d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ μάλα ἀληθὲς τὸ νῦν λεγόμενον.", "st": "46d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν αἱ τοιαῦται μείξεις αἱ μὲν ἐξ ἴσων εἰσὶ λυπῶν τε καὶ ἡδονῶν, αἱ δ᾽ ἐκ τῶν ἑτέρων πλειόνων;", "st": "46d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς γὰρ οὔ;", "st": "46d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> λέγε δὴ τὰς μέν, ὅταν πλείους λῦπαι τῶν ἡδονῶν γίγνωνται — τὰς τῆς ψώρας λεγομένας νυνδὴ ταύτας εἶναι καὶ τὰς τῶν γαργαλισμῶν — ὁπόταν ⟨ἐν τοῖς⟩ ἐντὸς τὸ ζέον ᾖ καὶ τὸ φλεγμαῖνον, τῇ τρίψει δὲ καὶ τῇ κνήσει μὴ ἐφικνῆταί", "st": "46d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τις, τὸ δ᾽ ἐπιπολῆς μόνον διαχέῃ, τοτὲ φέροντες εἰς πῦρ αὐτὰ καὶ εἰς τοὐναντίον πυρίαις μεταβάλλοντες ἐνίοτε ἀμηχάνους ἡδονάς, τοτὲ δὲ τοὐναντίον τοῖς ἐντὸς πρὸς τὰ τῶν ἔξω, λύπας ἡδοναῖς συγκερασθείσας, εἰς ὁπότερ᾽ ἂν ῥέψῃ, παρέσχοντο τῷ τὰ συγκεκριμένα βίᾳ διαχεῖν ἢ τὰ διακεκριμένα συγχεῖν", "st": "46e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> [καὶ] ὁμοῦ λύπας ἡδοναῖς παρατιθέναι.", "st": "47a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀληθέστατα.", "st": "47a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ὁπόταν αὖ πλείων ἡδονὴ κατὰ ⟨τὰ⟩ τοιαῦτα πάντα συμμειχθῇ, τὸ μὲν ὑπομεμειγμένον τῆς λύπης γαργαλίζει τε καὶ ἠρέμα ἀγανακτεῖν ποιεῖ, τὸ δ᾽ αὖ τῆς ἡδονῆς πολὺ πλέον ἐγκεχυμένον συντείνει τε καὶ ἐνίοτε πηδᾶν ποιεῖ, καὶ παντοῖα μὲν χρώματα, παντοῖα δὲ σχήματα, παντοῖα δὲ πνεύματα ἀπεργαζόμενον πᾶσαν ἔκπληξιν καὶ βοὰς μετὰ ἀφροσύνης ἐνεργάζεται;", "st": "47a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> μάλα γε.", "st": "47b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ λέγειν τε, ὦ ἑταῖρε, αὐτόν τε περὶ ἑαυτοῦ ποιεῖ καὶ ἄλλον ὡς ταύταις ταῖς ἡδοναῖς τερπόμενος οἷον ἀποθνῄσκει: καὶ ταύτας γε δὴ παντάπασιν ἀεὶ μεταδιώκει τοσούτῳ μᾶλλον ὅσῳ ἂν ἀκολαστότερός τε καὶ ἀφρονέστερος ὢν τυγχάνῃ, καὶ καλεῖ δὴ μεγίστας ταύτας, καὶ τὸν ἐν αὐταῖς ὅτι μάλιστ᾽ ἀεὶ ζῶντα εὐδαιμονέστατον καταριθμεῖται.", "st": "47b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάντα, ὦ Σώκρατες, τὰ συμβαίνοντα πρὸς τῶν πολλῶν ἀνθρώπων εἰς δόξαν διεπέρανας.", "st": "47b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> περί γε τῶν ἡδονῶν, ὦ Πρώταρχε, τῶν ἐν τοῖς κοινοῖς παθήμασιν αὐτοῦ τοῦ σώματος τῶν ἐπιπολῆς τε καὶ ἐντὸς κερασθέντων: περὶ δέ γ᾽ ὧν ψυχὴ σώματι τἀναντία συμβάλλεται, λύπην τε ἅμα πρὸς ἡδονὴν καὶ ἡδονὴν πρὸς λύπην, ὥστ᾽ εἰς μίαν ἀμφότερα κρᾶσιν ἰέναι, ταῦτα ἔμπροσθε μὲν διήλθομεν, ὡς, ὁπόταν [αὖ] κενῶται, πληρώσεως ἐπιθυμεῖ, καὶ ἐλπίζων μὲν χαίρει, κενούμενος δὲ ἀλγεῖ, ταῦτα δὲ τότε", "st": "47c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μὲν οὐκ ἐμαρτυράμεθα, νῦν δὲ λέγομεν ὡς ψυχῆς πρὸς σῶμα διαφερομένης ἐν πᾶσι τούτοις πλήθει ἀμηχάνοις οὖσι μεῖξις μία λύπης τε καὶ ἡδονῆς συμπίπτει γενομένη.", "st": "47d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> κινδυνεύεις ὀρθότατα λέγειν.", "st": "47d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἔτι τοίνυν ἡμῖν τῶν μείξεων λύπης τε καὶ ἡδονῆς λοιπὴ μία.", "st": "47d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ποία, φῄς;", "st": "47d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἣν αὐτὴν τὴν ψυχὴν αὑτῇ πολλάκις λαμβάνειν σύγκρασιν ἔφαμεν.", "st": "47d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς οὖν δὴ τοῦτ᾽ αὐτὸ λέγομεν;", "st": "47d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὀργὴν καὶ φόβον καὶ πόθον καὶ θρῆνον καὶ ἔρωτα καὶ ζῆλον καὶ φθόνον καὶ ὅσα τοιαῦτα, ἆρ᾽ οὐκ αὐτῆς τῆς ψυχῆς τίθεσαι ταύτας λύπας τινάς;", "st": "47e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἔγωγε.", "st": "47e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν αὐτὰς ἡδονῶν μεστὰς εὑρήσομεν ἀμηχάνων; ἢ δεόμεθα ὑπομιμνῄσκεσθαι [τὸ ⟨ἐν⟩ τοῖς θυμοῖς καὶ ταῖς ὀργαῖς,] τὸ", "st": "47e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὅς τ᾽ ἐφέηκε πολύφρονά περ χαλεπῆναι", "st": "47e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὅς τε πολὺ γλυκίων μέλιτος καταλειβομένοιο,", "st": "47e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ τὰς ἐν τοῖς θρήνοις καὶ πόθοις ἡδονὰς ἐν λύπαις οὔσας ἀναμεμειγμένας;", "st": "48a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὔκ, ἀλλ᾽ οὕτω ταῦτά γε καὶ οὐκ ἄλλως ἂν συμβαίνοι γιγνόμενα.", "st": "48a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν καὶ τάς γε τραγικὰς θεωρήσεις, ὅταν ἅμα χαίροντες κλάωσι, μέμνησαι;", "st": "48a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί δ᾽ οὔ;", "st": "48a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὴν δ᾽ ἐν ταῖς κωμῳδίαις διάθεσιν ἡμῶν τῆς ψυχῆς, ἆρ᾽ οἶσθ᾽ ὡς ἔστι κἀν τούτοις μεῖξις λύπης τε καὶ ἡδονῆς;", "st": "48a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὐ πάνυ κατανοῶ.", "st": "48a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> παντάπασι γὰρ οὐ ῥᾴδιον, ὦ Πρώταρχε, ἐν τούτῳ συννοεῖν τὸ τοιοῦτον ἑκάστοτε πάθος.", "st": "48b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὔκουν ὥς γ᾽ ἔοικεν ἐμοί.", "st": "48b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> λάβωμέν γε μὴν αὐτὸ τοσούτῳ μᾶλλον ὅσῳ σκοτεινότερόν ἐστιν, ἵνα καὶ ἐν ἄλλοις ῥᾷον καταμαθεῖν τις οἷός τ᾽ ᾖ μεῖξιν λύπης τε καὶ ἡδονῆς.", "st": "48b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγοις ἄν.", "st": "48b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τό τοι νυνδὴ ῥηθὲν ὄνομα φθόνου πότερα λύπην τινὰ ψυχῆς θήσεις, ἢ πῶς;", "st": "48b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὕτως.", "st": "48b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ μὴν ὁ φθονῶν γε ἐπὶ κακοῖς τοῖς τῶν πέλας ἡδόμενος ἀναφανήσεται.", "st": "48b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> σφόδρα γε.", "st": "48c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> κακὸν μὴν ἄγνοια καὶ ἣν δὴ λέγομεν ἀβελτέραν ἕξιν.", "st": "48c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν;", "st": "48c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἐκ δὴ τούτων ἰδὲ τὸ γελοῖον ἥντινα φύσιν ἔχει.", "st": "48c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγε μόνον.", "st": "48c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἔστιν δὴ πονηρία μέν τις τὸ κεφάλαιον, ἕξεώς τινος ἐπίκλην λεγομένη: τῆς δ᾽ αὖ πάσης πονηρίας ἐστὶ τοὐναντίον πάθος ἔχον ἢ τὸ λεγόμενον ὑπὸ τῶν ἐν Δελφοῖς γραμμάτων.", "st": "48c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ γνῶθι σαυτὸν λέγεις, ὦ Σώκρατες;", "st": "48c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἔγωγε. τοὐναντίον μὴν ἐκείνῳ δῆλον ὅτι τὸ μηδαμῇ γιγνώσκειν αὑτὸν λεγόμενον ὑπὸ τοῦ γράμματος ἂν εἴη.", "st": "48d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν;", "st": "48d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὦ Πρώταρχε, πειρῶ δὲ αὐτὸ τοῦτο τριχῇ τέμνειν.", "st": "48d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῇ φῄς; οὐ γὰρ μὴ δυνατὸς ὦ.", "st": "48d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> λέγεις δὴ δεῖν ἐμὲ τοῦτο διελέσθαι τὰ νῦν;", "st": "48d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγω, καὶ δέομαί γε πρὸς τῷ λέγειν.", "st": "48d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ οὖν οὐ τῶν ἀγνοούντων αὑτοὺς κατὰ τρία ἀνάγκη τοῦτο τὸ πάθος πάσχειν ἕκαστον;", "st": "48d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς;", "st": "48d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πρῶτον μὲν κατὰ χρήματα, δοξάζειν εἶναι πλουσιώτερον ἢ κατὰ τὴν αὑτῶν οὐσίαν.", "st": "48e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πολλοὶ γοῦν εἰσὶν τὸ τοιοῦτον πάθος ἔχοντες.", "st": "48e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πλείους δέ γε οἳ μείζους καὶ καλλίους αὑτοὺς δοξάζουσι, καὶ πάντα ὅσα κατὰ τὸ σῶμα εἶναι διαφερόντως τῆς οὔσης αὐτοῖς ἀληθείας.", "st": "48e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ γε.", "st": "48e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πολὺ δὲ πλεῖστοί γε οἶμαι περὶ τὸ τρίτον εἶδος τὸ τῶν ἐν ταῖς ψυχαῖς διημαρτήκασιν, ἀρετῇ δοξάζοντες βελτίους ἑαυτούς, οὐκ ὄντες.", "st": "48e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> σφόδρα μὲν οὖν.", "st": "48e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τῶν ἀρετῶν δ᾽ ἆρ᾽ οὐ σοφίας πέρι τὸ πλῆθος πάντως ἀντεχόμενον μεστὸν ἐρίδων καὶ δοξοσοφίας ἐστὶ ψευδοῦς;", "st": "49a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς δ᾽ οὔ;", "st": "49a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> κακὸν μὲν δὴ πᾶν ἄν τις τὸ τοιοῦτον εἰπὼν ὀρθῶς ἂν εἴποι πάθος.", "st": "49a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> σφόδρα γε.", "st": "49a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τοῦτο τοίνυν ἔτι διαιρετέον, ὦ Πρώταρχε, δίχα, εἰ μέλλομεν τὸν παιδικὸν ἰδόντες φθόνον ἄτοπον ἡδονῆς καὶ λύπης ὄψεσθαι μεῖξιν. πῶς οὖν τέμνομεν δίχα, λέγεις;", "st": "49a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πάντες ὁπόσοι ταύτην τὴν ψευδῆ δόξαν περὶ ἑαυτῶν ἀνοήτως δοξάζουσι, καθάπερ ἁπάντων ἀνθρώπων, καὶ τούτων ἀναγκαιότατον ἕπεσθαι τοῖς μὲν ῥώμην αὐτῶν καὶ δύναμιν, τοῖς δὲ οἶμαι τοὐναντίον.", "st": "49b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀνάγκη.", "st": "49b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ταύτῃ τοίνυν δίελε, καὶ ὅσοι μὲν αὐτῶν εἰσι μετ᾽ ἀσθενείας τοιοῦτοι καὶ ἀδύνατοι καταγελώμενοι τιμωρεῖσθαι, γελοίους τούτους φάσκων εἶναι τἀληθῆ φθέγξῃ: τοὺς δὲ δυνατοὺς τιμωρεῖσθαι καὶ ἰσχυροὺς φοβεροὺς καὶ ἐχθροὺς", "st": "49b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> προσαγορεύων ὀρθότατον τούτων σαυτῷ λόγον ἀποδώσεις. ἄγνοια γὰρ ἡ μὲν τῶν ἰσχυρῶν ἐχθρά τε καὶ αἰσχρά βλαβερὰ γὰρ καὶ τοῖς πέλας αὐτή τε καὶ ὅσαι εἰκόνες αὐτῆς εἰσιν — ἡ δ᾽ ἀσθενὴς ἡμῖν τὴν τῶν γελοίων εἴληχε τάξιν τε καὶ φύσιν.", "st": "49c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθότατα λέγεις. ἀλλὰ γὰρ ἡ τῶν ἡδονῶν καὶ λυπῶν μεῖξις ἐν τούτοις οὔπω μοι καταφανής.", "st": "49c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὴν τοίνυν τοῦ φθόνου λαβὲ δύναμιν πρῶτον.", "st": "49c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγε μόνον.", "st": "49c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> λύπη τις ἄδικός ἐστί που καὶ ἡδονή;", "st": "49d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τοῦτο μὲν ἀνάγκη.", "st": "49d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἐπὶ μὲν τοῖς τῶν ἐχθρῶν κακοῖς οὔτ᾽ ἄδικον οὔτε φθονερόν ἐστι τὸ χαίρειν;", "st": "49d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν;", "st": "49d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὰ δέ γε τῶν φίλων ὁρῶντας ἔστιν ὅτε κακὰ μὴ λυπεῖσθαι, χαίρειν δέ, ἆρα οὐκ ἄδικόν ἐστιν;", "st": "49d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς δ᾽ οὔ;", "st": "49d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τὴν ἄγνοιαν εἴπομεν ὅτι κακὸν πᾶσιν;", "st": "49d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθῶς.", "st": "49d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὴν οὖν τῶν φίλων δοξοσοφίαν καὶ δοξοκαλίαν καὶ", "st": "49d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὅσα νυνδὴ διήλθομεν, ἐν τρισὶν λέγοντες εἴδεσιν γίγνεσθαι, γελοῖα μὲν ὁπόσα ἀσθενῆ, μισητὰ δ᾽ ὁπόσα ἐρρωμένα, ⟨φῶμεν⟩ ἢ μὴ φῶμεν ὅπερ εἶπον ἄρτι, τὴν τῶν φίλων ἕξιν ταύτην ὅταν ἔχῃ τις τὴν ἀβλαβῆ τοῖς ἄλλοις, γελοίαν εἶναι;", "st": "49e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ γε.", "st": "49e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> κακὸν δ᾽ οὐχ ὁμολογοῦμεν αὐτὴν ἄγνοιάν γε οὖσαν εἶναι;", "st": "49e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> σφόδρα γε.", "st": "49e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> χαίρομεν δὲ ἢ λυπούμεθα, ὅταν ἐπ᾽ αὐτῇ γελῶμεν;", "st": "49e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> δῆλον ὅτι χαίρομεν.", "st": "50a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἡδονὴν δὲ ἐπὶ τοῖς τῶν φίλων κακοῖς, οὐ φθόνον ἔφαμεν εἶναι τὸν τοῦτ᾽ ἀπεργαζόμενον;", "st": "50a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀνάγκη.", "st": "50a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> γελῶντας ἄρα ἡμᾶς ἐπὶ τοῖς τῶν φίλων γελοίοις φησὶν ὁ λόγος, κεραννύντας ἡδονὴν αὖ φθόνῳ, λύπῃ τὴν ἡδονὴν συγκεραννύναι: τὸν γὰρ φθόνον ὡμολογῆσθαι λύπην ψυχῆς ἡμῖν πάλαι, τὸ δὲ γελᾶν ἡδονήν, ἅμα γίγνεσθαι δὲ τούτω ἐν τούτοις τοῖς χρόνοις.", "st": "50a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀληθῆ.", "st": "50a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μηνύει δὴ νῦν ὁ λόγος ἡμῖν ἐν θρήνοις τε καὶ ἐν τραγῳδίαις ⟨καὶ κωμῳδίαις⟩, μὴ τοῖς δράμασι μόνον ἀλλὰ καὶ τῇ τοῦ βίου συμπάσῃ τραγῳδίᾳ καὶ κωμῳδίᾳ, λύπας ἡδοναῖς ἅμα κεράννυσθαι, καὶ ἐν ἄλλοις δὴ μυρίοις.", "st": "50b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀδύνατον μὴ ὁμολογεῖν ταῦτα, ὦ Σώκρατες, εἰ καί τις φιλονικοῖ πάνυ πρὸς τἀναντία.", "st": "50b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὀργὴν μὴν καὶ πόθον καὶ θρῆνον καὶ φόβον καὶ", "st": "50b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἔρωτα καὶ ζῆλον καὶ φθόνον προυθέμεθα καὶ ὁπόσα τοιαῦτα, ἐν οἷς ἔφαμεν εὑρήσειν μειγνύμενα τὰ νῦν πολλάκις λεγόμενα. ἦ γάρ;", "st": "50c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ναί.", "st": "50c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μανθάνομεν οὖν ὅτι θρήνου πέρι καὶ φθόνου καὶ ὀργῆς πάντα ἐστὶ τὰ νυνδὴ διαπερανθέντα;", "st": "50c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς γὰρ οὐ μανθάνομεν;", "st": "50c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν πολλὰ ἔτι τὰ λοιπά;", "st": "50c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ πάνυ γε.", "st": "50c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> διὰ δὴ τί μάλισθ᾽ ὑπολαμβάνεις με δεῖξαί σοι τὴν ἐν τῇ κωμῳδίᾳ μεῖξιν; ἆρ᾽ οὐ πίστεως χάριν, ὅτι τήν γε ἐν", "st": "50c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τοῖς φόβοις καὶ ἔρωσι καὶ τοῖς ἄλλοις ῥᾴδιον κρᾶσιν ἐπιδεῖξαι: λαβόντα δὲ τοῦτο παρὰ σαυτῷ ἀφεῖναί με μηκέτι ἐπ᾽ ἐκεῖνα ἰόντα δεῖν μηκύνειν τοὺς λόγους, ἀλλ᾽ ἁπλῶς λαβεῖν τοῦτο, ὅτι καὶ σῶμα ἄνευ ψυχῆς καὶ ψυχὴ ἄνευ σώματος καὶ κοινῇ μετ᾽ ἀλλήλων ἐν τοῖς παθήμασι μεστά ἐστι συγκεκραμένης ἡδονῆς λύπαις; νῦν οὖν λέγε πότερα ἀφίης με ἢ μέσας ποιήσεις νύκτας; εἰπὼν δὲ σμικρὰ οἶμαί σου τεύξεσθαι μεθεῖναί με: τούτων γὰρ ἁπάντων αὔριον", "st": "50d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἐθελήσω σοι λόγον δοῦναι, τὰ νῦν δὲ ἐπὶ τὰ λοιπὰ βούλομαι στέλλεσθαι πρὸς τὴν κρίσιν ἣν Φίληβος ἐπιτάττει.", "st": "50e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καλῶς εἶπες, ὦ Σώκρατες: ἀλλ᾽ ὅσα λοιπὰ ἡμῖν διέξελθε ὅπῃ σοι φίλον.", "st": "50e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> κατὰ φύσιν τοίνυν μετὰ τὰς μειχθείσας ἡδονὰς ὑπὸ δή τινος ἀνάγκης ἐπὶ τὰς ἀμείκτους πορευοίμεθ᾽ ἂν ἐν τῷ μέρει.", "st": "50e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> κάλλιστ᾽ εἶπες.", "st": "51a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἐγὼ δὴ πειράσομαι μεταβαλὼν σημαίνειν ἡμῖν αὐτάς. τοῖς γὰρ φάσκουσι λυπῶν εἶναι παῦλαν πάσας τὰς ἡδονὰς οὐ πάνυ πως πείθομαι, ἀλλ᾽ ὅπερ εἶπον, μάρτυσι καταχρῶμαι πρὸς τὸ τινὰς ἡδονὰς εἶναι δοκούσας, οὔσας δ᾽ οὐδαμῶς, καὶ μεγάλας ἑτέρας τινὰς ἅμα καὶ πολλὰς φαντασθείσας, εἶναι δ᾽ αὐτὰς συμπεφυρμένας ὁμοῦ λύπαις τε καὶ ἀναπαύσεσιν ὀδυνῶν τῶν μεγίστων περί τε σώματος καὶ ψυχῆς ἀπορίας.", "st": "51a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀληθεῖς δ᾽ αὖ τίνας, ὦ Σώκρατες, ὑπολαμβάνων ὀρθῶς τις διανοοῖτ᾽ ἄν;", "st": "51b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὰς περί τε τὰ καλὰ λεγόμενα χρώματα καὶ περὶ τὰ σχήματα καὶ τῶν ὀσμῶν τὰς πλείστας καὶ τὰς τῶν φθόγγων καὶ ὅσα τὰς ἐνδείας ἀναισθήτους ἔχοντα καὶ ἀλύπους τὰς πληρώσεις αἰσθητὰς καὶ ἡδείας [καθαρὰς λυπῶν] παραδίδωσιν.", "st": "51b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς δὴ ταῦτα, ὦ Σώκρατες, αὖ λέγομεν οὕτω;", "st": "51b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πάνυ μὲν οὖν οὐκ εὐθὺς δῆλά ἐστιν ἃ λέγω, πειρατέον", "st": "51b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μὴν δηλοῦν. σχημάτων τε γὰρ κάλλος οὐχ ὅπερ ἂν ὑπολάβοιεν οἱ πολλοὶ πειρῶμαι νῦν λέγειν, ἢ ζῴων ἤ τινων ζωγραφημάτων, ἀλλ᾽ εὐθύ τι λέγω, φησὶν ὁ λόγος, καὶ περιφερὲς καὶ ἀπὸ τούτων δὴ τά τε τοῖς τόρνοις γιγνόμενα ἐπίπεδά τε καὶ στερεὰ καὶ τὰ τοῖς κανόσι καὶ γωνίαις, εἴ μου μανθάνεις. ταῦτα γὰρ οὐκ εἶναι πρός τι καλὰ λέγω, καθάπερ ἄλλα, ἀλλ᾽ ἀεὶ καλὰ καθ᾽ αὑτὰ πεφυκέναι καί τινας", "st": "51c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἡδονὰς οἰκείας ἔχειν, οὐδὲν ταῖς τῶν κνήσεων προσφερεῖς: καὶ χρώματα δὴ τοῦτον τὸν τύπον ἔχοντα [καλὰ καὶ ἡδονάς] ἀλλ᾽ ἆρα μανθάνομεν, ἢ πῶς;", "st": "51d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πειρῶμαι μέν, ὦ Σώκρατες: πειράθητι δὲ καὶ σὺ σαφέστερον ἔτι λέγειν.", "st": "51d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> λέγω δὴ ἠχὰς τῶν φθόγγων τὰς λείας καὶ λαμπράς, τὰς ἕν τι καθαρὸν ἱείσας μέλος, οὐ πρὸς ἕτερον καλὰς ἀλλ᾽ αὐτὰς καθ᾽ αὑτὰς εἶναι, καὶ τούτων συμφύτους ἡδονὰς ἑπομένας.", "st": "51d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἔστι γὰρ οὖν καὶ τοῦτο.", "st": "51d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ δὲ περὶ τὰς ὀσμὰς ἧττον μὲν τούτων θεῖον γένος ἡδονῶν: τὸ δὲ μὴ συμμεμεῖχθαι ἐν αὐταῖς ἀναγκαίους λύπας, καὶ ὅπῃ τοῦτο καὶ ἐν ὅτῳ τυγχάνει γεγονὸς ἡμῖν, τοῦτ᾽ ἐκείνοις τίθημι ἀντίστροφον ἅπαν. ἀλλ᾽, εἰ κατανοεῖς, ταῦτα εἴδη δύο ⟨ὧν⟩ λέγομεν ἡδονῶν.", "st": "51e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> κατανοῶ.", "st": "51e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἔτι δὴ τοίνυν τούτοις προσθῶμεν τὰς περὶ τὰ", "st": "51e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μαθήματα ἡδονάς, εἰ ἄρα δοκοῦσιν ἡμῖν αὗται πείνας μὲν μὴ ἔχειν τοῦ μανθάνειν μηδὲ διὰ μαθημάτων πείνην ἀλγηδόνας ἐξ ἀρχῆς γιγνομένας.", "st": "52a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀλλ᾽ οὕτω συνδοκεῖ.", "st": "52a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί δέ; μαθημάτων πληρωθεῖσιν ἐὰν ὕστερον ἀποβολαὶ διὰ τῆς λήθης γίγνωνται, καθορᾷς τινας ἐν αὐταῖς ἀλγηδόνας;", "st": "52a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὔ τι φύσει γε, ἀλλ᾽ ἔν τισι λογισμοῖς τοῦ", "st": "52a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> παθήματος, ὅταν τις στερηθεὶς λυπηθῇ διὰ τὴν χρείαν.", "st": "52b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μήν, ὦ μακάριε, νῦν γε ἡμεῖς αὐτὰ τὰ τῆς φύσεως μόνον παθήματα χωρὶς τοῦ λογισμοῦ διαπεραίνομεν.", "st": "52b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀληθῆ τοίνυν λέγεις ὅτι χωρὶς λύπης ἡμῖν λήθη γίγνεται ἑκάστοτε ἐν τοῖς μαθήμασιν.", "st": "52b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ταύτας τοίνυν τὰς τῶν μαθημάτων ἡδονὰς ἀμείκτους τε εἶναι λύπαις ῥητέον καὶ οὐδαμῶς τῶν πολλῶν ἀνθρώπων ἀλλὰ τῶν σφόδρα ὀλίγων.", "st": "52b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς γὰρ οὐ ῥητέον;", "st": "52b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ὅτε μετρίως ἤδη διακεκρίμεθα χωρὶς τάς τε καθαρὰς ἡδονὰς καὶ τὰς σχεδὸν ἀκαθάρτους ὀρθῶς ἂν λεχθείσας, προσθῶμεν τῷ λόγῳ ταῖς μὲν σφοδραῖς ἡδοναῖς ἀμετρίαν, ταῖς δὲ μὴ τοὐναντίον ἐμμετρίαν: καὶ ⟨τὰς⟩ τὸ μέγα καὶ τὸ σφοδρὸν αὖ ⟨δεχομένας⟩, καὶ πολλάκις καὶ ὀλιγάκις γιγνομένας τοιαύτας, τῆς τοῦ ἀπείρου γε ἐκείνου καὶ ἧττον καὶ μᾶλλον διά τε σώματος καὶ ψυχῆς φερομένου", "st": "52c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> [προς]θῶμεν αὐτὰς εἶναι γένους, τὰς δὲ μὴ τῶν ἐμμέτρων.", "st": "52d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθότατα λέγεις, ὦ Σώκρατες.", "st": "52d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἔτι τοίνυν πρὸς τούτοις μετὰ ταῦτα τόδε αὐτῶν διαθεατέον.", "st": "52d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ ποῖον;", "st": "52d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί ποτε χρὴ φάναι πρὸς ἀλήθειαν εἶναι; τὸ καθαρόν τε καὶ εἰλικρινὲς ἢ τὸ σφόδρα τε καὶ τὸ πολὺ καὶ τὸ μέγα καὶ τὸ ἰταμόν;", "st": "52d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί ποτ᾽ ἄρα, ὦ Σώκρατες, ἐρωτᾷς βουλόμενος;", "st": "52d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μηδέν, ὦ Πρώταρχε, ἐπιλείπειν ἐλέγχων ἡδονῆς", "st": "52d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τε καὶ ἐπιστήμης, εἰ τὸ μὲν ἄρ᾽ αὐτῶν ἑκατέρου καθαρόν ἐστι, τὸ δ᾽ οὐ καθαρόν, ἵνα καθαρὸν ἑκάτερον ἰὸν εἰς τὴν κρίσιν ἐμοὶ καὶ σοὶ καὶ συνάπασι τοῖσδε ῥᾴω παρέχῃ τὴν κρίσιν.", "st": "52e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθότατα.", "st": "52e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἴθι δή, περὶ πάντων, ὅσα καθαρὰ γένη λέγομεν, οὑτωσὶ διανοηθῶμεν: προελόμενοι πρῶτον αὐτῶν ἕν τι σκοπῶμεν.", "st": "52e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί οὖν προελώμεθα;", "st": "53a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ λευκὸν ἐν τοῖς πρῶτον, εἰ βούλει, θεασώμεθα γένος.", "st": "53a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν.", "st": "53a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πῶς οὖν ἂν λευκοῦ καὶ τίς καθαρότης ἡμῖν εἴη; πότερα τὸ μέγιστόν τε καὶ πλεῖστον ἢ τὸ ἀκρατέστατον, ἐν ᾧ χρώματος μηδεμία μοῖρα ἄλλη μηδενὸς ἐνείη;", "st": "53a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> δῆλον ὅτι τὸ μάλιστ᾽ εἰλικρινὲς ὄν.", "st": "53a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὀρθῶς. ἆρ᾽ οὖν οὐ τοῦτο ἀληθέστατον, ὦ Πρώταρχε,", "st": "53a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ ἅμα δὴ κάλλιστον τῶν λευκῶν πάντων θήσομεν, ἀλλ᾽ οὐ τὸ πλεῖστον οὐδὲ τὸ μέγιστον;", "st": "53b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθότατά γε.", "st": "53b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> σμικρὸν ἄρα καθαρὸν λευκὸν μεμειγμένου πολλοῦ λευκοῦ λευκότερον ἅμα καὶ κάλλιον καὶ ἀληθέστερον ἐὰν φῶμεν γίγνεσθαι, παντάπασιν ἐροῦμεν ὀρθῶς.", "st": "53b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθότατα μὲν οὖν.", "st": "53b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί οὖν; οὐ δήπου πολλῶν δεησόμεθα παραδειγμάτων τοιούτων ἐπὶ τὸν τῆς ἡδονῆς πέρι λόγον, ἀλλ᾽ ἀρκεῖ νοεῖν ἡμῖν αὐτόθεν ὡς ἄρα καὶ σύμπασα ἡδονὴ σμικρὰ", "st": "53b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μεγάλης καὶ ὀλίγη πολλῆς, καθαρὰ λύπης, ἡδίων καὶ ἀληθεστέρα καὶ καλλίων γίγνοιτ᾽ ἄν.", "st": "53c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> σφόδρα μὲν οὖν, καὶ τό γε παράδειγμα ἱκανόν.", "st": "53c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί δὲ τὸ τοιόνδε; ἆρα περὶ ἡδονῆς οὐκ ἀκηκόαμεν ὡς ἀεὶ γένεσίς ἐστιν, οὐσία δὲ οὐκ ἔστι τὸ παράπαν ἡδονῆς; κομψοὶ γὰρ δή τινες αὖ τοῦτον τὸν λόγον ἐπιχειροῦσι μηνύειν ἡμῖν, οἷς δεῖ χάριν ἔχειν.", "st": "53c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί δή;", "st": "53c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> διαπερανοῦμαί σοι τοῦτ᾽ αὐτὸ ἐπανερωτῶν, ὦ", "st": "53c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> Πρώταρχε φίλε.", "st": "53d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγε καὶ ἐρώτα μόνον.", "st": "53d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἐστὸν δή τινε δύο, τὸ μὲν αὐτὸ καθ᾽ αὑτό, τὸ δ᾽ ἀεὶ ἐφιέμενον ἄλλου.", "st": "53d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς τούτω καὶ τίνε λέγεις;", "st": "53d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ μὲν σεμνότατον ἀεὶ πεφυκός, τὸ δ᾽ ἐλλιπὲς ἐκείνου.", "st": "53d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγ᾽ ἔτι σαφέστερον.", "st": "53d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> παιδικά που καλὰ καὶ ἀγαθὰ τεθεωρήκαμεν ἅμα καὶ ἐραστὰς ἀνδρείους αὐτῶν.", "st": "53d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> σφόδρα γε.", "st": "53d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τούτοις τοίνυν ἐοικότα δυοῖν οὖσι δύο ἄλλα ζήτει", "st": "53d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> κατὰ πάνθ᾽ ὅσα λέγομεν εἶναι.", "st": "53e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ τρίτον ἔτ᾽ ἐρῶ; λέγε σαφέστερον, ὦ Σώκρατες, ὅτι λέγεις.", "st": "53e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδέν τι ποικίλον, ὦ Πρώταρχε: ἀλλ᾽ ὁ λόγος ἐρεσχηλεῖ νῷν, λέγει δ᾽ ὅτι τὸ μὲν ἕνεκά του τῶν ὄντων ἔστ᾽ ἀεί, τὸ δ᾽ οὗ χάριν ἑκάστοτε τὸ τινὸς ἕνεκα γιγνόμενον ἀεὶ γίγνεται.", "st": "53e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> μόγις ἔμαθον διὰ τὸ πολλάκις λεχθῆναι.", "st": "53e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τάχα δ᾽ ἴσως, ὦ παῖ, μᾶλλον μαθησόμεθα προελθόντος", "st": "53e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τοῦ λόγου.", "st": "54a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί γὰρ οὔ;", "st": "54a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> δύο δὴ τάδε ἕτερα λάβωμεν.", "st": "54a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ποῖα;", "st": "54a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἓν μέν τι γένεσιν πάντων, τὴν δὲ οὐσίαν ἕτερον ἕν.", "st": "54a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> δύο ἀποδέχομαί σου ταῦτα, οὐσίαν καὶ γένεσιν.", "st": "54a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὀρθότατα. πότερον οὖν τούτων ἕνεκα ποτέρου, τὴν γένεσιν οὐσίας ἕνεκα φῶμεν ἢ τὴν οὐσίαν εἶναι γενέσεως ἕνεκα;", "st": "54a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τοῦτο ὃ προσαγορεύεται οὐσία εἰ γενέσεως ἕνεκα τοῦτ᾽ ἔστιν ὅπερ ἐστί, νῦν πυνθάνῃ;", "st": "54a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> φαίνομαι.", "st": "54a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πρὸς θεῶν ἆρ᾽ [ἂν] ἐπανερωτᾷς με τοιόνδε τι; λέγ᾽, ὦ Πρώταρχε, μοί, πότερα πλοίων ναυπηγίαν ἕνεκα φῂς γίγνεσθαι μᾶλλον ἢ πλοῖα ἕνεκα ναυπηγίας, καὶ πάνθ᾽ ὁπόσα τοιαῦτ᾽ ἐστίν;", "st": "54b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> λέγω τοῦτ᾽ αὐτό, ὦ Πρώταρχε.", "st": "54b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί οὖν οὐκ αὐτὸς ἀπεκρίνω σαυτῷ, ὦ Σώκρατες;", "st": "54b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδὲν ὅτι οὔ: σὺ μέντοι τοῦ λόγου συμμέτεχε.", "st": "54b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν.", "st": "54b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> φημὶ δὴ γενέσεως μὲν ἕνεκα φάρμακά τε καὶ πάντα ὄργανα καὶ πᾶσαν ὕλην παρατίθεσθαι πᾶσιν, ἑκάστην δὲ γένεσιν ἄλλην ἄλλης οὐσίας τινὸς ἑκάστης ἕνεκα γίγνεσθαι, σύμπασαν δὲ γένεσιν οὐσίας ἕνεκα γίγνεσθαι συμπάσης.", "st": "54c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> σαφέστατα μὲν οὖν.", "st": "54c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἡδονή γε, εἴπερ γένεσίς ἐστιν, ἕνεκά τινος οὐσίας ἐξ ἀνάγκης γίγνοιτ᾽ ἄν.", "st": "54c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν;", "st": "54c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τό γε μὴν οὗ ἕνεκα τὸ ἕνεκά του γιγνόμενον ἀεὶ γίγνοιτ᾽ ἄν, ἐν τῇ τοῦ ἀγαθοῦ μοίρᾳ ἐκεῖνό ἐστι: τὸ δὲ τινὸς ἕνεκα γιγνόμενον εἰς ἄλλην, ὦ ἄριστε, μοῖραν θετέον.", "st": "54c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀναγκαιότατον.", "st": "54c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ οὖν ἡδονή γε εἴπερ γένεσίς ἐστιν, εἰς ἄλλην ἢ τὴν τοῦ ἀγαθοῦ μοῖραν αὐτὴν τιθέντες ὀρθῶς θήσομεν;", "st": "54d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθότατα μὲν οὖν.", "st": "54d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ὅπερ ἀρχόμενος εἶπον τούτου τοῦ λόγου, τῷ μηνύσαντι τῆς ἡδονῆς πέρι τὸ γένεσιν μέν, οὐσίαν δὲ μηδ᾽ ἡντινοῦν αὐτῆς εἶναι, χάριν ἔχειν δεῖ: δῆλον γὰρ ὅτι οὗτος τῶν φασκόντων ἡδονὴν ἀγαθὸν εἶναι καταγελᾷ.", "st": "54d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> σφόδρα γε.", "st": "54d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν αὑτὸς οὗτος ἑκάστοτε καὶ τῶν ἐν ταῖς γενέσεσιν ἀποτελουμένων καταγελάσεται.", "st": "54e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς δὴ καὶ ποίων λέγεις;", "st": "54e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τῶν ὅσοι ἐξιώμενοι ἢ πείνην ἢ δίψαν ἤ τι τῶν τοιούτων, ὅσα γένεσις ἐξιᾶται, χαίρουσι διὰ τὴν γένεσιν ἅτε ἡδονῆς οὔσης αὐτῆς, καί φασι ζῆν οὐκ ἂν δέξασθαι μὴ διψῶντές τε καὶ πεινῶντες καὶ τἆλλα ἅ τις ἂν εἴποι πάντα τὰ ἑπόμενα τοῖς τοιούτοις παθήμασι μὴ πάσχοντες.", "st": "54e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἐοίκασι γοῦν.", "st": "55a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τῷ γίγνεσθαί γε τοὐναντίον ἅπαντες τὸ φθείρεσθαι φαῖμεν ἄν.", "st": "55a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀναγκαῖον.", "st": "55a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὴν δὴ φθορὰν καὶ γένεσιν αἱροῖτ᾽ ἄν τις τοῦθ᾽ αἱρούμενος, ἀλλ᾽ οὐ τὸν τρίτον ἐκεῖνον βίον, τὸν ἐν ᾧ μήτε χαίρειν μήτε λυπεῖσθαι, φρονεῖν δ᾽ ἦν [δυνατὸν] ὡς οἷόν τε καθαρώτατα.", "st": "55a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πολλή τις, ὡς ἔοικεν, ὦ Σώκρατες, ἀλογία συμβαίνει γίγνεσθαι, ἐάν τις τὴν ἡδονὴν ὡς ἀγαθὸν ἡμῖν τιθῆται.", "st": "55a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πολλή, ἐπεὶ καὶ τῇδε ἔτι λέγωμεν.", "st": "55a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῇ;", "st": "55a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πῶς οὐκ ἄλογόν ἐστι μηδὲν ἀγαθὸν εἶναι μηδὲ καλὸν μήτε ἐν σώμασι μήτ᾽ ἐν πολλοῖς ἄλλοις πλὴν ἐν ψυχῇ, καὶ ἐνταῦθα ἡδονὴν μόνον, ἀνδρείαν δὲ ἢ σωφροσύνην ἢ νοῦν ἤ τι τῶν ἄλλων ὅσα ἀγαθὰ εἴληχε ψυχή, μηδὲν τοιοῦτον εἶναι; πρὸς τούτοις δὲ ἔτι τὸν μὴ χαίροντα, ἀλγοῦντα δέ, ἀναγκάζεσθαι φάναι κακὸν εἶναι τότε ὅταν ἀλγῇ, κἂν ᾖ ἄριστος πάντων, καὶ τὸν χαίροντα αὖ, ὅσῳ μᾶλλον χαίρει,", "st": "55b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τότε ὅταν χαίρῃ, τοσούτῳ διαφέρειν πρὸς ἀρετήν.", "st": "55c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάντ᾽ ἐστὶ ταῦτα, ὦ Σώκρατες, ὡς δυνατὸν ἀλογώτατα.", "st": "55c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μὴ τοίνυν ἡδονῆς μὲν πάντως ἐξέτασιν πᾶσαν ἐπιχειρῶμεν ποιήσασθαι, νοῦ δὲ καὶ ἐπιστήμης οἷον φειδόμενοι σφόδρα φανῶμεν: γενναίως δέ, εἴ πῄ τι σαθρὸν ἔχει, πᾶν περικρούωμεν, ὡς ὅτι καθαρώτατόν ἐστ᾽ αὐτῶν φύσει, τοῦτο κατιδόντες εἰς τὴν κρίσιν χρώμεθα τὴν κοινὴν τοῖς τε τούτων καὶ τοῖς τῆς ἡδονῆς μέρεσιν ἀληθεστάτοις.", "st": "55c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθῶς.", "st": "55c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἡμῖν τὸ μὲν οἶμαι δημιουργικόν ἐστι τῆς περὶ τὰ μαθήματα ἐπιστήμης, τὸ δὲ περὶ παιδείαν καὶ τροφήν. ἢ πῶς;", "st": "55d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὕτως.", "st": "55d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἐν δὴ ταῖς χειροτεχνικαῖς διανοηθῶμεν πρῶτα εἰ τὸ μὲν ἐπιστήμης αὐτῶν μᾶλλον ἐχόμενον, τὸ δ᾽ ἧττον ἔνι, καὶ δεῖ τὰ μὲν ὡς καθαρώτατα νομίζειν, τὰ δ᾽ ὡς ἀκαθαρτότερα.", "st": "55d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὐκοῦν χρή.", "st": "55d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὰς τοίνυν ἡγεμονικὰς διαληπτέον ἑκάστων αὐτῶν χωρίς;", "st": "55d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ποίας καὶ πῶς;", "st": "55d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οἷον πασῶν που τεχνῶν ἄν τις ἀριθμητικὴν χωρίζῃ καὶ μετρητικὴν καὶ στατικήν, ὡς ἔπος εἰπεῖν φαῦλον τὸ καταλειπόμενον ἑκάστης ἂν γίγνοιτο.", "st": "55e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> φαῦλον μὲν δή.", "st": "55e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ γοῦν μετὰ ταῦτ᾽ εἰκάζειν λείποιτ᾽ ἂν καὶ τὰς αἰσθήσεις καταμελετᾶν ἐμπειρίᾳ καί τινι τριβῇ, ταῖς τῆς στοχαστικῆς προσχρωμένους δυνάμεσιν ἃς πολλοὶ τέχνας", "st": "55e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἐπονομάζουσι, μελέτῃ καὶ πόνῳ τὴν ῥώμην ἀπειργασμένας.", "st": "56a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀναγκαιότατα λέγεις.", "st": "56a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν μεστὴ μέν που μουσικὴ πρῶτον, τὸ σύμφωνον ἁρμόττουσα οὐ μέτρῳ ἀλλὰ μελέτης στοχασμῷ, καὶ σύμπασα αὐτῆς αὐλητική, τὸ μέτρον ἑκάστης χορδῆς τῷ στοχάζεσθαι φερομένης θηρεύουσα, ὥστε πολὺ μεμειγμένον ἔχειν τὸ μὴ σαφές, σμικρὸν δὲ τὸ βέβαιον.", "st": "56a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀληθέστατα.", "st": "56a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν ἰατρικήν τε καὶ γεωργίαν καὶ κυβερνητικὴν καὶ στρατηγικὴν ὡσαύτως εὑρήσομεν ἐχούσας.", "st": "56b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ πάνυ γε.", "st": "56b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τεκτονικὴν δέ γε οἶμαι πλείστοις μέτροις τε καὶ ὀργάνοις χρωμένην τὰ πολλὴν ἀκρίβειαν αὐτῇ πορίζοντα τεχνικωτέραν τῶν πολλῶν ἐπιστημῶν παρέχεται.", "st": "56b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῇ;", "st": "56b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> κατά τε ναυπηγίαν καὶ κατ᾽ οἰκοδομίαν καὶ ἐν πολλοῖς ἄλλοις τῆς ξυλουργικῆς. κανόνι γὰρ οἶμαι καὶ", "st": "56b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τόρνῳ χρῆται καὶ διαβήτῃ καὶ στάθμῃ καί τινι προσαγωγίῳ κεκομψευμένῳ.", "st": "56c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ πάνυ γε, ὦ Σώκρατες, ὀρθῶς λέγεις.", "st": "56c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> θῶμεν τοίνυν διχῇ τὰς λεγομένας τέχνας, τὰς μὲν μουσικῇ συνεπομένας ἐν τοῖς ἔργοις ἐλάττονος ἀκριβείας μετισχούσας, τὰς δὲ τεκτονικῇ πλείονος.", "st": "56c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> κείσθω.", "st": "56c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τούτων δὲ ταύτας ἀκριβεστάτας εἶναι τέχνας, ἃς νυνδὴ πρώτας εἴπομεν.", "st": "56c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀριθμητικὴν φαίνῃ μοι λέγειν καὶ ὅσας μετὰ ταύτης τέχνας ἐφθέγξω νυνδή.", "st": "56c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πάνυ μὲν οὖν. ἀλλ᾽, ὦ Πρώταρχε, ἆρ᾽ οὐ διττὰς αὖ καὶ ταύτας λεκτέον; ἢ πῶς;", "st": "56d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ποίας δὴ λέγεις;", "st": "56d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀριθμητικὴν πρῶτον ἆρ᾽ οὐκ ἄλλην μέν τινα τὴν τῶν πολλῶν φατέον, ἄλλην δ᾽ αὖ τὴν τῶν φιλοσοφούντων;", "st": "56d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῇ ποτε διορισάμενος οὖν ἄλλην, τὴν δὲ ἄλλην θείη τις ἂν ἀριθμητικήν;", "st": "56d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐ σμικρὸς ὅρος, ὦ Πρώταρχε. οἱ μὲν γάρ που μονάδας ἀνίσους καταριθμοῦνται τῶν περὶ ἀριθμόν, οἷον στρατόπεδα δύο καὶ βοῦς δύο καὶ δύο τὰ σμικρότατα ἢ καὶ", "st": "56d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὰ πάντων μέγιστα: οἱ δ᾽ οὐκ ἄν ποτε αὐτοῖς συνακολουθήσειαν, εἰ μὴ μονάδα μονάδος ἑκάστης τῶν μυρίων μηδεμίαν ἄλλην ἄλλης διαφέρουσάν τις θήσει.", "st": "56e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ μάλα εὖ λέγεις οὐ σμικρὰν διαφορὰν τῶν περὶ ἀριθμὸν τευταζόντων, ὥστε λόγον ἔχειν δύ᾽ αὐτὰς εἶναι.", "st": "56e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί δέ; λογιστικὴ καὶ μετρητικὴ ⟨ἡ⟩ κατὰ τεκτονικὴν καὶ κατ᾽ ἐμπορικὴν τῆς κατὰ φιλοσοφίαν γεωμετρίας τε καὶ", "st": "56e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> λογισμῶν καταμελετωμένων — πότερον ὡς μία ἑκατέρα λεκτέον ἢ δύο τιθῶμεν;", "st": "57a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τῇ πρόσθεν ἑπόμενος ἔγωγ᾽ ἂν δύο κατὰ τὴν ἐμὴν ψῆφον τιθείην ἑκατέραν τούτων.", "st": "57a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὀρθῶς. οὗ δ᾽ ἕνεκα ταῦτα προηνεγκάμεθα εἰς τὸ μέσον, ἆρα ἐννοεῖς;", "st": "57a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἴσως, ἀλλὰ σὲ βουλοίμην ἂν ἀποφήνασθαι τὸ νῦν ἐρωτώμενον.", "st": "57a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> δοκεῖ τοίνυν ἔμοιγε οὗτος ὁ λόγος, οὐχ ἧττον ἢ ὅτε λέγειν αὐτὸν ἠρχόμεθα, ταῖς ἡδοναῖς ζητῶν ἀντίστροφον ἐνταῦθα προβεβληκέναι σκοπῶν ἆρά ἐστί τις ἑτέρας", "st": "57a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἄλλη καθαρωτέρα ἐπιστήμης ἐπιστήμη, καθάπερ ἡδονῆς ἡδονή.", "st": "57b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ μάλα σαφὲς τοῦτό γε, ὅτι ταῦθ᾽ ἕνεκα τούτων ἐπικεχείρηκεν.", "st": "57b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί οὖν; ἆρ᾽ οὐκ ἐν μὲν τοῖς ἔμπροσθεν ἐπ᾽ ἄλλοις ἄλλην τέχνην οὖσαν ἀνηυρήκειν σαφεστέραν καὶ ἀσαφεστέραν ἄλλην ἄλλης;", "st": "57b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν.", "st": "57b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἐν τούτοις δὲ ἆρ᾽ οὔ τινα τέχνην ὡς ὁμώνυμον φθεγξάμενος, εἰς δόξαν καταστήσας ὡς μιᾶς, πάλιν ὡς", "st": "57b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> δυοῖν ἐπανερωτᾷ τούτοιν αὐτοῖν τὸ σαφὲς καὶ τὸ καθαρὸν περὶ ταῦτα πότερον ἡ τῶν φιλοσοφούντων ἢ μὴ φιλοσοφούντων ἀκριβέστερον ἔχει;", "st": "57c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ μάλα δοκεῖ μοι τοῦτο διερωτᾶν.", "st": "57c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τίν᾽ οὖν, ὦ Πρώταρχε, αὐτῷ δίδομεν ἀπόκρισιν;", "st": "57c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὦ Σώκρατες, εἰς θαυμαστὸν διαφορᾶς μέγεθος εἰς σαφήνειαν προεληλύθαμεν ἐπιστημῶν.", "st": "57c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἀποκρινούμεθα ῥᾷον;", "st": "57c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν; καὶ εἰρήσθω γε ὅτι πολὺ μὲν αὗται τῶν ἄλλων τεχνῶν διαφέρουσι, τούτων δ᾽ αὐτῶν αἱ περὶ τὴν", "st": "57c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τῶν ὄντως φιλοσοφούντων ὁρμὴν ἀμήχανον ἀκριβείᾳ καὶ ἀληθείᾳ περὶ μέτρα τε καὶ ἀριθμοὺς διαφέρουσιν.", "st": "57d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἔστω ταῦτα κατὰ σέ, καὶ σοὶ δὴ πιστεύοντες θαρροῦντες ἀποκρινόμεθα τοῖς δεινοῖς περὶ λόγων ὁλκήν", "st": "57d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ ποῖον;", "st": "57d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὡς εἰσὶ δύο ἀριθμητικαὶ καὶ δύο μετρητικαὶ καὶ ταύταις ἄλλαι τοιαῦται συνεπόμεναι συχναί, τὴν διδυμότητα ἔχουσαι ταύτην, ὀνόματος δὲ ἑνὸς κεκοινωμέναι.", "st": "57d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> διδῶμεν τύχῃ ἀγαθῇ τούτοις οὓς φῂς δεινοὺς εἶναι ταύτην τὴν ἀπόκρισιν, ὦ Σώκρατες.", "st": "57e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ταύτας οὖν λέγομεν ἐπιστήμας ἀκριβεῖς μάλιστ᾽ εἶναι;", "st": "57e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν.", "st": "57e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ᾽ ἡμᾶς, ὦ Πρώταρχε, ἀναίνοιτ᾽ ἂν ἡ τοῦ διαλέγεσθαι δύναμις, εἴ τινα πρὸ αὐτῆς ἄλλην κρίναιμεν.", "st": "57e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τίνα δὲ ταύτην αὖ δεῖ λέγειν;", "st": "57e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> δῆλον ὁτιὴ πᾶς ἂν τήν γε νῦν λεγομένην γνοίη: τὴν γὰρ περὶ τὸ ὂν καὶ τὸ ὄντως καὶ τὸ κατὰ ταὐτὸν ἀεὶ πεφυκὸς πάντως ἔγωγε οἶμαι ἡγεῖσθαι σύμπαντας ὅσοις νοῦ καὶ σμικρὸν προσήρτηται μακρῷ ἀληθεστάτην εἶναι γνῶσιν. σὺ δὲ τί; πῶς τοῦτο, ὦ Πρώταρχε, διακρίνοις ἄν;", "st": "58a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἤκουον μὲν ἔγωγε, ὦ Σώκρατες, ἑκάστοτε Γοργίου πολλάκις ὡς ἡ τοῦ πείθειν πολὺ διαφέροι πασῶν τεχνῶν", "st": "58a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάντα γὰρ ὑφ᾽ αὑτῇ δοῦλα δι᾽ ἑκόντων ἀλλ᾽ οὐ διὰ βίας ποιοῖτο, καὶ μακρῷ ἀρίστη πασῶν εἴη τῶν τεχνῶν — νῦν δ᾽ οὔτε σοὶ οὔτε δὴ ἐκείνῳ βουλοίμην ἂν ἐναντία τίθεσθαι.", "st": "58b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὰ ὅπλα μοι δοκεῖς βουληθεὶς εἰπεῖν αἰσχυνθεὶς ἀπολιπεῖν.", "st": "58b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἔστω νῦν ταῦτα ταύτῃ ὅπῃ σοι δοκεῖ.", "st": "58b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ οὖν αἴτιος ἐγὼ τοῦ μὴ καλῶς ὑπολαβεῖν σε;", "st": "58b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ ποῖον;", "st": "58b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκ, ὦ φίλε Πρώταρχε, τοῦτο ἔγωγε ἐζήτουν πω,", "st": "58b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τίς τέχνη ἢ τίς ἐπιστήμη πασῶν διαφέρει τῷ μεγίστη καὶ ἀρίστη καὶ πλεῖστα ὠφελοῦσα ἡμᾶς, ἀλλὰ τίς ποτε τὸ σαφὲς καὶ τἀκριβὲς καὶ τὸ ἀληθέστατον ἐπισκοπεῖ, κἂν εἰ σμικρὰ καὶ σμικρὰ ὀνινᾶσα, τοῦτ᾽ ἔστιν ὃ νῦν δὴ ζητοῦμεν. ἀλλ᾽ ὅρα — οὐδὲ γὰρ ἀπεχθήσῃ Γοργίᾳ, τῇ μὲν ἐκείνου ὑπάρχειν τέχνῃ διδοὺς πρὸς χρείαν τοῖς ἀνθρώποις κρατεῖν, ᾗ δ᾽ εἶπον ἐγὼ νῦν πραγματείᾳ, καθάπερ τοῦ λευκοῦ πέρι τότε ἔλεγον, κἂν εἰ σμικρόν, καθαρὸν δ᾽ εἴη, τοῦ πολλοῦ", "st": "58c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴ τοιούτου διαφέρειν, τούτῳ γ᾽ αὐτῷ τῷ ἀληθεστάτῳ, καὶ νῦν δὴ σφόδρα διανοηθέντες καὶ ἱκανῶς διαλογισάμενοι, μήτ᾽ εἴς τινας ὠφελίας ἐπιστημῶν βλέψαντες μήτε τινὰς εὐδοκιμίας, ἀλλ᾽ εἴ τις πέφυκε τῆς ψυχῆς ἡμῶν δύναμις ἐρᾶν τε τοῦ ἀληθοῦς καὶ πάντα ἕνεκα τούτου πράττειν, ταύτην εἴπωμεν διεξερευνησάμενοι — τὸ καθαρὸν νοῦ τε καὶ φρονήσεως εἰ ταύτην μάλιστα ἐκ τῶν εἰκότων ἐκτῆσθαι φαῖμεν ἂν ἤ τινα ἑτέραν ταύτης κυριωτέραν ἡμῖν ζητητέον.", "st": "58d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀλλὰ σκοπῶ, καὶ χαλεπὸν οἶμαι συγχωρῆσαί τινα ἄλλην ἐπιστήμην ἢ τέχνην τῆς ἀληθείας ἀντέχεσθαι μᾶλλον ἢ ταύτην.", "st": "58e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ οὖν ἐννοήσας τὸ τοιόνδε εἴρηκας ὃ λέγεις νῦν, ὡς αἱ πολλαὶ τέχναι, καὶ ὅσοι περὶ ταῦτα πεπόνηνται,", "st": "58e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πρῶτον μὲν δόξαις χρῶνται καὶ τὰ περὶ δόξαν ζητοῦσι συντεταμένως; εἴ τε καὶ περὶ φύσεως ἡγεῖταί τις ζητεῖν, οἶσθ᾽ ὅτι τὰ περὶ τὸν κόσμον τόνδε, ὅπῃ τε γέγονεν καὶ ὅπῃ πάσχει τι καὶ ὅπῃ ποιεῖ, ταῦτα ζητεῖ διὰ βίου; φαῖμεν ἂν ταῦτα, ἢ πῶς;", "st": "59a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὕτως.", "st": "59a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν οὐ περὶ τὰ ὄντα ἀεί, περὶ δὲ τὰ γιγνόμενα καὶ γενησόμενα καὶ γεγονότα ἡμῶν ὁ τοιοῦτος ἀνῄρηται τὸν πόνον;", "st": "59a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀληθέστατα.", "st": "59a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τούτων οὖν τι σαφὲς ἂν φαῖμεν τῇ ἀκριβεστάτῃ", "st": "59a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀληθείᾳ γίγνεσθαι, ὧν μήτε ἔσχε μηδὲν πώποτε κατὰ ταὐτὰ μήθ᾽ ἕξει μήτε εἰς τὸ νῦν παρὸν ἔχει;", "st": "59b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ πῶς;", "st": "59b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> περὶ οὖν τὰ μὴ κεκτημένα βεβαιότητα μηδ᾽ ἡντινοῦν πῶς ἄν ποτε βέβαιον γίγνοιθ᾽ ἡμῖν καὶ ὁτιοῦν;", "st": "59b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οἶμαι μὲν οὐδαμῶς.", "st": "59b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδ᾽ ἄρα νοῦς οὐδέ τις ἐπιστήμη περὶ αὐτά ἐστιν τὸ ἀληθέστατον ἔχουσα.", "st": "59b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὔκουν εἰκός γε.", "st": "59b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὸν μὲν δὴ σὲ καὶ ἐμὲ καὶ Γοργίαν καὶ Φίληβον χρὴ συχνὰ χαίρειν ἐᾶν, τόδε δὲ διαμαρτύρασθαι τῷ λόγῳ.", "st": "59b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ ποῖον;", "st": "59c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὡς ἢ περὶ ἐκεῖνα ἔσθ᾽ ἡμῖν τό τε βέβαιον καὶ τὸ καθαρὸν καὶ ἀληθὲς καὶ ὃ δὴ λέγομεν εἰλικρινές, περὶ τὰ ἀεὶ κατὰ τὰ αὐτὰ ὡσαύτως ἀμεικτότατα ἔχοντα, ἢ [δεύτερος] ἐκείνων ὅτι μάλιστά ἐστι συγγενές: τὰ δ᾽ ἄλλα πάντα δεύτερά τε καὶ ὕστερα λεκτέον.", "st": "59c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀληθέστατα λέγεις.", "st": "59c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὰ δὴ τῶν ὀνομάτων περὶ τὰ τοιαῦτα κάλλιστα ἆρ᾽ οὐ τοῖς καλλίστοις δικαιότατον ἀπονέμειν;", "st": "59c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> εἰκός γε.", "st": "59c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν νοῦς ἐστι καὶ φρόνησις ἅ γ᾽ ἄν τις τιμήσειε μάλιστα ὀνόματα;", "st": "59d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ναί.", "st": "59d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ταῦτ᾽ ἄρα ἐν ταῖς περὶ τὸ ὂν ὄντως ἐννοίαις ἐστὶν ἀπηκριβωμένα ὀρθῶς κείμενα καλεῖσθαι.", "st": "59d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν.", "st": "59d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν ἅ γε εἰς τὴν κρίσιν ἐγὼ τότε παρεσχόμην οὐκ ἄλλ᾽ ἐστὶν ἢ ταῦτα τὰ ὀνόματα.", "st": "59d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν, ὦ Σώκρατες;", "st": "59d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> εἶεν. τὸ μὲν δὴ φρονήσεώς τε καὶ ἡδονῆς πέρι", "st": "59d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πρὸς τὴν ἀλλήλων μεῖξιν εἴ τις φαίη καθαπερεὶ δημιουργοῖς ἡμῖν ἐξ ὧν ἢ ἐν οἷς δεῖ δημιουργεῖν τι παρακεῖσθαι, καλῶς ἂν τῷ λόγῳ ἀπεικάζοι.", "st": "59e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ μάλα.", "st": "59e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ δὴ μετὰ ταῦτα ἆρ᾽ οὐ μειγνύναι ἐπιχειρητέον;", "st": "59e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν;", "st": "59e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τάδε προειποῦσι καὶ ἀναμνήσασιν ἡμᾶς αὐτοὺς ὀρθότερον ἂν ἔχοι;", "st": "59e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὰ ποῖα;", "st": "59e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἃ καὶ πρότερον ἐμνήσθημεν: εὖ δ᾽ ἡ παροιμία", "st": "59e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> δοκεῖ ἔχειν, τὸ καὶ δὶς καὶ τρὶς τό γε καλῶς ἔχον ἐπαναπολεῖν τῷ λόγῳ δεῖν.", "st": "60a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί μήν;", "st": "60a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> φέρε δὴ πρὸς Διός: οἶμαι γὰρ οὑτωσί πως τὰ τότε λεχθέντα ῥηθῆναι.", "st": "60a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς;", "st": "60a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> Φίληβός φησι τὴν ἡδονὴν σκοπὸν ὀρθὸν πᾶσι ζῴοις γεγονέναι καὶ δεῖν πάντας τούτου στοχάζεσθαι, καὶ δὴ καὶ τἀγαθὸν τοῦτ᾽ αὐτὸ εἶναι σύμπασι, καὶ δύο ὀνόματα, ἀγαθὸν καὶ ἡδύ, ἑνί τινι καὶ φύσει μιᾷ τούτω ὀρθῶς", "st": "60a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τεθέντ᾽ ἔχειν: Σωκράτης δ᾽ ἓν μὲν οὔ φησι τοῦτ᾽ εἶναι, δύο δὲ καθάπερ τὰ ὀνόματα, καὶ τό τε ἀγαθὸν καὶ ἡδὺ διάφορον ἀλλήλων φύσιν ἔχειν, μᾶλλον δὲ μέτοχον εἶναι τῆς τοῦ ἀγαθοῦ μοίρας τὴν φρόνησιν ἢ τὴν ἡδονήν. οὐ ταῦτ᾽ ἔστιν τε καὶ ἦν τὰ τότε λεγόμενα, ὦ Πρώταρχε;", "st": "60b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> σφόδρα μὲν οὖν.", "st": "60b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ τόδε καὶ τότε καὶ νῦν ἡμῖν ἂν συνομολογοῖτο;", "st": "60b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ ποῖον;", "st": "60b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὴν τἀγαθοῦ διαφέρειν φύσιν τῷδε τῶν ἄλλων.", "st": "60b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τίνι;", "st": "60c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὧι παρείη τοῦτ᾽ ἀεὶ τῶν ζῴων διὰ τέλους πάντως καὶ πάντῃ, μηδενὸς ἑτέρου ποτὲ ἔτι προσδεῖσθαι, τὸ δὲ ἱκανὸν τελεώτατον ἔχειν. οὐχ οὕτως;", "st": "60c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὕτω μὲν οὖν.", "st": "60c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τῷ λόγῳ ἐπειράθημεν χωρὶς ἑκάτερον ἑκατέρου θέντες εἰς τὸν βίον ἑκάστων, ἄμεικτον μὲν ἡδονὴν φρονήσει, φρόνησιν δὲ ὡσαύτως ἡδονῆς μηδὲ τὸ σμικρότατον ἔχουσαν;", "st": "60c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἦν ταῦτα.", "st": "60c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μῶν οὖν ἡμῖν αὐτῶν τότε πότερον ἱκανὸν ἔδοξεν", "st": "60c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> εἶναί τῳ;", "st": "60d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ πῶς;", "st": "60d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> εἰ δέ γε παρηνέχθημέν τι τότε, νῦν ὁστισοῦν ἐπαναλαβὼν ὀρθότερον εἰπάτω, μνήμην καὶ φρόνησιν καὶ ἐπιστήμην καὶ ἀληθῆ δόξαν τῆς αὐτῆς ἰδέας τιθέμενος καὶ σκοπῶν εἴ τις ἄνευ τούτων δέξαιτ᾽ ἄν οἱ καὶ ὁτιοῦν εἶναι ἢ καὶ γίγνεσθαι, μὴ ὅτι δή γε ἡδονὴν εἴθ᾽ ὡς πλείστην εἴθ᾽ ὡς σφοδροτάτην, ἣν μήτε ἀληθῶς δοξάζοι χαίρειν μήτε τὸ παράπαν γιγνώσκοι τί ποτε πέπονθε πάθος μήτ᾽ αὖ", "st": "60d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μνήμην τοῦ πάθους μηδ᾽ ὁντινοῦν χρόνον ἔχοι. ταὐτὰ δὲ λεγέτω καὶ περὶ φρονήσεως, εἴ τις ἄνευ πάσης ἡδονῆς καὶ τῆς βραχυτάτης δέξαιτ᾽ ἂν φρόνησιν ἔχειν μᾶλλον ἢ μετά τινων ἡδονῶν ἢ πάσας ἡδονὰς χωρὶς φρονήσεως μᾶλλον ἢ μετὰ φρονήσεως αὖ τινος.", "st": "60e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὐκ ἔστιν, ὦ Σώκρατες, ἀλλ᾽ οὐδὲν δεῖ ταῦτά γε πολλάκις ἐπερωτᾶν.", "st": "60e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τό γε τέλεον καὶ πᾶσιν αἱρετὸν καὶ τὸ παντάπασιν ἀγαθὸν οὐδέτερον ἂν τούτων εἴη;", "st": "61a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς γὰρ ἄν;", "st": "61a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ τοίνυν ἀγαθὸν ἤτοι σαφῶς ἢ καί τινα τύπον αὐτοῦ ληπτέον, ἵν᾽, ὅπερ ἐλέγομεν, δευτερεῖα ὅτῳ δώσομεν ἔχωμεν.", "st": "61a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθότατα λέγεις.", "st": "61a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ὁδὸν μέν τινα ἐπὶ τἀγαθὸν εἰλήφαμεν;", "st": "61a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τίνα;", "st": "61a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καθάπερ εἴ τίς τινα ἄνθρωπον ζητῶν τὴν οἴκησιν", "st": "61a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πρῶτον ὀρθῶς ἵν᾽ οἰκεῖ πύθοιτο αὐτοῦ, μέγα τι δήπου πρὸς τὴν εὕρεσιν ἂν ἔχοι τοῦ ζητουμένου.", "st": "61b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς δ᾽ οὔ;", "st": "61b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ νῦν δή τις λόγος ἐμήνυσεν ἡμῖν, ὥσπερ καὶ κατ᾽ ἀρχάς, μὴ ζητεῖν ἐν τῷ ἀμείκτῳ βίῳ τἀγαθὸν ἀλλ᾽ ἐν τῷ μεικτῷ.", "st": "61b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ γε.", "st": "61b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἐλπὶς μὴν πλείων ἐν τῷ μειχθέντι καλῶς τὸ ζητούμενον ἔσεσθαι φανερώτερον ἢ ἐν τῷ μή;", "st": "61b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πολύ γε.", "st": "61b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τοῖς δὴ θεοῖς, ὦ Πρώταρχε, εὐχόμενοι κεραννύωμεν,", "st": "61b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> εἴτε Διόνυσος εἴτε Ἥφαιστος εἴθ᾽ ὅστις θεῶν ταύτην τὴν τιμὴν εἴληχε τῆς συγκράσεως.", "st": "61c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν.", "st": "61c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν καθάπερ ἡμῖν οἰνοχόοις τισὶ παρεστᾶσι κρῆναι — μέλιτος μὲν ἂν ἀπεικάζοι τις τὴν τῆς ἡδονῆς, τὴν δὲ τῆς φρονήσεως νηφαντικὴν καὶ ἄοινον αὐστηροῦ καὶ ὑγιεινοῦ τινος ὕδατος — ἃς προθυμητέον ὡς κάλλιστα συμμειγνύναι.", "st": "61c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς γὰρ οὔ;", "st": "61c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> φέρε δὴ πρότερον: ἆρα πᾶσαν ἡδονὴν πάσῃ φρονήσει μειγνύντες τοῦ καλῶς ἂν μάλιστα ἐπιτύχοιμεν;", "st": "61d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἴσως.", "st": "61d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ᾽ οὐκ ἀσφαλές. ᾗ δὲ ἀκινδυνότερον ἂν μειγνύοιμεν, δόξαν μοι δοκῶ τινα ἀποφήνασθαι ἄν.", "st": "61d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> λέγε τίνα.", "st": "61d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἦν ἡμῖν ἡδονή τε ἀληθῶς, ὡς οἰόμεθα, μᾶλλον ἑτέρας ἄλλη καὶ δὴ καὶ τέχνη τέχνης ἀκριβεστέρα;", "st": "61d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς γὰρ οὔ;", "st": "61d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ ἐπιστήμη δὴ ἐπιστήμης διάφορος, ἡ μὲν ἐπὶ", "st": "61d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὰ γιγνόμενα καὶ ἀπολλύμενα ἀποβλέπουσα, ἡ δ᾽ ἐπὶ τὰ μήτε γιγνόμενα μήτε ἀπολλύμενα, κατὰ ταὐτὰ δὲ καὶ ὡσαύτως ὄντα ἀεί. ταύτην εἰς τὸ ἀληθὲς ἐπισκοπούμενοι ἡγησάμεθα ἐκείνης ἀληθεστέραν εἶναι.", "st": "61e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν ὀρθῶς.", "st": "61e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν εἰ τἀληθέστατα τμήματα ἑκατέρας ἴδοιμεν πρῶτον συμμείξαντες, ἆρα ἱκανὰ ταῦτα συγκεκραμένα τὸν ἀγαπητότατον βίον ἀπεργασάμενα παρέχειν ἡμῖν, ἤ τινος ἔτι προσδεόμεθα καὶ τῶν μὴ τοιούτων;", "st": "61e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἐμοὶ γοῦν δοκεῖ δρᾶν οὕτως.", "st": "62a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἔστω δή τις ἡμῖν φρονῶν ἄνθρωπος αὐτῆς περὶ δικαιοσύνης ὅτι ἔστιν, καὶ λόγον ἔχων ἑπόμενον τῷ νοεῖν, καὶ δὴ καὶ περὶ τῶν ἄλλων πάντων τῶν ὄντων ὡσαύτως διανοούμενος.", "st": "62a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἔστω γὰρ οὖν.", "st": "62a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ οὖν οὗτος ἱκανῶς ἐπιστήμης ἕξει, κύκλου μὲν καὶ σφαίρας αὐτῆς τῆς θείας τὸν λόγον ἔχων, τὴν δὲ ἀνθρωπίνην ταύτην σφαῖραν καὶ τοὺς κύκλους τούτους ἀγνοῶν,", "st": "62a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ χρώμενος ἐν οἰκοδομίᾳ καὶ τοῖς ἄλλοις ὁμοίως κανόσι καὶ τοῖς κύκλοις;", "st": "62b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> γελοίαν διάθεσιν ἡμῶν, ὦ Σώκρατες, ἐν ταῖς θείαις οὖσαν μόνον ἐπιστήμαις λέγομεν.", "st": "62b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πῶς φῄς; ἦ τοῦ ψευδοῦς κανόνος ἅμα καὶ τοῦ κύκλου τὴν οὐ βέβαιον οὐδὲ καθαρὰν τέχνην ἐμβλητέον κοινῇ καὶ συγκρατέον;", "st": "62b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀναγκαῖον γάρ, εἰ μέλλει τις ἡμῶν καὶ τὴν ὁδὸν ἑκάστοτε ἐξευρήσειν οἴκαδε.", "st": "62b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἦ καὶ μουσικήν, ἣν ὀλίγον ἔμπροσθεν ἔφαμεν στοχάσεώς τε καὶ μιμήσεως μεστὴν οὖσαν καθαρότητος ἐνδεῖν;", "st": "62c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀναγκαῖον φαίνεται ἔμοιγε, εἴπερ γε ἡμῶν ὁ βίος ἔσται καὶ ὁπωσοῦν ποτε βίος.", "st": "62c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> βούλει δῆτα, ὥσπερ θυρωρὸς ὑπ᾽ ὄχλου τις ὠθούμενος καὶ βιαζόμενος, ἡττηθεὶς ἀναπετάσας τὰς θύρας ἀφῶ πάσας τὰς ἐπιστήμας εἰσρεῖν καὶ μείγνυσθαι ὁμοῦ καθαρᾷ τὴν ἐνδεεστέραν;", "st": "62c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὔκουν ἔγωγε οἶδα, ὦ Σώκρατες, ὅτι τις ἂν βλάπτοιτο πάσας λαβὼν τὰς ἄλλας ἐπιστήμας, ἔχων τὰς πρώτας.", "st": "62d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μεθιῶ δὴ τὰς συμπάσας ῥεῖν εἰς τὴν τῆς Ὁμήρου καὶ μάλα ποιητικῆς μισγαγκείας ὑποδοχήν;", "st": "62d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν.", "st": "62d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μεθεῖνται: καὶ πάλιν ἐπὶ τὴν τῶν ἡδονῶν πηγὴν ἰτέον. ὡς γὰρ διενοήθημεν αὐτὰς μειγνύναι, τὰ τῶν ἀληθῶν μόρια πρῶτον, οὐκ ἐξεγένεθ᾽ ἡμῖν, ἀλλὰ διὰ τὸ πᾶσαν ἀγαπᾶν ἐπιστήμην εἰς ταὐτὸν μεθεῖμεν ἁθρόας καὶ πρόσθεν", "st": "62d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τῶν ἡδονῶν.", "st": "62e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀληθέστατα λέγεις.", "st": "62e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὥρα δὴ βουλεύεσθαι νῷν καὶ περὶ τῶν ἡδονῶν, πότερα καὶ ταύτας πάσας ἁθρόας ἀφετέον ἢ καὶ τούτων πρώτας μεθετέον ἡμῖν ὅσαι ἀληθεῖς.", "st": "62e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πολύ τι διαφέρει πρός γε ἀσφάλειαν πρώτας τὰς ἀληθεῖς ἀφεῖναι.", "st": "62e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> μεθείσθων δή. τί δὲ μετὰ ταῦτα; ἆρ᾽ οὐκ εἰ μέν τινες ἀναγκαῖαι, καθάπερ ἐκεῖ, συμμεικτέον καὶ ταύτας;", "st": "62e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί δ᾽ οὔ; τάς γε ἀναγκαίας δήπουθεν.", "st": "62e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> εἰ δέ γε καί, καθάπερ τὰς τέχνας πάσας ἀβλαβές τε καὶ ὠφέλιμον ἦν ἐπίστασθαι διὰ βίου, καὶ νῦν δὴ ταὐτὰ λέγομεν περὶ τῶν ἡδονῶν, εἴπερ πάσας ἡδονὰς ἥδεσθαι διὰ βίου συμφέρον τε ἡμῖν ἐστι καὶ ἀβλαβὲς ἅπασι, πάσας συγκρατέον.", "st": "63a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς οὖν δὴ περὶ αὐτῶν τούτων λέγωμεν; καὶ πῶς ποιῶμεν;", "st": "63a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐχ ἡμᾶς, ὦ Πρώταρχε, διερωτᾶν χρή, τὰς ἡδονὰς δὲ αὐτὰς καὶ τὰς φρονήσεις διαπυνθανομένους τὸ τοιόνδε ἀλλήλων πέρι.", "st": "63a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ ποῖον;", "st": "63b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὦ φίλαι, εἴτε ἡδονὰς ὑμᾶς χρὴ προσαγορεύειν εἴτε ἄλλῳ ὁτῳοῦν ὀνόματι, μῶν οὐκ ἂν δέξαισθε οἰκεῖν μετὰ φρονήσεως πάσης ἢ χωρὶς τοῦ φρονεῖν; οἶμαι μὲν πρὸς ταῦτα τόδ᾽ αὐτὰς ἀναγκαιότατον εἶναι λέγειν.", "st": "63b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ ποῖον;", "st": "63b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὅτι καθάπερ ἔμπροσθεν ἐρρήθη, τὸ μόνον καὶ ἔρημον εἰλικρινὲς εἶναί τι γένος οὔτε πάνυ τι δυνατὸν οὔτ᾽", "st": "63b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὠφέλιμον: πάντων γε μὴν ἡγούμεθα γενῶν ἄριστον ἓν ἀνθ᾽ ἑνὸς συνοικεῖν ἡμῖν τὸ τοῦ γιγνώσκειν τἆλλά τε πάντα καὶ [αὖ τὴν] αὐτὴν ἡμῶν τελέως εἰς δύναμιν ἑκάστην.", "st": "63c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ καλῶς γε εἰρήκατε τὰ νῦν, φήσομεν.", "st": "63c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὀρθῶς. πάλιν τοίνυν μετὰ τοῦτο τὴν φρόνησιν καὶ τὸν νοῦν ἀνερωτητέον: ἆρ᾽ ἡδονῶν τι προσδεῖσθε ἐν τῇ συγκράσει; φαῖμεν ἂν αὖ τὸν νοῦν τε καὶ τὴν φρόνησιν ἀνερωτῶντες. ποίων, φαῖεν ἂν ἴσως, ἡδονῶν;", "st": "63c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> εἰκός.", "st": "63c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὁ δέ γ᾽ ἡμέτερος λόγος μετὰ τοῦτ᾽ ἐστὶν ὅδε. πρὸς ταῖς ἀληθέσιν ἐκείναις ἡδοναῖς, φήσομεν, ἆρ᾽ ἔτι προσδεῖσθ᾽ ὑμῖν τὰς μεγίστας ἡδονὰς συνοίκους εἶναι καὶ τὰς σφοδροτάτας; καὶ πῶς, ὦ Σώκρατες, ἴσως φαῖεν ἄν, αἵ γ᾽ ἐμποδίσματά τε μυρία ἡμῖν ἔχουσι, τὰς ψυχὰς ἐν αἷς οἰκοῦμεν ταράττουσαι διὰ μανίας [ἡδονάς], καὶ γίγνεσθαί", "st": "63d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τε ἡμᾶς τὴν ἀρχὴν οὐκ ἐῶσι, τά τε γιγνόμενα ἡμῶν τέκνα ὡς τὸ πολύ, δι᾽ ἀμέλειαν λήθην ἐμποιοῦσαι, παντάπασι διαφθείρουσιν; ἀλλ᾽ ἅς τε ἡδονὰς ἀληθεῖς καὶ καθαρὰς [ἃς] εἶπες, σχεδὸν οἰκείας ἡμῖν νόμιζε, καὶ πρὸς ταύταις τὰς μεθ᾽ ὑγιείας καὶ τοῦ σωφρονεῖν, καὶ δὴ καὶ συμπάσης ἀρετῆς ὁπόσαι καθάπερ θεοῦ ὀπαδοὶ γιγνόμεναι αὐτῇ συνακολουθοῦσι πάντῃ, ταύτας μείγνυ: τὰς δ᾽ ἀεὶ μετ᾽ ἀφροσύνης καὶ τῆς ἄλλης κακίας ἑπομένας πολλή που ἀλογία τῷ νῷ μειγνύναι τὸν βουλόμενον ὅτι καλλίστην ἰδόντα καὶ ἀστασιαστοτάτην μεῖξιν", "st": "63e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ κρᾶσιν, ἐν ταύτῃ μαθεῖν πειρᾶσθαι τί ποτε ἔν τ᾽ ἀνθρώπῳ καὶ τῷ παντὶ πέφυκεν ἀγαθὸν καὶ τίνα ἰδέαν αὐτὴν εἶναί ποτε μαντευτέον. ἆρ᾽ οὐκ ἐμφρόνως ταῦτα καὶ ἐχόντως ἑαυτὸν τὸν νοῦν φήσομεν ὑπέρ τε αὑτοῦ καὶ μνήμης καὶ δόξης ὀρθῆς ἀποκρίνασθαι τὰ νῦν ῥηθέντα;", "st": "64a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> παντάπασι μὲν οὖν.", "st": "64a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ μὴν καὶ τόδε γε ἀναγκαῖον, καὶ οὐκ ἄλλως ἄν ποτε γένοιτο οὐδ᾽ ἂν ἕν.", "st": "64a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ ποῖον;", "st": "64b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὧι μὴ μείξομεν ἀλήθειαν, οὐκ ἄν ποτε τοῦτο ἀληθῶς γίγνοιτο οὐδ᾽ ἂν γενόμενον εἴη.", "st": "64b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς γὰρ ἄν;", "st": "64b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδαμῶς. ἀλλ᾽ εἴ τινος ἔτι προσδεῖ τῇ συγκράσει ταύτῃ, λέγετε σὺ καὶ Φίληβος. ἐμοὶ μὲν γὰρ καθαπερεὶ κόσμος τις ἀσώματος ἄρξων καλῶς ἐμψύχου σώματος ὁ νῦν λόγος ἀπειργάσθαι φαίνεται.", "st": "64b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καὶ ἐμοὶ τοίνυν, ὦ Σώκρατες, οὕτω λέγε δεδόχθαι.", "st": "64b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ οὖν ἐπὶ μὲν τοῖς τοῦ ἀγαθοῦ νῦν ἤδη προθύροις [καὶ] τῆς οἰκήσεως ἐφεστάναι [τῆς τοῦ τοιούτου] λέγοντες ἴσως ὀρθῶς ἄν τινα τρόπον φαῖμεν;", "st": "64c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἐμοὶ γοῦν δοκεῖ.", "st": "64c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τί δῆτα ἐν τῇ συμμείξει τιμιώτατον ἅμα καὶ μάλιστ᾽ αἴτιον εἶναι δόξειεν ἂν ἡμῖν τοῦ πᾶσιν γεγονέναι προσφιλῆ τὴν τοιαύτην διάθεσιν; τοῦτο γὰρ ἰδόντες μετὰ τοῦτ᾽ ἐπισκεψόμεθα εἴθ᾽ ἡδονῇ εἴτε τῷ νῷ προσφυέστερον καὶ οἰκειότερον ἐν τῷ παντὶ συνέστηκεν.", "st": "64c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθῶς: τοῦτο γὰρ εἰς τὴν κρίσιν ἡμῖν ἐστι συμφορώτατον.", "st": "64d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν καὶ συμπάσης γε μείξεως οὐ χαλεπὸν ἰδεῖν τὴν αἰτίαν, δι᾽ ἣν ἢ παντὸς ἀξία γίγνεται ἡτισοῦν ἢ τὸ παράπαν οὐδενός.", "st": "64d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς λέγεις;", "st": "64d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδείς που τοῦτο ἀνθρώπων ἀγνοεῖ.", "st": "64d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ ποῖον;", "st": "64d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὅτι μέτρου καὶ τῆς συμμέτρου φύσεως μὴ τυχοῦσα ἡτισοῦν καὶ ὁπωσοῦν σύγκρασις πᾶσα ἐξ ἀνάγκης ἀπόλλυσι τά τε κεραννύμενα καὶ πρώτην αὑτήν: οὐδὲ", "st": "64d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> γὰρ κρᾶσις ἀλλά τις ἄκρατος συμπεφορημένη ἀληθῶς ἡ τοιαύτη γίγνεται ἑκάστοτε ὄντως τοῖς κεκτημένοις συμφορά.", "st": "64e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀληθέστατα.", "st": "64e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> νῦν δὴ καταπέφευγεν ἡμῖν ἡ τοῦ ἀγαθοῦ δύναμις εἰς τὴν τοῦ καλοῦ φύσιν: μετριότης γὰρ καὶ συμμετρία κάλλος δήπου καὶ ἀρετὴ πανταχοῦ συμβαίνει γίγνεσθαι.", "st": "64e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ μὲν οὖν.", "st": "64e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν ἀλήθειάν γε ἔφαμεν αὐτοῖς ἐν τῇ κράσει μεμεῖχθαι.", "st": "64e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάνυ γε.", "st": "64e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν εἰ μὴ μιᾷ δυνάμεθα ἰδέᾳ τὸ ἀγαθὸν θηρεῦσαι, σὺν τρισὶ λαβόντες, κάλλει καὶ συμμετρίᾳ καὶ ἀληθείᾳ, λέγωμεν ὡς τοῦτο οἷον ἓν ὀρθότατ᾽ ἂν αἰτιασαίμεθ᾽ ἂν τῶν ἐν τῇ συμμείξει, καὶ διὰ τοῦτο ὡς ἀγαθὸν ὂν τοιαύτην αὐτὴν γεγονέναι.", "st": "65a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθότατα μὲν οὖν.", "st": "65a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἤδη τοίνυν, ὦ Πρώταρχε, ἱκανὸς ἡμῖν γένοιτ᾽ ἂν ὁστισοῦν κριτὴς ἡδονῆς τε πέρι καὶ φρονήσεως, ὁπότερον", "st": "65a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> αὐτοῖν τοῦ ἀρίστου συγγενέστερόν τε καὶ τιμιώτερον ἐν ἀνθρώποις τέ ἐστι καὶ θεοῖς.", "st": "65b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> δῆλον μέν, ὅμως δ᾽ οὖν τῷ λόγῳ ἐπεξελθεῖν βέλτιον.", "st": "65b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καθ᾽ ἓν ἕκαστον τοίνυν τῶν τριῶν πρὸς τὴν ἡδονὴν καὶ τὸν νοῦν κρίνωμεν: δεῖ γὰρ ἰδεῖν ποτέρῳ ⟨ὡς⟩ μᾶλλον συγγενὲς ἕκαστον αὐτῶν ἀπονεμοῦμεν.", "st": "65b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> κάλλους καὶ ἀληθείας καὶ μετριότητος πέρι λέγεις;", "st": "65b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ναί. πρῶτον δέ γε ἀληθείας λαβοῦ, ὦ Πρώταρχε:", "st": "65b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ λαβόμενος βλέψας εἰς τρία, νοῦν καὶ ἀλήθειαν καὶ ἡδονήν, πολὺν ἐπισχὼν χρόνον ἀπόκριναι σαυτῷ πότερον ἡδονὴ συγγενέστερον ἢ νοῦς ἀληθείᾳ.", "st": "65c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τί δὲ χρόνου δεῖ; πολὺ γὰρ οἶμαι διαφέρετον. ἡδονὴ μὲν γὰρ ἁπάντων ἀλαζονίστατον, ὡς δὲ λόγος, καὶ ἐν ταῖς ἡδοναῖς ταῖς περὶ τἀφροδίσια, αἳ δὴ μέγισται δοκοῦσιν εἶναι, καὶ τὸ ἐπιορκεῖν συγγνώμην εἴληφε παρὰ θεῶν, ὡς", "st": "65c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> καθάπερ παίδων τῶν ἡδονῶν νοῦν οὐδὲ τὸν ὀλίγιστον κεκτημένων: νοῦς δὲ ἤτοι ταὐτὸν καὶ ἀλήθειά ἐστιν ἢ πάντων ὁμοιότατόν τε καὶ ἀληθέστατον.", "st": "65d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τὸ μετὰ τοῦτο τὴν μετριότητα ὡσαύτως σκέψαι, πότερον ἡδονὴ φρονήσεως ἢ φρόνησις ἡδονῆς πλείω κέκτηται;", "st": "65d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> εὔσκεπτόν γε καὶ ταύτην σκέψιν προβέβληκας: οἶμαι γὰρ ἡδονῆς μὲν καὶ περιχαρείας οὐδὲν τῶν ὄντων πεφυκὸς ἀμετρώτερον εὑρεῖν ἄν τινα, νοῦ δὲ καὶ ἐπιστήμης ἐμμετρώτερον οὐδ᾽ ἂν ἕν ποτε.", "st": "65d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καλῶς εἴρηκας. ὅμως δ᾽ ἔτι λέγε τὸ τρίτον. νοῦς ἡμῖν κάλλους μετείληφε πλεῖον ἢ τὸ τῆς ἡδονῆς γένος, ὥστε εἶναι καλλίω νοῦν ἡδονῆς, ἢ τοὐναντίον;", "st": "65e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀλλ᾽ οὖν φρόνησιν μὲν καὶ νοῦν, ὦ Σώκρατες, οὐδεὶς πώποτε οὔθ᾽ ὕπαρ οὔτ᾽ ὄναρ αἰσχρὸν οὔτε εἶδεν οὔτε ἐπενόησεν οὐδαμῇ οὐδαμῶς οὔτε γιγνόμενον οὔτε ὄντα οὔτε ἐσόμενον.", "st": "65e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὀρθῶς.", "st": "65e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἡδονὰς δέ γέ που, καὶ ταῦτα σχεδὸν τὰς μεγίστας, ὅταν ἴδωμεν ἡδόμενον ὁντινοῦν, ἢ τὸ γελοῖον ἐπ᾽ αὐταῖς ἢ τὸ", "st": "65e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πάντων αἴσχιστον ἑπόμενον ὁρῶντες αὐτοί τε αἰσχυνόμεθα καὶ ἀφανίζοντες κρύπτομεν ὅτι μάλιστα, νυκτὶ πάντα τὰ τοιαῦτα διδόντες, ὡς φῶς οὐ δέον ὁρᾶν αὐτά.", "st": "66a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πάντῃ δὴ φήσεις, ὦ Πρώταρχε, ὑπό τε ἀγγέλων πέμπων καὶ παροῦσι φράζων, ὡς ἡδονὴ κτῆμα οὐκ ἔστι πρῶτον οὐδ᾽ αὖ δεύτερον, ἀλλὰ πρῶτον μέν πῃ περὶ μέτρον καὶ τὸ μέτριον καὶ καίριον καὶ πάντα ὁπόσα χρὴ τοιαῦτα νομίζειν, τὴν ἀίδιον ᾑρῆσθαι.", "st": "66a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> φαίνεται γοῦν ἐκ τῶν νῦν λεγομένων.", "st": "66a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> δεύτερον μὴν περὶ τὸ σύμμετρον καὶ καλὸν καὶ τὸ τέλεον καὶ ἱκανὸν καὶ πάνθ᾽ ὁπόσα τῆς γενεᾶς αὖ ταύτης ἐστίν.", "st": "66b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἔοικε γοῦν.", "st": "66b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ τοίνυν τρίτον, ὡς ἡ ἐμὴ μαντεία, νοῦν καὶ φρόνησιν τιθεὶς οὐκ ἂν μέγα τι τῆς ἀληθείας παρεξέλθοις.", "st": "66b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἴσως.", "st": "66b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ οὖν οὐ τέταρτα, ἃ τῆς ψυχῆς αὐτῆς ἔθεμεν, ἐπιστήμας τε καὶ τέχνας καὶ δόξας ὀρθὰς λεχθείσας, ταῦτ᾽", "st": "66b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> εἶναι τὰ πρὸς τοῖς τρισὶ τέταρτα, εἴπερ τοῦ ἀγαθοῦ γέ ἐστι μᾶλλον [ἢ] τῆς ἡδονῆς συγγενῆ;", "st": "66c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τάχ᾽ ἄν.", "st": "66c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πέμπτας τοίνυν, ἃς ἡδονὰς ἔθεμεν ἀλύπους ὁρισάμενοι, καθαρὰς ἐπονομάσαντες τῆς ψυχῆς αὐτῆς, ἐπιστήμαις, τὰς δὲ αἰσθήσεσιν ἑπομένας;", "st": "66c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἴσως.", "st": "66c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἕκτῃ δ᾽ ἐν γενεᾷ, φησὶν Ὀρφεύς, καταπαύσατε κόσμον ἀοιδῆς: ἀτὰρ κινδυνεύει καὶ ὁ ἡμέτερος λόγος ἐν ἕκτῃ καταπεπαυμένος εἶναι κρίσει. τὸ δὴ μετὰ", "st": "66c"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ταῦθ᾽ ἡμῖν οὐδὲν λοιπὸν πλὴν ὥσπερ κεφαλὴν ἀποδοῦναι τοῖς εἰρημένοις.", "st": "66d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> οὐκοῦν χρή.", "st": "66d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ἴθι δή, τὸ τρίτον τῷ σωτῆρι τὸν αὐτὸν διαμαρτυράμενοι λόγον ἐπεξέλθωμεν.", "st": "66d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ποῖον δή;", "st": "66d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> Φίληβος τἀγαθὸν ἐτίθετο ἡμῖν ἡδονὴν εἶναι πᾶσαν καὶ παντελῆ.", "st": "66d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> τὸ τρίτον, ὦ Σώκρατες, ὡς ἔοικας, ἔλεγες ἀρτίως τὸν ἐξ ἀρχῆς ἐπαναλαβεῖν δεῖν λόγον.", "st": "66d"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ναί, τὸ δέ γε μετὰ τοῦτο ἀκούωμεν. ἐγὼ γὰρ δὴ κατιδὼν ἅπερ νυνδὴ διελήλυθα, καὶ δυσχεράνας τὸν Φιλήβου λόγον οὐ μόνον ἀλλὰ καὶ ἄλλων πολλάκις μυρίων, εἶπον ὡς ἡδονῆς γε νοῦς εἴη μακρῷ βέλτιόν τε καὶ ἄμεινον τῷ τῶν ἀνθρώπων βίῳ.", "st": "66e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἦν ταῦτα.", "st": "66e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> ὑποπτεύων δέ γε καὶ ἄλλα εἶναι πολλὰ εἶπον ὡς εἰ φανείη τι τούτοιν ἀμφοῖν βέλτιον, ὑπὲρ τῶν δευτερείων νῷ πρὸς ἡδονὴν συνδιαμαχοίμην, ἡδονὴ δὲ καὶ δευτερείων στερήσοιτο.", "st": "66e"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> εἶπες γὰρ οὖν.", "st": "67a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μετὰ ταῦτά γε πάντων ἱκανώτατα τούτοιν οὐδέτερον ἱκανὸν ἐφάνη.", "st": "67a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀληθέστατα.", "st": "67a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν παντάπασιν ἐν τούτῳ τῷ λόγῳ καὶ νοῦς ἀπήλλακτο καὶ ἡδονὴ μή τοι τἀγαθόν γε αὐτὸ μηδ᾽ ἕτερον αὐτοῖν εἶναι, στερομένοιν αὐταρκείας καὶ τῆς τοῦ ἱκανοῦ καὶ τελέου δυνάμεως;", "st": "67a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ὀρθότατα.", "st": "67a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> φανέντος δέ γε ἄλλου τρίτου κρείττονος τούτοιν ἑκατέρου, μυρίῳ γ᾽ αὖ νοῦς ἡδονῆς οἰκειότερον καὶ προσφυέστερον πέφανται νῦν τῇ τοῦ νικῶντος ἰδέᾳ.", "st": "67a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> πῶς γὰρ οὔ;", "st": "67a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν πέμπτον κατὰ τὴν κρίσιν, ἣν νῦν ὁ λόγος ἀπεφήνατο, γίγνοιτ᾽ ἂν ἡ τῆς ἡδονῆς δύναμις.", "st": "67a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἔοικεν.", "st": "67a"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> πρῶτον δέ γε οὐδ᾽ ἂν οἱ πάντες βόες τε καὶ ἵπποι καὶ τἆλλα σύμπαντα θηρία φῶσι τῷ τὸ χαίρειν διώκειν: οἷς πιστεύοντες, ὥσπερ μάντεις ὄρνισιν, οἱ πολλοὶ κρίνουσι τὰς ἡδονὰς εἰς τὸ ζῆν ἡμῖν εὖ κρατίστας εἶναι, καὶ τοὺς θηρίων ἔρωτας οἴονται κυρίους εἶναι μάρτυρας μᾶλλον ἢ τοὺς τῶν ἐν μούσῃ φιλοσόφῳ μεμαντευμένων ἑκάστοτε λόγων.", "st": "67b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> ἀληθέστατα, ὦ Σώκρατες, εἰρῆσθαί σοι νῦν ἤδη φαμὲν ἅπαντες.", "st": "67b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ ἀφίετέ με;", "st": "67b"}, {"sp": "N", "t": "<span class=\"speaker-label\">Πρώταρχος:<\/span> σμικρὸν ἔτι τὸ λοιπόν, ὦ Σώκρατες: οὐ γὰρ δήπου σύ γε ἀπερεῖς πρότερος ἡμῶν, ὑπομνήσω δέ σε τὰ λειπόμενα.", "st": "67b"}],[]);})();